  nebuliserTimer = object : CountDownTimer(tmv!!, 1000) {                    override fun onTick(milliSec: Long) {                        nebulisercount.text = "" + String.format(                            FORMAT,                            TimeUnit.MILLISECONDS.toMinutes(milliSec),                            TimeUnit.MILLISECONDS.toSeconds(milliSec) - TimeUnit.MINUTES.toSeconds(                                TimeUnit.MILLISECONDS.toMinutes(milliSec)                            )                        )                    }                    override fun onFinish() {                        mDashBoardViewModel.updateIsNebulizerActive(false)                        imageViewNebuliser.visibility = View.GONE                        nebulisercount.visibility = View.GONE                        nebuliserPanel.isEnabled = false                        nebuliserPanel.setBackgroundColor(                            ContextCompat.getColor(                                this@DashBoardActivity, R.color.black                            )                        )                        communicationService?.send(getString(R.string.cmd_vent_nebuliser) + "000")//                        sendMessageToServer(getString(R.string.cmd_vent_nebuliser) + "000")                        nebuliserTimer?.cancel()                    }                }.start()            }            "5009" -> {                mDashBoardViewModel.updateIsNebulizerActive(false)                nebuliserTimer?.onFinish()                addEvents("Mesh Nebuliser stopped", prefManager?.readUHID().toString())            }            // Handle other ACK codes if needed            else -> {                // Handle unknown ACK codes or future ACK codes                Log.i("SocketClientCode", "Received unknown ACK: $ackCode")            }        }    }    private fun handleMessage(message: String) {        // Process regular messages here        val cleanedMessage = message.substring(2, message.length - 1)        val dataParts = cleanedMessage.split(",")        if (dataParts.size >= 2) {            val xValue = dataParts[1].toFloat()            etco2Data = dataParts[0].toFloat()            cuffPressure = dataParts[2].toFloat()            Log.i(                "CHECK_DATA_VALUE",                "X VALUE" + xValue.toString() + "EtCo2" + etco2Data.toString() + "Cuff Pressure" + cuffPressure.toString()            )//            updatePrimaryModelActualValue(LBL_ETCO2,etco2Data)            updatePrimaryModelActualValue(LBL_CuffPressure, cuffPressure)        }    }//    private fun startReadingFromServer() {//        Thread {//            try {//                val reader = BufferedReader(InputStreamReader(inputStream))//                while (true) { // Continue reading in a loop//                    val message = reader.readLine()////                    Log.d("SocketClient", "Received message: $message")//                    if (message != null) {//                        runOnUiThread {////                            val cleanedMessage = message.substring(2, message.length - 1)//                            val dataParts = cleanedMessage.split(",")//                            if (dataParts.size >= 2) {//                                val xValue = dataParts[1].toFloat()//                                etco2Data = dataParts[0].toFloat()//                                cuffPressure = dataParts[2].toFloat()//                                Log.i("CHECK_DATA_VALUE","X VALUE" + xValue.toString() + "EtCo2" + etco2Data.toString() + "Cuff Pressure" + cuffPressure.toString())//                                updatePrimaryModelActualValue(LBL_ETCO2,etco2Data)//                                updatePrimaryModelActualValue(LBL_CuffPressure,cuffPressure)//                            }//                        }//                    } else {//                        // Connection might have been closed by the server