FF_LEAKAGE_DETECTED)        intentFilter.addAction(IntentFactory.ACTION_CUFF_LEAKAGE_RESOLVED)        intentFilter.addAction(IntentFactory.ACTION_FLOW_SENSOR_OCCLUSION_DETECTED)        intentFilter.addAction(IntentFactory.ACTION_FLOW_SENSOR_OCCLUSION_RESOLVED)        intentFilter.addAction(IntentFactory.ACTION_EXPIRE_TIME_OUT_OF_RANGE)        intentFilter.addAction(IntentFactory.ACTION_POWER_OFF)        intentFilter.addAction(IntentFactory.ACTION_POWER_ON)        intentFilter.addAction(IntentFactory.ACTION_EXPIRE_TIME_UNDER_RANGE)        intentFilter.addAction(IntentFactory.ACTION_VENT_PARAM_LIMIT_UNDERFLOW)        intentFilter.addAction(IntentFactory.ACTION_VENT_PARAM_LIMIT_OVERFLOW)        intentFilter.addAction(IntentFactory.ACTION_KNOB_CHANGE)        intentFilter.addAction(IntentFactory.ACTION_KNOB_X)        intentFilter.addAction(IntentFactory.ACTION_MUTE_UNMUTE)        intentFilter.addAction(IntentFactory.ACTION_HOME)        intentFilter.addAction(IntentFactory.ACTION_LOCK)        intentFilter.addAction(IntentFactory.ACTION_INSPIRATORY_HOLD)        intentFilter.addAction(IntentFactory.ACTION_EXPIRATORY_HOLD)        intentFilter.addAction(IntentFactory.ACTION_OXYGEN_100)        intentFilter.addAction(IntentFactory.ACTION_NEBULISER)        intentFilter.addAction(IntentFactory.ACTION_MANUAL_BREATH)        intentFilter.addAction(IntentFactory.ACTION_SENSOR_AVAILABILITY_RESPONSE)        intentFilter.addAction(IntentFactory.ACTION_SENSOR_CALIBRATION_RESPONSE)        intentFilter.addAction(IntentFactory.ACTION_CHECK_USB_CONNECTIONS)        intentFilter.addAction(Intent.ACTION_SHUTDOWN)        intentFilter.addAction(Intent.ACTION_REBOOT)        intentFilter.addAction(IntentFactory.ACTION_ETHERNET_CONNECT)        intentFilter.addAction(IntentFactory.ACTION_ETHERNET_DISCONNECT)        // ONLY FOR TESTING        if (BuildConfig.DEBUG) {            intentFilter.addAction(IntentFactory.ACTION_HEATSENSE_STATUS_AVAILABLE)        }        return intentFilter    }    var map: MutableMap<String, String> = java.util.LinkedHashMap()    // this is the broadcast receiver for the app    fun updateUsbCheckView(hid: Boolean, venti: Boolean) {        Log.i("check_usb_connections", "run usb connection")        if (!hid) cvHideConnectionDash.setImageResource(R.color.red)        else cvHideConnectionDash.setImageResource(R.color.ack_green)        if (!venti) cvVentilatorConnectionDash.setImageResource(R.color.red)        else cvVentilatorConnectionDash.setImageResource(R.color.ack_green)    }//  private fun updateServiceLayout(image: Int, color: Int) {//      serviceLayoutDash.setBackgroundResource(color)//      serviceIconDash.setImageResource(image)//  }    private fun updateLogsEventsScrollState(data: String) {        when (data) {            PREFIX_PLUS -> logsDialogFragment?.scrollEventsForward()            PREFIX_MINUS -> logsDialogFragment?.scrollEventsBackward()        }    }    private fun updateLogsAlarmsScrollState(data: String) {        when (data) {            PREFIX_PLUS -> logsDialogFragment?.scrollAlarmsForward()            PREFIX_MINUS -> logsDialogFragment?.scrollAlarmsBackward()        }    }    private fun updateLogsTendsScrollState(data: String) {        when (data) {            PREFIX_PLUS -> logsDialogFragment?.scrollTrendsForward()            PREFIX_MINUS -> logsDialogFragment?.scrollTrendsBack()        }    }    private fun onDeviceConnect() {        Log.i("handshake_check", "onDevice Connect")        // FOR ALLOWING SCREEN AUTO LOCK        AppUtils.keepScreenAlive(this@DashBoardActivity, true)        communicationService?.takeIf { it.isPortsConnected }?.apply {            validateConnectionState()            if (!isReadingFromConnection) {                Log.i(                    "SERVICE_CHECK",                    "connection status = $isPortsConnected during DEVICE_CONNECTED check"                )                isReadingFromConnection = true                startReading()            }        } ?: kotlin.run {}    }    private fun onDeviceDisconnect() {        Log.i("handshake_check", "onDevice Disconnect")        // FOR ALLOWING SCREEN AUTO LOCK        AppUtils.keepScreenAlive(this@DashBoardActivity, false)        stopHandshaking()        if (isReadingFromConnection) {            communicationService?.apply {                stopReading()            }            isReadingFromConnection = false        }    }    private fun validateConnectionState() {        communicationService?.takeIf { it.isPortsConnected }?.apply {            startHandshakingWithThreadSafety()        } ?: kotlin.run {            AppUtils.keepScreenAlive(this@DashBoardActivity, false)        }    }    /*  * This method will start handshaking countdown thread  */    private fun startHandshakingWithThreadSafety() {        Log.i("handshake_check", "in start handshaking thread safety")        Handler(Looper.getMainLooper()).post {            try {                startHandshaking()            } catch (e: Exception) {                e.printStackTrace()            }        }    }    private fun startHandshaking() {        Log.i("handshake_check", "in start handshaking")        communicationService?.takeIf { it.isPortsConnected }?.apply {            if (handshakingTask == null) handshakingTask = HandshakingTask(this)            if (handshakingTask?.isRunning == true) return            // case for knob data knob available            if (isForKnob == true) {                addEventsForDevelopers(                    "Start Handshaking For Knob Data Not Available During Ventilation Case",                    prefManager?.readUHID().toString()                )            }            else if (isForKnob == false) {                addEventsForDevelopers(                    "Start Handshaking For Spo2 Data Not Available During Ventilation Case",                    prefManager?.readUHID().toString()                )            }            else if (isForKnob == null) {                addEventsForDevelopers(                    "Start Handshaking For Crash During Ventilation Case",                    prefManager?.readUHID().toString()                )            }            Handler(Looper.getMainLooper()).postDelayed({                handshakingTask?.apply {                    start()                }            }, 100)        }    }    private fun stopHandshaking() {        isForKnob = null        handshakingTask?.stop()    }    // BroadCast Receiver Getting Data from IntentFactory    private val gattReceiver: BroadcastReceiver = object : BroadcastReceiver() {        override fun onReceive(context: Context, intent: Intent) {            intent.action?.apply {                when (this) {                    IntentFactory.ACTION_CHECK_USB_CONNECTIONS -> {                        val hid = intent.getBooleanExtra(USB_HID_DATA, false)                        val venti = intent.getBooleanExtra(USB_VENTILATOR_DATA, false)                        Log.i("check_usb_connections", "run usb connection")                        updateUsbCheckView(hid, venti)                    }                    UsbManager.ACTION_USB_DEVICE_ATTACHED -> {                        sendBroadcast(Intent(IntentFactory.ACTION_DEVICE_CONNECTED))                    }                    //Third threadCount                    IntentFactory.ACTION_GRAPH_LIMIT_CHANGE -> {                        val data = intent.getStringExtra(GRAPH_LIMITS)                        data?.takeIf { it.isNotEmpty() }?.apply {                            xMaxRangeGlobal = data.toDouble()                            CoroutineScope(Dispatchers.Main).launch {                                dataStoreManager?.saveXMaxValue(data.toDouble())                            }                            changeGraphXLimits()                        }                    }                    IntentFactory.ACTION_VENTILATOR_FAILURE_GENERATED -> {                        removeVentilatorFailureAlarm()                        addAlarm(                            ALARM_VENTILATOR_FAILURE,                            "UI InOp.",                            prefManager?.readUHID().toString()                        )                    }                    IntentFactory.ACTION_VENTILATOR_FAILURE_REMOVED -> {                        removeVentilatorFailureAlarm()                    }                    IntentFactory.ACTION_KNOB_FAILURE_GENERATED -> {                        removeKnobFailureAlarm()                        addAlarm(                            ALARM_KNOB_FAILURE,                            "Knob InOp.",                            prefManager?.readUHID().toString()                        )                    }                    IntentFactory.ACTION_KNOB_FAILURE_REMOVED -> {                        removeKnobFailureAlarm()                    }                    IntentFactory.ACTION_HANDSHAKE_TIMEOUT -> {                        Log.i("handshake_check", "ACTION HANDSHAKE TIMEOUT")                        // case for knob data knob available                        if (isForKnob == true) {                            addEventsForDevelopers(                                "Handshake Timeout For Knob Data Not Available During Ventilation Case",                                prefManager?.readUHID().toString()                            )                        }                        // case for spo2 data knob available                        else if (isForKnob == false) {                            addEventsForDevelopers(                                "Handshake Timeout For Spo2 Data Not Available During Ventilation Case",                                prefManager?.readUHID().toString()                            )                        } else if (isForKnob == null) {                            addEventsForDevelopers(                                "Handshake Timeout For Crash During Ventilation Case",                                prefManager?.readUHID().toString()                            )                        }                        stopHandshaking()                    }                    IntentFactory.ACTION_DATA_AVAILABLE -> {                        runOnUiThread {                            val data = intent.getStringExtra(VENTILATOR_DATA)                            data?.takeIf { it.isNotBlank() }?.apply {                                Log.i("VENT DATA", this)                                stpWindowHolder?.takeIf { it.isVisible }?.apply {                                    putResponse("\$AgVa : " + data.substring(0, data.length - 1))                                    Log.i("STP_CHECK", data)                                } ?: kotlin.run {                                    parseMap = raspiParser?.parser(data)                                    Log.i("VENT_DATA_PARSED", parseMap.toString())                                    parseMap?.apply {                                        setDataOnScreen(this)                                    }                                }                            }                        }                    }                    IntentFactory.ACTION_ACK_AVAILABLE -> {                        val ackValue = intent.getStringExtra(VENTILATOR_ACK)                        Log.i(TAG, "Broadcast  receiver receives ACK @$ackValue")                        val runningModeFromIntent = intent.getIntExtra(VENTILATOR_MODES, -1)                        ackValue?.takeIf {                            isNotEmpty()                        }?.apply { handleAcknowledgements(this) }                    }                    IntentFactory.ACTION_BATTERY_STATUS_AVAILABLE -> {//                        prefManager?.apply {//                            if (readDashBoardRunningTimeForService() > SERVICE_HOUR_LIMIT) {//                                updateServiceLayout(R.drawable.service_due_icon, R.color.ack_red)//                            } else if (readDashBoardRunningTimeForService() in (SERVICE_HOUR_LIMIT * 0.90).toLong()..SERVICE_HOUR_LIMIT) {//                                updateServiceLayout(//                                    R.drawable.service_due_icon_black, R.color.preCalib_amber//                                )//                            } else {//                                updateServiceLayout(R.drawable.service_not_due_icon, R.color.black)//                            }//                        }                        CoroutineScope(Dispatchers.Main).launch {                            if (countKnobData == 9 && dataStoreManager?.getKnobRebootStatusFlag()                                    ?.first() == true                            ) {                                dataStoreManager?.saveKnobRebootStatusFlag(false)                                sendBroadcast(Intent(IntentFactory.ACTION_KNOB_FAILURE_REMOVED))                                addEventsForDevelopers(                                    "Re-Initiate Handshake Due to Knob Data Not Available during ventilation",                                    prefManager?.readUHID().toString()                                )                                isForKnob = true                                onDeviceConnect()                            } else if (countKnobData == 9 && dataStoreManager?.getKnobRebootStatusFlag()                                    ?.first() == false                            ) {                                addEventsForDevelopers(                                    "Showing Alarm Due to Knob Data Not Available during ventilation",                                    prefManager?.readUHID().toString()                                )                                sendBroadcast(Intent(IntentFactory.ACTION_KNOB_FAILURE_GENERATED))                            }                            countKnobData++                        }                        val isPowerConnected = !ackVisibilities[0]                        val batteryLevel = intent.getIntExtra(VENTILATOR_BATTERY_LEVEL, -1)                        val batteryHealth = intent.getIntExtra(VENTILATOR_BATTERY_HEALTH, -1)                        val batteryRemainingTime = intent.getIntExtra(VENTILATOR_BATTERY_TTE, -1).let {                                if (it > 30) it                                else -1                            }                        mDashBoardViewModel.setVentBatteryHealth(batteryHealth)                        mDashBoardViewModel.setVentBatteryLevel(batteryLevel)                        mDashBoardViewModel.setVentBatteryRemainingTime(batteryRemainingTime)                    }                    IntentFactory.ACTION_SOFTWARE_VERSION_AVAILABLE -> {                        val data = intent.getStringExtra(VENTILATOR_SOFTWARE_VERSION)                        data?.let {                            Log.i("SOFTWARE_VERSION", it)                            prefManager?.setVentilatorSoftwareVersion(it)                            updateSoftwareVersion(it)                        }                    }                    IntentFactory.ACTION_MOTOR_LIFE_STATUS_AVAILABLE -> {                        val motorLifeHrs = intent.getIntExtra(VENTILATOR_MOTOR_LIFE, 0)                    }                    IntentFactory.ACTION_POWER_ON -> {                        if (alarmsMap.containsKey(POWER_BUTTON)) removeAlarm(POWER_BUTTON)                    }                    IntentFactory.ACTION_POWER_OFF -> {                        if (!alarmsMap.containsKey(POWER_BUTTON)) addAlarm(                            POWER_BUTTON,                            "Main Switch Off",                            prefManager?.readUHID().toString()                        )                    }                    IntentFactory.ACTION_MODE_SET -> {                        modeCode = intent.getIntExtra(VENTILATOR_MODES, -1)                        Log.i("MODE_CODE", "MODE  $modeCode")                        if (Configs.isValidVentilatorMode(this@DashBoardActivity, modeCode)) {                            layoutFreezeData.visibility = View.GONE                            if (modeCode == Configs.MODE_AUTO_VENTILATION) {                                Log.i("Venti_MODE_CHECKER", modeCode.toString())                                sendControlModeToVentilator(modeCode)                            } else {                                showStandbyControlFragment()                            }                        }                    }                    IntentFactory.ACTION_MODE_TYPE -> {                        typeMode = intent.getIntExtra(VENTILATOR_MODE_TYPE, 1)                        Log.i("MODE_TYPE_CHECK", "mode_type $typeMode")                    }                    IntentFactory.ACTION_DEVICE_DISCONNECTED -> {                        onDeviceDisconnect()                    }                    IntentFactory.ACTION_DEVICE_CONNECTED -> {                        onDeviceConnect()                    }                    IntentFactory.ACTION_INACTIVE -> {                        Log.i("INACTIVE_WATCH_DOG", "INACTIVE_ALERT")                    }                    IntentFactory.ACTION_VENT_PARAM_LIMIT_OVERFLOW -> {                        val lbl = intent.getStringExtra(ALERT_LABEL)                        val message = intent.getStringExtra(ALERT_MSG)                        lbl?.let {                            if (alarmsMap.containsKey(it)) return                            else {                                Log.i("OVERFLOW", "Added $it -> $message")                                message?.let { alarmMsg ->                                    addAlarm(                                        it,                                        alarmMsg,                                        (if (prefManager?.readUHID() == null) FIRST_FILTER_NAME else prefManager?.readUHID()).toString()                                    )                                }                                // for tile warning state                                primaryObservedParameterAdapter?.notifyDataSetChanged()                                secondaryObservedParameterAdapter?.notifyDataSetChanged()//                                validateErrorBar()                            }                        }                    }                    IntentFactory.ACTION_VENT_PARAM_LIMIT_UNDERFLOW -> {                        val lbl = intent.getStringExtra(ALERT_LABEL)//                        val message = intent.getStringExtra(ALERT_MSG)                        Log.i("UNDERFLOW", (alarmsMap.keys).toString())                        lbl?.let {                            if (alarmsMap.containsKey(it)) {                                removeAlarm(it)                                // for tile warning state                                primaryObservedParameterAdapter?.notifyDataSetChanged()                                secondaryObservedParameterAdapter?.notifyDataSetChanged()//                                validateErrorBar()                            }                        }                    }                    IntentFactory.ACTION_EXPIRE_TIME_OUT_OF_RANGE -> {                    }                    IntentFactory.ACTION_EXPIRE_TIME_UNDER_RANGE -> {                    }                    IntentFactory.ACTION_KNOB_CHANGE -> {                        val data = intent.getStringExtra(VENTILATOR_CONTROL_KNOB)                        data?.takeIf { it.isNotEmpty() }?.apply {                            countKnobData = 0                            CoroutineScope(Dispatchers.Main).launch {                                dataStoreManager?.saveKnobRebootStatusFlag(true)                            }                            if (data != "X") {                                if (DialogBoxFactory.dialogView != null && DialogBoxFactory.dialogView.isShowing) {                                    Log.i("KNOB_DATADASH", DialogBoxFactory.dialogView.toString())                                } else if (knobDialog?.isVisible == true) {                                    knobDialog?.takeIf { it.isVisible }?.apply {                                        updateWithTimeoutDebounce(data)                                    }                                } else if ((swappableLayout.visibility == View.VISIBLE)) {                                    updateSwappableLayout(this)                                } else if (alarmDialogFragment?.isVisible == true) {                                    alarmDialogFragment?.takeIf { it.isVisible }?.apply {                                        highlightViewWithFocus(data)                                    }                                } else if (graphicTooltipFragment?.isVisible == true) {                                    graphicTooltipFragment?.takeIf { it.isVisible }?.apply {                                        startTimeoutWithDebounce()                                    }                                } else if (controlDialogFragment?.isVisible == true) {                                    controlDialogFragment?.highlightViewWithFocus(data)                                } else if (systemDialogFragment?.isVisible == true) {                                    systemDialogFragment?.updateKnob(data)                                } else if (standbyControlFragment?.isVisible == true) {                                    standbyControlFragment?.highlightViewWithFocus(data)                                } else if (modeDialogFragment?.isVisible == true) {//                                    modeDialogFragment?.highlightViewWithFocus(data)                                } else if (maneuversDialogFragment?.isVisible == true) {                                    maneuversDialogFragment?.takeIf {                                        it.isVisible                                    }?.apply {                                        highlightViewWithFocus(data)                                    }                                } else if (logsDialogFragment?.isVisible == true) {                                    logsDialogFragment?.takeIf { it.isVisible }?.apply {//                                        highlightViewWithFocus(data)                                        if (knobDialog == null) {                                            if (mDashBoardViewModel.isLogsTrendsFragmentVisible.value == true) {                                                updateLogsTendsScrollState(data)                                            } else if (mDashBoardViewModel.isLogsEventsFragmentVisible.value == true) {                                                updateLogsEventsScrollState(data)                                            } else if (mDashBoardViewModel.isLogsAlarmFragmentVisible.value == true) {                                                updateLogsAlarmsScrollState(data)                                            }                                        }                                    }                                } else if (alarmDialogFragment?.isVisible == true) {                                    alarmDialogFragment?.takeIf { it.isVisible }?.apply {                                        highlightViewWithFocus(data)                                    }                                } else if (monitoringDialogFragment?.isVisible == true) {                                    monitoringDialogFragment?.takeIf { it.isVisible }?.apply {                                        highlightViewWithFocus(data)                                    }                                } else if (graphicsDialogFragment?.isVisible == true) {                                    graphicsDialogFragment?.takeIf { it.isVisible }?.apply {                                        highlightViewWithFocus(data)                                    }                                } else {                                    highlightViewWithFocus(this)                                }                            } else {                                if (DialogBoxFactory.dialogView != null && DialogBoxFactory.dialogView.isShowing) {                                    Log.i("KNOB_DATADASH", DialogBoxFactory.dialogView.toString())                                } else if (systemDialogFragment?.isVisible == true) {                                    systemDialogFragment?.takeIf { it.isVisible }?.apply {                                        updateXValue(data)                                    }                                }                            }                        }                    }                    IntentFactory.ACTION_MUTE_UNMUTE -> {                        Log.i("testing", "in Mute")                        val data = intent.getStringExtra(MUTE_UNMUTE_RESPONSE)                        FileLogger.d(this@DashBoardActivity, "Mute unmute button signal : $data")                        alarmPanel.callOnClick()                    }                    // || readLastVentMode() != MODE_NIV_CPAP || readLastVentMode() != MODE_NIV_BPAP                    IntentFactory.ACTION_NEBULISER -> {                        if (!isLocked) {                            when (prefManager?.readLastVentMode()) {                                MODE_NIV_CPAP, MODE_NIV_BPAP, MODE_HFNC -> {                                    ToastFactory.custom(context, "Nebuliser not available")                                }                                else -> {                                    Log.i("CHECK_LOG", "it is running")                                    //Fifth threadCount                                    CoroutineScope(Dispatchers.Main).launch {                                        if (prefManager?.readCurrentUid() != PatientProfile.TYPE_NEONAT                                        ) {                                            if (dataStoreManager?.getNebulizerCheck()                                                    ?.first() == true || VentilatorApp.isSocketConnected                                            ) {                                                isFromKnob = NEBULIZER                                                if (ACCESS_NEBULISER_AVAILABLE) {                                                    if (maneuversDialogFragment == null) {                                                        maneuversDialogFragment =                                                            ManeuversDialogFragment.newInstance(                                                                heightSize,                                                                widthSize,                                                                isFromKnob,                                                                this@DashBoardActivity,                                                                communicationService                                                            )                                                        currentFragment = maneuversDialogFragment                                                    }                                                    maneuversDialogFragment.apply {                                                        if (this?.isVisible == true) {                                                            TastyToasty.yellow(                                                                context,                                                                "Please close the maneuversDialogFragment for launching the nebulizer",                                                                R.drawable.ic_info_small                                                            ).show();                                                        } else {                                                            maneuversDialogFragment?.let {                                                                supportFragmentManager.apply {                                                                    beginTransaction().replace(                                                                        R.id.dashboardFragment_nav_container,                                                                        it,                                                                        isFromKnob                                                                    ).commitNow()                                                                }                                                            }                                                        }                                                    }                                                    checkDialogPresence()                                                    ACCESS_NEBULISER_AVAILABLE = false                                                    Handler(Looper.getMainLooper()).postDelayed({                                                        ACCESS_NEBULISER_AVAILABLE = true                                                    }, 1000)                                                }                                            } else ToastFactory.custom(                                                context,                                                "No Oxygen supply connected"                                            )                                        } else {                                            ToastFactory.custom(ctx, "Nebuliser not available")                                        }                                    }                                }                            }                        } else {                            DialogBoxFactory.dismissDialogs()                            DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)                        }                    }                    IntentFactory.ACTION_OXYGEN_100 -> {                        Log.i("ACTION_HARDWARE_BUTTON", "Oxygen 100% button is clicked.........")                        if (!isLocked) {                            sendO2FullCommandToVentilator()                            if (!isOxygenRunning) {                                startFiO2()                                isOxygenRunning = true                            } else {                                stopFiO2()                                isOxygenRunning = false                            }                        } else {                            DialogBoxFactory.dismissDialogs()                            DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)                        }                    }                    IntentFactory.ACTION_HOME -> {                        // AppUtils.HOME=true                        Log.i("ACTION_HARDWARE_BUTTON", "Home button is clicked.........")                        if (ACCESS_HOME_AVAILABLE) {                            hideAllAlertDialogBox()                            hideKnobViews()                            // hideModeConfirmation()                            hideAllDialogFragment()                            ACCESS_HOME_AVAILABLE = false                            Log.i("ACTION_HARDWARE_BUTTON", "Home button is clicked.........")                            Handler(Looper.getMainLooper()).postDelayed({                                ACCESS_HOME_AVAILABLE = true                            }, 1000)                        }                    }                    IntentFactory.ACTION_LOCK -> {                        isLocked = !isLocked                        primaryActionAdapter?.notifyDataSetChanged()                    }                    IntentFactory.ACTION_INSPIRATORY_HOLD -> {                        if (!isLocked) {                            if (prefManager?.readLastVentMode() == MODE_NIV_BPAP || prefManager?.readLastVentMode() == MODE_NIV_NBPAP || prefManager?.readLastVentMode() == MODE_NIV_CPAP || prefManager?.readLastVentMode() == MODE_NC_IPPV || prefManager?.readLastVentMode() == MODE_NIV_NCPAP) {                                isFromKnob = INSPIRATORY_HOLD                                DialogBoxFactory.dismissDialogs()                                DialogBoxFactory.showNeonateSensorDialog(                                    this@DashBoardActivity, "Manuevers not available"                                )                            } else if (prefManager?.readCurrentUid() == PatientProfile.TYPE_NEONAT || prefManager?.readLastVentMode() == MODE_HFNC) {                                isFromKnob = INSPIRATORY_HOLD                                DialogBoxFactory.dismissDialogs()                                DialogBoxFactory.showNeonateSensorDialog(                                    this@DashBoardActivity, "Manuevers not available"                                )                            } else {                                isFromKnob = INSPIRATORY_HOLD                                if (ACCESS_INSPIRATORY_AVAILABLE) {                                    if (maneuversDialogFragment == null) {                                        maneuversDialogFragment =                                            ManeuversDialogFragment.newInstance(                                                heightSize,                                                widthSize,                                                isFromKnob,                                                this@DashBoardActivity,                                                communicationService                                            )                                        currentFragment = maneuversDialogFragment                                    }                                    maneuversDialogFragment.apply {                                        if (this?.isVisible == true) {                                            ToastFactory.custom(                                                context,                                                "Please close the maneuvers for launching the inspiratory hold"                                            )                                        } else {                                            maneuversDialogFragment?.let {                                                supportFragmentManager.apply {                                                    beginTransaction().replace(                                                        R.id.dashboardFragment_nav_container,                                                        it,                                                        ManeuversDialogFragment.TAG                                                    ).commitNow()                                                }                                            }                                        }                                    }                                    checkDialogPresence()                                    ACCESS_INSPIRATORY_AVAILABLE = false                                    Handler(Looper.getMainLooper()).postDelayed({                                        ACCESS_INSPIRATORY_AVAILABLE = true                                    }, 1000)                                }                            }                        } else {                            DialogBoxFactory.dismissDialogs()                            DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)                        }                    }                    IntentFactory.ACTION_EXPIRATORY_HOLD -> {                        if (!isLocked) {                            // AppUtils.EXPIRATORY=true                            if (prefManager?.readLastVentMode() == MODE_NIV_BPAP || prefManager?.readLastVentMode() == MODE_NIV_NBPAP || prefManager?.readLastVentMode() == MODE_NIV_CPAP || prefManager?.readLastVentMode() == MODE_NC_IPPV || prefManager?.readLastVentMode() == MODE_NIV_NCPAP) {                                isFromKnob = EXPIRATORY_HOLD                                DialogBoxFactory.dismissDialogs()                                DialogBoxFactory.showNeonateSensorDialog(                                    this@DashBoardActivity, "Manuevers not available"                                )                            } else if (prefManager?.readCurrentUid() == PatientProfile.TYPE_NEONAT || prefManager?.readLastVentMode() == MODE_HFNC) {                                isFromKnob = EXPIRATORY_HOLD                                DialogBoxFactory.dismissDialogs()                                DialogBoxFactory.showNeonateSensorDialog(                                    this@DashBoardActivity, "Manuevers not available"                                )                            } else {                                isFromKnob = EXPIRATORY_HOLD                                if (ACCESS_EXPIRATORY_AVAILABLE) {                                    if (maneuversDialogFragment == null) {                                        maneuversDialogFragment =                                            ManeuversDialogFragment.newInstance(                                                heightSize,                                                widthSize,                                                isFromKnob,                                                this@DashBoardActivity,                                                communicationService                                            )                                        currentFragment = maneuversDialogFragment                                    }                                    maneuversDialogFragment.apply {                                        if (this?.isVisible == true) {                                            ToastFactory.custom(                                                context,                                                "Please close the maneuversDialogFragment for launching the expiratory hold"                                            )                                        } else {                                            maneuversDialogFragment?.let {                                                supportFragmentManager.apply {                                                    beginTransaction().replace(                                                        R.id.dashboardFragment_nav_container,                                                        it,                                                        ManeuversDialogFragment.TAG                                                    ).commitNow()                                                }                                            }                                        }                                    }                                    checkDialogPresence()                                    ACCESS_EXPIRATORY_AVAILABLE = false                                    Handler(Looper.getMainLooper()).postDelayed({                                        ACCESS_EXPIRATORY_AVAILABLE = true                                    }, 1000)                                }                            }                        } else {                            DialogBoxFactory.dismissDialogs()                            DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)                        }                    }                    IntentFactory.ACTION_MANUAL_BREATH -> {                        //  AppUtils.MANUALBREATH=true                        Log.i("ACTION_HARDWARE_BUTTON", "Manual breath button is clicked.........")                        if (!isLocked) {                            if (ACCESS_MANUALBREATH_AVAILABLE) {                                communicationService?.takeIf { it.isPortsConnected }?.apply {                                    send(getString(R.string.cmd_vent_breath))                                }                                addEvents(                                    "Manual Breath requested",                                    prefManager?.readUHID().toString()                                )                                ACCESS_MANUALBREATH_AVAILABLE = false                                Handler(Looper.getMainLooper()).postDelayed({                                    ACCESS_MANUALBREATH_AVAILABLE = true                                }, 1000)                            }                        } else {                            DialogBoxFactory.dismissDialogs()                            DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)                        }                    }                    IntentFactory.ACTION_SELF_TEST_STATUS_AVAILABLE -> {                        val stpResponse = intent.getIntExtra(VENTILATOR_SELF_TEST_STATUS, 0)                        if (stpResponse == 7) {                            showSelfTestWindow()                            val data = intent.getStringExtra(VENTILATOR_DATA)                            data?.let {                                Log.i("VENT DATA", data)                                stpWindowHolder?.apply {                                    putResponse(it)                                }                            }                        } else {                            dismissSelfTestWindow()                        }                    }                    IntentFactory.ACTION_SENSOR_AVAILABILITY_RESPONSE -> {                        intent.getStringArrayListExtra(SENSOR_ANALYSIS)?.takeIf { it.isNotEmpty() }                            ?.apply {                                Log.i("SENSOR_ANALYSE_CHECK", this.toString())                                prefManager?.setSensorExhaleFlow(this[0].toInt())                                prefManager?.setSensorInhaleFlow(this[1].toInt())                                prefManager?.setSensorLowFlowO2(this[2].toInt())                                prefManager?.setSensorHighFlowO2(this[3].toInt())                                prefManager?.setSensorSPO2(this[5].toInt())                                prefManager?.setSensorTemp(this[6].toInt())                                prefManager?.setSensorHighPressureO2Line(this[7].toInt())                                prefManager?.setSensorInspPressure(this[10].toInt())                                prefManager?.setSensorExpPressure(this[11].toInt())                            }                    }                    IntentFactory.ACTION_SENSOR_CALIBRATION_RESPONSE -> {                        val status = intent.getStringExtra(VENTILATOR_SENSOR_CALIBRATION_TAG)                        val calibResult =                            intent.getIntExtra(VENTILATOR_SENSOR_CALIBRATION_RESULT, -1)                        Log.i("CALIBCHECK", "Sensor = $status calibrated with value = $calibResult")                        try {                            status?.apply {                                if (calibResult == -1) {                                    Log.i("CALIBCHECK", "Sensor calibration status not available")                                    return                                }                                val calibration = SensorCalibration(calibResult)                                Log.i(                                    "CALIBCHECK",                                    "Sensor = $status calibrated with value = $calibResult"                                )                                Log.i("CALIBCHECK", "Sensor calib = $calibration")                                when (this) {                                    TAG_SENSOR_EXP_FLOW -> {                                        prefManager?.setExpFlowCalibration(calibration)                                    }                                    TAG_SENSOR_INSP_FLOW -> {                                        prefManager?.setInspFlowCalibration(calibration)                                    }                                    TAG_SENSOR_OXYGEN -> {//                                        prefManager?.setOxygenCalibration(calibration)                                    }                                    TAG_SENSOR_PRESSURE -> {                                        prefManager?.setPresserCalibration(calibration)                                    }                                    TAG_SENSOR_TURBINE -> {                                        prefManager?.setTurbineCalibration(calibration)                                    }                                    else -> {                                        Log.i("CALIBCHECK", "Invalid sensor tag for calibration")                                    }                                }                                Log.i("CALIBCHECK", "out of when")                                systemDialogFragment?.getTestCalibFragment()                                    ?.updateSensorCalibrationStatus()                                systemDialogFragment?.getaAdvancedFragment()                                    ?.updateSensorCalibrationStatus()                            }                        } catch (e: Exception) {                            e.printStackTrace()                        }                    }                }            }        }    }    fun changeGraphXLimits() {        when (prefManager?.readGraphParentType()) {            parent