n = null        }    }    private val startNewVentilationListener = object : OnStartVentilationListener {        override fun onStart() {            layoutFreezeData.visibility = View.VISIBLE            graphicTooltipFragment?.takeIf { it.isVisible }?.apply {                TastyToasty.orange(                    this@DashBoardActivity,                    "Please close the graphical tooltip to start ventilation",                    R.drawable.ic_info_small                ).show();            } ?: kotlin.run { sendControlModeToVentilator(modeCode) }        }    }    private fun showKnobDialogForStandbyControl(        parameterModel: KnobParameterModel,        encoderValue: EncoderValue,        parameterList: MutableList<ControlParameterModel>,        pos: Int,        type: ControlSettingType    ) {        hideKnobDialog()        knobDialog = KnobDialog.newInstance(            onKnobPressListener = object : OnKnobPressListener {                override fun onKnobPress(previousValue: Float, newValue: Float) {                    isKnobPressedForControlTile = true                    parameterList.also {                        val lbl = it[pos].ventKey                        val unit = it[pos].units                        it.filter { it.ventKey == lbl }.takeIf { it.isNotEmpty() }?.getOrNull(0)                            ?.apply {                                this.reading = supportPrecision(lbl, newValue)                                updateParameter(lbl, newValue.toString())                                prefManager?.apply {                                    if (type == Configs.ControlSettingType.ADVANCED) {                                        advancedControlParameterList?.filter { it.ventKey == lbl }                                            ?.takeIf { it.isNotEmpty() }?.getOrNull(0)?.apply {                                                this.reading = supportPrecision(lbl, newValue)                                            }                                    }                                }                            }                        addEvents(                            "Set $lbl from ${                                supportPrecision(lbl, previousValue)                            }  $unit to $newValue $unit", prefManager?.readUHID().toString()                        )                        testingConditonMap.put(lbl, newValue)                    }.forEach {                        it.isIsselected = false                    }                    standbyControlFragment?.notifyParameterAdapter()                    Log.i("STANDBYCONTROL_CHECK", "ARR[$pos] -> $${parameterList[pos].reading}")                    hideKnobViews()                    hideSystemUI()                }            },            onLimitChangeListener = object : OnLimitChangeListener {                override fun onLimitChange(                    previousValue: Float, newValue: Float                ) {                    parameterList.getOrNull(pos)?.let { param ->                        val model = standbyControlFragment?.updateParamVal(                            param.ventKey, newValue.toString(), type                        )                        model?.let { updateGraphictoolTip(it) }                    }                }            },            onTimeoutListener = object : OnDismissDialogListener {                override fun handleDialogClose() {                    hideSystemUI()                    checkDialogPresence()                    parameterList.forEach {                        it.isIsselected = false                    }                    renderStandbyControlParameterTilesViaPreference(parameterList[pos].ventKey)                }            },            onCloseListener = object : OnDismissDialogListener {                override fun handleDialogClose() {                    parameterList.forEach {                        it.isIsselected = false                    }                    renderStandbyControlParameterTilesViaPreference(parameterList[pos].ventKey)                }            },            parameterModel = parameterModel,            encoderValue = encoderValue,        ).also {            supportFragmentManager.apply {                beginTransaction().replace(                    R.id.knob_nav_container, it, "FromDashBoardActivity"                ).commitNow()            }            it.startTimeoutWithDebounce()            knob_nav_container.visibility = View.VISIBLE        }    }    private fun showKnobDialog(parameterModel: KnobParameterModel, encoderValue: EncoderValue) {        hideKnobDialog()        knobDialog = KnobDialog.newInstance(            onKnobPressListener = this,            onLimitChangeListener = this,            onTimeoutListener = knobViewsCloseListner,            onCloseListener = object : OnDismissDialogListener {                override fun handleDialogClose() {                    renderControlParameterTilesViaPreference()                }            },            parameterModel = parameterModel,            encoderValue = encoderValue,        ).also {            supportFragmentManager.apply {                beginTransaction().replace(                    R.id.knob_nav_container, it, "FromDashBoardActivity"                ).commitNow()            }            it.startTimeoutWithDebounce()            knob_nav_container.visibility = View.VISIBLE        }    }    private fun hideKnobDialog() {        Log.i("masoomzasd", "2")        if (knobDialog?.isVisible == true) {            knob_nav_container.visibility = View.GONE            //simv_nav_container.visibility = View.GONE            knobDialog?.let {                supportFragmentManager.beginTransaction().remove(it).commitNow()                knobDialog = null            }        }    }    private fun showGraphicTooltip(modeCode: Int) {        hideGraphicTooltip()        prefManager?.readVentilationMode()?.run {            GeneralGraphicalToolTipFragment.newInstance(                height = heightSize,                width = widthSize,                modeCode,                false,                knobViewsCloseListner            )        }?.apply {            supportFragmentManager.beginTransaction()                .replace(R.id.simv_nav_container, this, "FromDashBoardActivity").commitNow()            graphicTooltipFragment = this            this.startTimeoutWithDebounce()        }        graphicTooltipFragment?.let {            isGraphicalToolTipVisible = true        }        simv_nav_container.visibility = View.VISIBLE    }    private fun hideGraphicTooltip() {        Log.i("masoomzasd", "1")        if (graphicTooltipFragment?.isVisible == true) {            simv_nav_container.visibility = View.GONE            graphicTooltipFragment?.let {                supportFragmentManager.beginTransaction().remove(it).commitNow()                isGraphicalToolTipVisible = false                graphicTooltipFragment = null            }        }    }    private fun showKnobViews(parameterModel: KnobParameterModel, encoderValue: EncoderValue) {        closeSwappableLayout()        showGraphicTooltip(prefManager?.readVentilationMode()!!)        showKnobDialog(parameterModel, encoderValue)        // start handler    }    private fun showKnobViewsForStandbyControls(        parameterModel: KnobParameterModel,        encoderValue: EncoderValue,        parameterList: MutableList<ControlParameterModel>,        pos: Int,        type: ControlSettingType,    ) {        closeSwappableLayout()        showGraphicTooltip(modeCode)        showKnobDialogForStandbyControl(parameterModel, encoderValue, parameterList, pos, type)    }    private fun hideKnobViews() {        Log.i("CHECKKNOBVIEW", "working fine")        Log.i("value1231", "3")        normaliseParameterTiles()        hideKnobDialog()        hideGraphicTooltip()    }    private fun updateSwappableLayout(data: String) {        if (swappableLayout.isVisible) {            swappableAdapter?.apply {                when (data) {                    PREFIX_PLUS -> {                        setSelectionForward()                        swappableRecyclerView.smoothScrollToPosition(getSelection())                    }                    PREFIX_MINUS -> {                        setSelectionBackward()                        swappableRecyclerView.smoothScrollToPosition(getSelection())                    }                    PREFIX_AND -> {                        Log.i("vlaue_osdada", "in and")                        swapWithCurrentSelection()                    }                }            }        }    }    private fun updateSoftwareVersion(softVersion: String?) {        systemDialogFragment?.takeIf { it.isVisible }?.apply {            Handler(Looper.getMainLooper()).postDelayed({                setSoftWareUpdate(softVersion)            }, 1000)        }    }    private fun handleAcknowledgements(ackValue: String) {        val isAckValid = ackValue.startsWith(Configs.PREFIX_ACK)        if (!isAckValid) return        if (AlarmConfiguration.isCycleCheckRequired(ackValue) && isCycleCheckActivated()) return        if (alarmsMap.containsKey(ackValue)) {            Log.i(ACK_TAG, "IGNORING EXISTING ACK $ackValue")            return        } else {            val ackMsg = MessageFactory.getAckMessage(this, ackValue, prefManager?.readLastVentMode())            when (AlarmConfiguration.getAckType(ackValue)) {                AckType.ACK -> {                    if (ackValue.contains("ACK0804") || ackValue.contains("ACK0805")) neoSensorView.setImageResource(                        R.drawable.neonate_icon_disconnected_img                    )                    val ackCode = ackValue.replace("ACK", "").toIntOrNull()                    if ((prefManager?.readCurrentUid() == PatientProfile.TYPE_NEONAT && apneaActive) && ackValue.contains(                            "ACK0786"                        )                    ) {                        lastAvgLeak?.let {                            if (it >= 80) {                                addAlarm(                                    ackValue, ackMsg, prefManager?.readUHID().toString()                                )                            } else {                                Log.i("PATIENT_DISCONNECTION", "ALARM: Not Added Leakege below 80%")                            }                        }                    } else {                        addAlarm(                            ackValue, ackMsg, prefManager?.readUHID().toString()                        )                    }                    ackCode?.let { ackVisibilities[it] = true }                }                AckType.NACK -> {                    if (ackValue.contains("ACK0814") || ackValue.contains("ACK0815")) neoSensorView.setImageResource(                        R.drawable.neonate_icon                    )                    val correspondingAckValue = AlarmConfiguration.getAckFor(ackValue)                    correspondingAckValue?.let {                        val nackCode = it.replace("ACK", "").toIntOrNull()                        removeAlarm(it)                        nackCode?.apply { ackVisibilities[this] = false }                    }                }                AckType.INVALID_ACK -> {                    Log.i(ACK_TAG, "Invalid (untracked) ack code found in handleAcknowledgement")                    return                }                AckType.OP_ACK -> {}            }        }        when (ackValue) {            ACK_CODE_5181 -> {                DialogBoxFactory.showNeonateSensorDialog(ctx, "Et-Cuff started")            }            //replacement of ACK_CODE_2            ACK_CODE_5090 -> {                ackVisibilities[5090] = true                Log.d("ackvalueInsp", ackVisibilities[5090].toString())            }            ACK_CODE_5091 -> {                ackVisibilities[5091] = true            }            ACK_CODE_5092 -> {                ackVisibilities[5092] = true            }            ACK_CODE_5093 -> {                ackVisibilities[5093] = true            }            ACK_CODE_5111 -> {                Log.d("ACK_ALARM_SUM_CHECK", ackVisibilities[5111].toString())            }            ACK_CODE_5114 -> {                addEvents(                    "BATTERY Critically Low ShutDown in anytime", prefManager?.readUHID().toString()                )            }            ACK_CODE_5115 -> {            }//            ACK_CODE_331 -> {//                removeAllAlarms()//            }            ACK_CODE_321 -> {            }            ACK_CODE_5169 -> {                VentilatorApp.isManualBreath = true                imageViewbreathe.visibility = View.VISIBLE            }            ACK_CODE_69 -> {                removeAllAlarms()                VentilatorApp.apneaActive = true                if (VentilatorApp.apneaActive == true) {                    modeType.text = "Apnea Vent."                    modeType.setTextColor(resources.getColor(R.color.black))                    modeButtonLayout.setBackgroundResource(R.color.preCalib_amber)                }                addEvents("Apnea ventilation started", prefManager?.readUHID().toString())            }            ACK_CODE_79 -> {                removeAllAlarms()                VentilatorApp.apneaActive = false                modeType.setTextColor(resources.getColor(R.color.white))                modeButtonLayout.setBackgroundResource(R.color.racing_green)                prefManager?.readLastVentMode()?.let { ventModecheck(it) }                addEvents("Apnea ventilation stopped", prefManager?.readUHID().toString())            }            ACK_CODE_49 -> {                if (VentilatorApp.isNebuliserActive == true) {                    mDashBoardViewModel.updateIsNebulizerActive(false)                    nebuliserTimer?.onFinish()                    VentilatorApp.isNebuliserActive = false                    Log.i("NEBULISER_FLAG", VentilatorApp.isNebuliserActive.toString())                } else {                    Log.i("NEBULISER_CHECK", "Nebuliser is inactive")                }                CoroutineScope(Dispatchers.Main).launch {                    dataStoreManager?.saveNebulizerCheck(false)                }//                VentilatorApp.isNebuliserActive == false            }            ACK_CODE_728 -> {                if (VentilatorApp.isNebuliserActive == true) {                    mDashBoardViewModel.updateIsNebulizerActive(false)                    nebuliserTimer?.onFinish()                } else {                    Log.i("NEBULISER_CHECK", "Nebuliser is inactive")                }                CoroutineScope(Dispatchers.Main).launch {                    dataStoreManager?.saveNebulizerCheck(false)                }            }            ACK_CODE_738 -> {                CoroutineScope(Dispatchers.Main).launch {                    dataStoreManager?.saveNebulizerCheck(true)                }            }            // NOTE: new way of handshake completed            ACK_CODE_5004 -> {                if (isForKnob == true) {                    addEventsForDevelopers(                        "Handshake Completed For Knob Data Not Available During Ventilation Case",                        prefManager?.readUHID().toString()                    )                }                // case for spo2 data knob available                else if (isForKnob == false) {                    addEventsForDevelopers(                        "Handshake Completed For Spo2 Data Not Available During Ventilation Case",                        prefManager?.readUHID().toString()                    )     