            setVGVStatus(readVGVStatusTemp())                    Log.i("CHECK_VTAS", prefManager?.readVGVStatus().toString())                    // set selected options into preference                    when (VentilatorApp.selectedOptions) {                        SELECTED_OPTIONS.PRONGS_NAME -> {                            prefManager?.setSelectedOptions(SELECTED_OPTIONS.PRONGS_NAME)                        }                        SELECTED_OPTIONS.INVASIVE_NAME -> {                            prefManager?.setSelectedOptions(SELECTED_OPTIONS.INVASIVE_NAME)                        }                        SELECTED_OPTIONS.NON_INVASIVE_NAME -> {                            prefManager?.setSelectedOptions(SELECTED_OPTIONS.NON_INVASIVE_NAME)                        }                    }                    VentilatorApp.selectedOptions = null                }                mDashBoardViewModel.SmartSpo2Toggle.tryEmit(false)                mDashBoardViewModel.hrSpo2DataStreaming.tryEmit(false)                mDashBoardViewModel.spo2hrDataStreaming.tryEmit(false)                if (modeCode != prefManager?.readLastVentMode()) removeAllAlarms()                createObservedParameterList(modeCode)                updateModeAndSendParametersToVentilator(modeCode)                renderAllTiles()                renderControlParameterTilesViaPreference()                setUpLayoutViaMode()                if (prefManager?.readLastVentMode() == MODE_HFNC) layoutFreezeData.visibility = View.GONE                lastUhid = prefManager?.readUHID().toString()                Log.i(                    "backup_value",                    "${prefManager?.readApneaSettingsStatusTemp()}  ,2,  ${prefManager?.readIRVStatusTemp()}"                )            }            ACK_CODE_5009 -> {                // nebuliserPanel.isEnabled=false                mDashBoardViewModel.updateIsNebulizerActive(false)                nebuliserTimer?.onFinish()                addEvents("Nebuliser stopped", prefManager?.readUHID().toString())            }            ACK_CODE_5008 -> {                nebuliserPanel.isEnabled = true                VentilatorApp.isNebuliserActive = true                mDashBoardViewModel.updateIsNebulizerActive(true)                imageViewNebuliser.visibility = View.VISIBLE                // ToastFactory.custom(this@DashBoardActivity,"The onclick of 5008")                nebulisercount.visibility = View.VISIBLE                nebuliserPanel.setBackgroundColor(                    ContextCompat.getColor(                        this, R.color.racing_green                    )                )                addEvents("Nebuliser started", prefManager?.readUHID().toString())                val tmv =                    (prefManager?.readNebuliserTime()?.toInt()?.times(60)?.toLong())?.times(1000)                nebuliserTimer = object : CountDownTimer(tmv!!, 1000) {                    override fun onTick(milliSec: Long) {                        imageViewNebuliser.visibility = View.VISIBLE                        nebulisercount.visibility = View.VISIBLE                        nebulisercount.text = "" + String.format(                            FORMAT,                            TimeUnit.MILLISECONDS.toMinutes(milliSec),                            TimeUnit.MILLISECONDS.toSeconds(milliSec) - TimeUnit.MINUTES.toSeconds(                                TimeUnit.MILLISECONDS.toMinutes(milliSec)                            )                        )                    }                    override fun onFinish() {                        mDashBoardViewModel.updateIsNebulizerActive(false)                        imageViewNebuliser.visibility = View.GONE                        nebulisercount.visibility = View.GONE                        nebuliserPanel.isEnabled = false                        nebuliserPanel.setBackgroundColor(                            ContextCompat.getColor(        