atorApp.isNebuliserActive = true                // alarm buffer zero for stop alarm bar                alarmStringBuffer = "${LIMITTER_ALARM_PRIORITY}0,0,0,0${DELIMETER_ALARM_PRIORITY}"                Log.i("AlarmBuffer", alarmStringBuffer)                communicationService?.takeIf { it.isPortsConnected }?.apply {                    send(alarmStringBuffer)                }                prefManager?.setSmartFiO2Status(false)                CoroutineScope(Dispatchers.Main).launch {                    dataStoreManager?.saveStandByCheckFlag(true)                }                Log.i("STAND_BY_RESPONSE", "STANDBY")                Handler(Looper.getMainLooper()).postDelayed({                    // Dismiss progress bar after 500 Milliseconds                    hideStandbyProgress()                }, 100)                CoroutineScope(Dispatchers.Main).launch {                    dataStoreManager?.saveNebulizerCheck(true)                }                Handler(Looper.getMainLooper()).postDelayed({                    Log.i("STANDBY", "Standby is true")                    // Dismiss progress bar after 2 seconds                    val intentData = Intent(this@DashBoardActivity, MainActivity::class.java)                    intentData.putExtra(IS_STAND_BY, true)                    startActivity(intentData)                    finish()                }, 1000)            }            ACK_CODE_16 -> {                Log.d(                    "ackvaluemessage", "$ACK_CODE_16   ${                        MessageFactory.getAckMessage(                            this@DashBoardActivity, ACK_CODE_16, prefManager?.readLastVentMode()                        )                    }"                )                mDashBoardViewModel.setBAtteryConnectedFlag(false)            }            ACK_CODE_6 -> {                mDashBoardViewModel.setBAtteryConnectedFlag(true)            }        }    }    private fun updateBatteryImage(batteryLevel: Int) {        if (batteryLevel in 76..100) {            primaryActionAdapter?.updateBatteryData(                R.drawable.ic_plug_out_rotate, R.drawable.battery_full            )            mBatteryLevel = "full"        } else if (batteryLevel in 51..75) {            primaryActionAdapter?.updateBatteryData(                R.drawable.ic_plug_out_rotate, R.drawable.battery_semi            )            mBatteryLevel = "medium"        } else if (batteryLevel in 26..50) {            primaryActionAdapter?.updateBatteryData(                R.drawable.ic_plug_out_rotate, R.drawable.battery_half            )            mBatteryLevel = "half"        } else if (batteryLevel in 0..25) {            primaryActionAdapter?.updateBatteryData(                R.drawable.ic_plug_out_rotate, R.drawable.battery_low            )            mBatteryLevel = "low"            addEvents("Battery Critically Low", prefManager?.readUHID().toString())            DialogBoxFactory.dismissDialogs()            DialogBoxFactory.showBatteryCriticallyLowStatusDialog(                "Ventilator will shutdown anytime,For patient's safety please connect the ventilator to AC source.",                ctx            )        } else {            primaryActionAdapter?.updateBatteryData(                R.drawable.ic_plug_out_rotate, R.drawable.battery_full            )        }    }    private fun ventModecheck(mode: Int) {        when (mode) {            MODE_VCV_CMV -> {                modeType.text = getString(R.string.hint_vc_cmv)            }            MODE_VCV_ACV -> {                modeType.text = getString(R.string.hint_vc_cv)            }            MODE_VCV_SIMV -> {                modeType.text = getString(R.string.hint_vc_simv)            }            MODE_PC_CMV -> {                modeType.text = getString(R.string.hint_pc_cmv)            }            MODE_PC_SIMV -> {                modeType.text = getString(R.string.hint_pc_simv)            }            MODE_PC_AC -> {                modeType.text = getString(R.string.hint_spont)            }            MODE_PC_ARPV -> {                modeType.text = getString(R.string.hint_pc_aprv)            }            MODE_PC_PSV -> {                modeType.text = getString(R.string.hint_psv)            }            MODE_PC_PRVC -> {                modeType.text = getString(R.string.hint_prvc)            }            MODE_HFNC -> {                if (prefManager?.readCurrentUid() == Configs.PatientProfile.TYPE_NEONAT) modeType.text =                    getString(R.string.NeoNatehfnc) else modeType.text = getString(R.string.hfnc)            }            MODE_AUTO_VENTILATION -> {                modeType.text = getString(R.string.hint_ai_vent)            }            MODE_NIV_BPAP -> {                if (prefManager?.readCurrentUid() == Configs.PatientProfile.TYPE_NEONAT) modeType.text =                    getString(R.string.hint_nbpap) else modeType.text =                    getString(R.string.hint_bpap)            }            MODE_NC_IPPV -> {                if (prefManager?.readCurrentUid() == Configs.PatientProfile.TYPE_NEONAT) modeType.text =                    getString(R.string.hint_nc_cpap) else modeType.text =                    getString(R.string.hint_nc_cpap)            }            MODE_NIV_CPAP -> {                if (prefManager?.readCurrentUid() == Configs.PatientProfile.TYPE_NEONAT) modeType.text =                    getString(R.string.hint_ncpap) else modeType.text =                    getString(R.string.hint_cpap)            }            MODE_NC_CPAP -> {                if (prefManager?.readCurrentUid() == Configs.PatientProfile.TYPE_NEONAT) modeType.text =                    getString(R.string.hint_ncpap)            }        }    }    private fun validateErrorBar() {        if (mDashBoardViewModel.alarms.value?.isEmpty() == true) {            mDashBoardViewModel.alarms.value?.let {                sizeOfLow = it.filter {                    it.priority == Configs.AlarmType.ALARM_LOW_LEVEL                }.size                sizeOfMedium = it.filter {                    it.priority == Configs.AlarmType.ALARM_MEDIUM_LEVEL                }.size                sizeOfHigh = it.filter {                    it.priority == Configs.AlarmType.ALARM_HIGH_LEVEL                }.size                sizeOfCritical = it.filter {                    it.priority == Configs.AlarmType.ALARM_CRITICAL_LEVEL                }.size                alarmStringBuffer =                    "${LIMITTER_ALARM_PRIORITY}$sizeOfCritical,$sizeOfHigh,$sizeOfMedium,$sizeOfLow${DELIMETER_ALARM_PRIORITY}"                Log.i("AlarmBuffer", alarmStringBuffer)                CoroutineScope(Dispatchers.IO).launch {                    delay(100L)                    communicationService?.takeIf { it.isPortsConnected }?.apply {                        send(alarmStringBuffer)                    }                }            }        }        if (mDashBoardViewModel.alarms.value?.isNotEmpty() == true) {            mDashBoardViewModel.alarms.value?.let {                sizeOfLow = it.filter {                    it.priority == Configs.AlarmType.ALARM_LOW_LEVEL                }.size                sizeOfMedium = it.filter {                    it.priority == Configs.AlarmType.ALARM_MEDIUM_LEVEL                }.size                sizeOfHigh = it.filter {                    it.priority == Configs.AlarmType.ALARM_HIGH_LEVEL                }.size                sizeOfCritical = it.filter {                    it.priority == Configs.AlarmType.ALARM_CRITICAL_LEVEL                }.size                alarmStringBuffer = "${LIMITTER_ALARM_PRIORITY}$sizeOfCritical,$sizeOfHigh,$sizeOfMedium,$sizeOfLow${DELIMETER_ALARM_PRIORITY}"                Log.i("AlarmBuffer", alarmStringBuffer)                CoroutineScope(Dispatchers.IO).launch {                    delay(100L)                    communicationService?.takeIf { it.isPortsConnected }?.apply {                        send(alarmStringBuffer)                    }                }            }            // set color of error bar according to alarm level priority            if (mDashBoardViewModel.alarms.value?.any { a ->                    a.priority == AlarmType.ALARM_HIGH_LEVEL || a.priority == AlarmType.ALARM_CRITICAL_LEVEL                } == true) {                alarmBarColor = "#AC0303"                alarmTextColor = "#FFFFFF"                layoutErrorBar?.setBackgroundResource(R.color.ack_red)                tvErrorBar?.setTextColor(Color.WHITE)                mDashBoardViewModel.alarms.value?.first()?.let {                    tvErrorBar?.text = it.message                }            } else if (mDashBoardViewModel.alarms.value?.any { a ->                    a.priority == AlarmType.ALARM_MEDIUM_LEVEL || a.priority == AlarmType.ALARM_LOW_LEVEL                } == true) {                alarmBarColor = "#F4C430"                alarmTextColor = "#000000"                layoutErrorBar?.setBackgroundResource(R.color.yellow_dark)                tvErrorBar?.setTextColor(Color.BLACK)                mDashBoardViewModel.alarms.value?.first()?.let {                    tvErrorBar?.text = it.message                }            } else {                alarmBarColor = "#AC0303"                alarmTextColor = "#FFFFFF"                layoutErrorBar?.setBackgroundResource(R.color.ack_red)                tvErrorBar?.setTextColor(Color.WHITE)                //   tvErrorBar?.setTextColor(R.color.white)                mDashBoardViewModel.alarms.value?.first()?.let {                    tvErrorBar?.text = it.message                }            }            // change here 19 sep            if (mDashBoardViewModel.alarms.value?.any { a -> a.priority == AlarmType.ALARM_HIGH_LEVEL || a.priority == AlarmType.ALARM_CRITICAL_LEVEL || a.priority == AlarmType.ALARM_MEDIUM_LEVEL || a.priority == AlarmType.ALARM_LOW_LEVEL } == true) {                if (sizeOfCritical > 0) {                    currentPriority = AlarmType.ALARM_CRITICAL_LEVEL                    playAlarm(currentPriority)                } else if (sizeOfHigh > 0) {                    currentPriority = AlarmType.ALARM_HIGH_LEVEL                    playAlarm(currentPriority)                } else if (sizeOfMedium > 0) {                    currentPriority = AlarmType.ALARM_MEDIUM_LEVEL                    playAlarm(currentPriority)                } else if (sizeOfLow > 0) {                    isAlarmPlaying = false                    try {                        mediaPlayer?.setVolume(0.0f, 0.0f)                    } catch (e: Exception) {                        Log.i("CHECK_MEDIA", e.toString())                    }                }            }        } else {            // change here 19 sep            // NO ALARM SHOULD PLAY WHEN COUNT = 0            alarmBarColor = "#000000"            alarmTextColor = "#000000"            layoutErrorBar?.setBackgroundResource(R.drawable.background_black)            tvErrorBar?.text = ""            isAlarmPlaying = false            try {                mediaPlayer?.setVolume(0.0f, 0.0f)            } catch (e: Exception) {                Log.i("CHECK_MEDIA", e.toString())            }        }    }    // change here 19 sep    private fun playAlarm(currentPriority: AlarmType) {        try {            isAlarmPlaying = true            AlarmConfiguration.getAlarmUri(currentPriority)?.let { it1 ->                if (!isAlarmMuted) {                    prefManager?.apply {                        mediaPlayer?.setVolume(                            readVolume() / VOLUME_MAX_VALUE, readVolume() / VOLUME_MAX_VALUE                        )                    }                }            }        } catch (e: Exception) {            e.printStackTrace()        }    }    fun addEvents(eventMsg: String, uhid: String) {        val eventDataModel = EventDataModel(            eventMsg, uhid        )        mEventViewModel.addEvent(eventDataModel)    }    fun addEventsForDevelopers(eventMsg: String, uhid: String) {        val eventDataModel = EventDataModel(            eventMsg, uhid        )        mEventViewModel.addEventForDevelopers(eventDataModel)    }    private fun addAlarm(alarmKey: String, alarmMsg: String, uhid: String) {        AlarmModel(            alarmMsg, alarmKey, getCurrentDateTime(), uhid        ).let {            alarmsMap[alarmKey] = it            mDashBoardViewModel.addAlarm(it)            mAlarmViewModel.addAlarm(it.toDBModel())            Log.d("LOGCRASH", "23`")        }        lastUhidAlarms = uhid    }    private fun removeAlarm(ackValue: String) {        alarmsMap.getOrDefault(ackValue, null)?.let {            mDashBoardViewModel.removeAlarm(it)            alarmsMap.remove(ackValue)        }    }    private fun removeAllAlarms() {        mDashBoardViewModel.removeAllAlarms()        alarmsMap.clear()    }    private var settingsCountDownTimer: SettingsCountDownTimer? = null    private var alarmSpo2HrFlag: Boolean = false    private var isRebootDone: Boolean = false    private var isGraphicalToolTipVisible = false    private var isFio2ValueChange = false    private var lastUhidAlarms = ""    private var lastUhidEvents = ""    private var lastUhid = ""    //Code to be removed    var tempSpo2Timer: CountDownTimer? = null    var tempHrTimer: CountDownTimer? = null    var decTimer: CountDownTimer? = null    private var isTempHrTimerRunning: Boolean? = false    private var isDecreTimerRunning: Boolean? = false    private var isTempSPo2TimerRunning: Boolean? = false    private var hrTimerClosed: Boolean? = false    private var spo2TimerClosed: Boolean? = false    private var tempReadSpo2List: ArrayList<Float> = ArrayList<Float>()    private var tempReadHrList: ArrayList<Float> = ArrayList<Float>()    private fun removeSPO2LowMaxFio2() {        if (alarmsMap.containsKey(Configs.ALARM_MAX_FIO2)) {            removeAlarm(ALARM_MAX_FIO2)        }    }    private fun removeHighPRMaxFio2() {        if (alarmsMap.containsKey(Configs.ALARM_MAX_FIO2_HR_HIGH)) {            removeAlarm(ALARM_MAX_FIO2_HR_HIGH)        }    }    private fun removeVentilatorFailureAlarm() {        if (alarmsMap.containsKey(ALARM_VENTILATOR_FAILURE)) {            removeAlarm(ALARM_VENTILATOR_FAILURE)        }    }    private fun removeKnobFailureAlarm() {        if (alarmsMap.containsKey(ALARM_KNOB_FAILURE)) {            removeAlarm(ALARM_KNOB_FAILURE)        }    }    private fun removeWrongPeepAlarm() {        if (alarmsMap.containsKey(Configs.ALARM_WRONG_PEEP)) {            removeAlarm(Configs.ALARM_WRONG_PEEP)        }    }    private fun addWrongPeepAlarm() {        removeWrongPeepAlarm()        addAlarm(            Configs.ALARM_WRONG_PEEP,            getString(R.string.wrong_peep_alarm),            (if (prefManager?.readUHID() == null) "0000000000" else prefManager?.readUHID()).toString()        )    }    private fun removeAutoPeepAlarm() {        if (alarmsMap.containsKey(Configs.ALARM_AUTO_PEEP)) {            removeAlarm(ALARM_AUTO_PEEP)        }    }    private fun addAutoPeepAlarm() {        removeAutoPeepAlarm()        addAlarm(            Configs.ALARM_AUTO_PEEP,            getString(R.string.auto_peep_alarm),            (if (prefManager?.readUHID() == null) "0000000000" else prefManager?.readUHID()).toString()        )    }    private fun removeFio2LeakAlarm() {        if (alarmsMap.containsKey(Configs.ALARM_FIO2_LEAK)) {            removeAlarm(ALARM_FIO2_LEAK)        }    }    private fun addFio2LeakAlarm() {        removeFio2LeakAlarm()        addAlarm(            Configs.ALARM_FIO2_LEAK,            getString(R.string.fio2_leak),            (if (prefManager?.readUHID() == null) "0000000000" else prefManager?.readUHID()).toString()        )    }    private fun addSPO2LowMaxFio2() {        removeSPO2LowMaxFio2()        addAlarm(            Configs.ALARM_MAX_FIO2,            getString(R.string.maxFio2),            (if (prefManager?.readUHID() == null) "0000000000" else prefManager?.readUHID()).toString()        )    }    private fun addHighPRMaxFio2() {        removeHighPRMaxFio2()        addAlarm(            Configs.ALARM_MAX_FIO2_HR_HIGH,            getString(R.string.maxFio2HR),            (if (prefManager?.readUHID() == null) "0000000000" else prefManager?.readUHID()).toString()        )    }    private fun callRunningStatusApi(status: String, dataStatus: String) {        CoroutineScope(Dispatchers.IO).launch {            val request = StatusRequestModel()            dataStoreManager?.apply {                request.apply {                    this.did = Settings.Secure.getString(                        this@DashBoardActivity.contentResolver, Settings.Secure.ANDROID_ID                    )                    this.deviceStatus = deviceStatus                    this.message = status                    this.last_hours = calculateTotalAndLastHours(getLastHours().first().toLong())                    this.total_hours = calculateTotalAndLastHours(getTotalHours().first().toLong())                    this.health = " Good"                    this.address = LocationFilter(this@DashBoardActivity).getAddress(                        VentilatorApp.latitude, VentilatorApp.logitude                    )                }                Log.i("value_check_hours", "INVENTILATION $request")                if (!ServerLogger.sendStatusRequest(request)) ServerLogger.sendStatusRequest(request)            }        }    }    private fun callPatientDetailsApi() {        CoroutineScope(Dispatchers.IO).launch {            val request = PatientDetailsRequestModel()            request.apply {                this.deviceId = Settings.Secure.getString(                    this@DashBoardActivity.contentResolver, Settings.Secure.ANDROID_ID                )                this.age = prefManager?.readAge().toString()                this.weight = prefManager?.readBodyWeight().toString()                this.height = prefManager?.readBodyHeight().toString()                this.UHID =                    if (prefManager?.readUHID() == FIRST_FILTER_NAME) "" else prefManager?.readUHID()                        .toString()                this.patient_Profile = when (prefManager?.readCurrentUid()) {                    PatientProfile.TYPE_NEONAT -> "Neonate"                    PatientProfile.TYPE_ADULT -> "Adult"                    PatientProfile.TYPE_PED -> "Pediatric"                    else -> ""                }            }            Log.i("value_check_hours", "INVENTILATION $request")            if (!ServerLogger.sendPatientDetailsRequest(request)) ServerLogger.sendPatientDetailsRequest(                request            )        }    }    @SuppressLint("HardwareIds")    private fun socketSendLogic() {        deviceId = Settings.Secure.getString(            this@DashBoardActivity.contentResolver, Settings.Secure.ANDROID_ID        )        try {            mSocket = IO.socket(FileLogger.readBaseUrl())            mSocket?.connect()        } catch (e: URISyntaxException) {            e.printStackTrace()        }        mSocket?.on("AndroidReceivingPaymentStatus") {            if (deviceId == it[0].toString().split("^")[0]) {                if (it[0].toString().split("^")[1] == "false") {                    val lockedStatusData = "$deviceId,false,false,In Ventilation"                    mSocket?.emit("NodeReceivingLockedStatus", lockedStatusData)                    prefManager?.saveLockedStatus("Manual Lock")                } else {                    val lockedStatusData = "$deviceId,true,false,Unlocked"                    mSocket?.emit("NodeReceivingLockedStatus", lockedStatusData)                    prefManager?.saveLockedStatus("Unlock")                }            }        }        mSocket?.emit("AndroidStartUp", deviceId)        mSocket?.on("AndroidNodeStart") {            if (deviceId == it[0].toString().split(",")[0]) {                connectedDevicesLive += 1                isSocketStop = false                isLiveDataRequest = true            }        }        mSocket?.on("AndroidReceiveStop") {            if (it[0].toString() == deviceId) {                connectedDevicesLive -= 1                isSocketStop = true                isLiveDataRequest = connectedDevicesLive > 0            }        }        mSocket?.on("AndroidNodeStartGraph") {            if (deviceId == it[0].toString().split(",")[0]) {                connectedDevicesLiveForGraph += 1                isLiveGraphDataRequest = true            }        }        mSocket?.on("AndroidReceiveStopGraph") {            if (it[0].toString() == deviceId) {                if (connectedDevicesLiveForGraph > 0) connectedDevicesLiveForGraph -= 1                isLiveGraphDataRequest = connectedDevicesLiveForGraph > 0            }        }        mSocket?.on("NodeToAndroidBackup") {            if (it[0].toString() == deviceId) {                sendBackUpDataToLiveFragment()            }        }        mSocket?.on("NodeToAndroidAdvanced") {            if (it[0].toString() == deviceId) {                sendAdvancedDataToLiveFragment()            }        }        mSocket?.on("NodeToAndroidBasic") {            if (it[0].toString() == deviceId) {                sendBasicDataToLiveFragment()            }        }        mSocket?.on("NodeToAndroidAlarm") {            if (it[0].toString() == deviceId) {                sendAlarmLimitDataToLiveFragment()            }        }    }    private fun sendAdvancedDataToLiveFragment() {        var advancedTiles = ArrayList<ControlParameterModel>()        val controlParameters = filterControlParameterViaMode(            this@DashBoardActivity, prefManager?.readLastVentMode()!!, getAllControlParameterLists(                this@DashBoardActivity, prefManager?.readLastVentMode()!!            ).flatten()        )        controlParameters[ControlSettingType.ADVANCED]?.let {            advancedTiles = it as ArrayList<ControlParameterModel>        }        var data = deviceId        data += "^"        // advanced toggle data        data += prefManager?.readIRVStatus().toString() + "^"        // backup tiles data send        for (i in advancedTiles) {            if (i != null && (i.title != "" && i.reading != "")) data += "${i.title}~${i.reading}~${i.units},"        }        data = data.substring(0, data.length - 1)        // usb connection data        data += "${communicationService?.isVentilatorConnected},${communicationService?.isHIDConnected}^"        Log.i(            "dataAdvancedswa", "$data | ${advancedTiles.size} | ${prefManager?.readLastVentMode()}"        )        if (isLiveDataRequest) mSocket?.emit("AndroidToNodeAdvanced", data)    }    private fun sendBasicDataToLiveFragment() {        var basicTiles = ArrayList<ControlParameterModel>()        val controlParameters = filterControlParameterViaMode(            this@DashBoardActivity, prefManager?.readLastVentMode()!!, getAllControlParameterLists(                this@DashBoardActivity, prefManager?.readLastVentMode()!!            ).flatten()        )        controlParameters[ControlSettingType.BASIC]?.let {            basicTiles = it as ArrayList<ControlParameterModel>        }        var data = deviceId        data += "^"        // backup tiles data send        for (i in basicTiles) {            if (i != null && (i.title != "" && i.reading != "" && i.units != "")) data += "${i.title}~${i.reading}~${i.units},"        }        if (data[data.length - 1] == ',') data = data.substring(0, data.length - 1)        Log.i("dataBackupswa", "$data | ${basicTiles.size} | ${prefManager?.readLastVentMode()}")        if (isLiveDataRequest) mSocket?.emit("AndroidToNodeBasic", data)    }    private fun sendBackUpDataToLiveFragment() {        var backupTiles = ArrayList<ControlParameterModel>()        val controlParameters = filterControlParameterViaMode(            this@DashBoardActivity, prefManager?.readLastVentMode()!!, getAllControlParameterLists(                this@DashBoardActivity, prefManager?.readLastVentMode()!!            ).flatten()        )        controlParameters[ControlSettingType.BACKUP]?.let {            backupTiles = it as ArrayList<ControlParameterModel>        }        var data = deviceId        data += "^"        // backup toggle data        data += prefManager?.readApneaSettingsStatus().toString() + "^"        // backup tiles data send        for (i in backupTiles) {            if (i != null && (i.title != "" && i.reading != "" && i.units != "")) data += "${i.title}~${i.reading}~${i.units},"        }        if (data[data.length - 1] == ',') data = data.substring(0, data.length - 1)        Log.i("dataBackupswa", "$data | ${backupTiles.size} | ${prefManager?.readLastVentMode()}")        if (isLiveDataRequest) mSocket?.emit("AndroidToNodeBackup", data)    }    fun sendAlarmLimitDataToLiveFragment() {        var data = deviceId        data += "^"        prefManager?.let {            data += it.readPipLimits()[1].toInt().toString() + ","            data += it.readPipLimits()[0].toInt().toString() + ","            data += it.readVteLimits()[1].toInt().toString() + ","            data += it.readVteLimits()[0].toInt().toString() + ","            data += it.readPeepLimits()[1].toInt().toString() + ","            data += it.readPeepLimits()[0].toInt().toString() + ","            data += it.readRRLimits()[1].toInt().toString() + ","            data += it.readRRLimits()[0].toInt().toString() + ","            data += it.readMveLimits()[1].toInt().toString() + ","            data += it.readMveLimits()[0].toInt().toString()        }        Log.i("dataAlarmLimits", data)        if (isLiveDataRequest) mSocket?.emit("AndroidToNodeAlarm", data)    }    // knob highlight logic starts here    private var highlightedIndex = 0    private var prevHighlightedIndex = 0    private var visibilityTimeout: CountDownTimer? = null    @SuppressLint("NotifyDataSetChanged")    private fun normaliseAdapters() {        secondaryObservedParameterAdapter?.selectedIndex = -1        primaryObservedParameterAdapter?.selectedIndex = -1        primaryControlParameterAdapter?.selectedIndex = -1        primaryActionAdapter?.selectedIndex = -1        secondaryObservedParameterAdapter?.notifyDataSetChanged()        primaryObservedParameterAdapter?.notifyDataSetChanged()        primaryControlParameterAdapter?.notifyDataSetChanged()        primaryActionAdapter?.notifyDataSetChanged()    }    @SuppressLint("NotifyDataSetChanged")    fun highlightViewWithFocus(data: String) {        startTimeoutWithDebounce()        Log.i("value_check_tiles", "$highlightedIndex")        normaliseAdapters()        when (data) {            PREFIX_PLUS -> {                if (highlightedIndex < 40) highlightedIndex++                else highlightedIndex = 1                getViewForFocus()?.let { changeConstraintsOfFocusLayout(it) } ?: run {                    clearPreviousConstraints()                    if (highlightedIndex in 16..20) {                        primaryObservedParameterAdapter?.selectedIndex =                            (highlightedIndex - prevHighlightedIndex)                        primaryObservedParameterAdapter?.notifyDataSetChanged()                    } else if (highlightedIndex in 21..29) {                        primaryControlParameterAdapter?.selectedIndex =                            (highlightedIndex - prevHighlightedIndex)                        primaryControlParameterAdapter?.notifyDataSetChanged()                    } else {                        primaryActionAdapter?.selectedIndex =                            (highlightedIndex - prevHighlightedIndex)                        primaryActionAdapter?.notifyDataSetChanged()                    }                }            }            PREFIX_MINUS -> {                if (highlightedIndex > 1) highlightedIndex--                else highlightedIndex = 40                getViewForFocus()?.let { changeConstraintsOfFocusLayout(it) } ?: run {                    clearPreviousConstraints()                    if (highlightedIndex in 16..20) {                        primaryObservedParameterAdapter?.selectedIndex =                            (highlightedIndex - prevHighlightedIndex)                        primaryObservedParameterAdapter?.notifyDataSetChanged()                    } else if (highlightedIndex in 21..29) {                        primaryControlParameterAdapter?.selectedIndex =                            (highlightedIndex - prevHighlightedIndex)                        primaryControlParameterAdapter?.notifyDataSetChanged()                    } else {                        primaryActionAdapter?.selectedIndex =                            (highlightedIndex - prevHighlightedIndex)                        primaryActionAdapter?.notifyDataSetChanged()                    }                }            }            PREFIX_AND -> {                getViewForFocus()?.callOnClick() ?: kotlin.run {                    if (highlightedIndex in 16..20) {                        onClick(                            highlightedIndex - prevHighlightedIndex,                            selectedTiles[highlightedIndex - prevHighlightedIndex]                        )                    } else if (highlightedIndex in 21..29) {                        if (primaryControlParameters[highlightedIndex - prevHighlightedIndex].isVoid) {                            onBasicParameterClickListener.onClick(                                highlightedIndex - prevHighlightedIndex,                                primaryControlParameters[highlightedIndex - prevHighlightedIndex]                            )                        } else {                        }                    } else {                        onClick(highlightedIndex - prevHighlightedIndex)                    }                }            }        }    }    private fun clearPreviousConstraints() {        try {            val constraintSet = ConstraintSet()            constraintSet.clone(mainViewPanelDashboard)            constraintSet.clear(focusLayoutDashboard.id, ConstraintSet.TOP)            constraintSet.clear(focusLayoutDashboard.id, ConstraintSet.BOTTOM)            constraintSet.clear(focusLayoutDashboard.id, ConstraintSet.LEFT)            constraintSet.clear(focusLayoutDashboard.id, ConstraintSet.RIGHT)            constraintSet.applyTo(mainViewPanelDashboard)        } catch (e: Exception) {            e.printStackTrace()        }    }    private fun changeConstraintsOfFocusLayout(view: View) {        val constraintSet = ConstraintSet()        constraintSet.clone(mainViewPanelDashboard)        constraintSet.connect(            focusLayoutDashboard.id,            ConstraintSet.RIGHT,            view.id,            ConstraintSet.RIGHT,            0        )        constraintSet.connect(            focusLayoutDashboard.id,            ConstraintSet.TOP,            view.id,            ConstraintSet.TOP,            0        )        constraintSet.connect(            focusLayoutDashboard.id,            ConstraintSet.BOTTOM,            view.id,            ConstraintSet.BOTTOM,            0        )        constraintSet.connect(            focusLayoutDashboard.id,            ConstraintSet.LEFT,            view.id,            ConstraintSet.LEFT,            0        )        constraintSet.applyTo(mainViewPanelDashboard)    }    private fun getViewForFocus(): View? {        return when (highlightedIndex) {            1 -> modeButtonLayout            2 -> patientLayout            3 -> layoutErrorBar            4 -> alarmPanel            5 -> standbyLayout            6 -> button_monitoring            7 -> button_alarms            8 -> button_loop            9 -> button_graphics            10 -> button_maneuvers            11 -> button_logs            12 -> button_modes            13 -> button_controls            14 -> button_systems            15 -> layoutFreezeData            in 16..20 -> {                prevHighlightedIndex = 16                null            }            in 21..29 -> {                prevHighlightedIndex = 21                null            }            30 -> button_more_controls            in 31..40 -> {                prevHighlightedIndex = 31                null            }            else -> null        }    }    fun startTimeoutWithDebounce() {        cancelTimeout()        visibilityTimeout = object : CountDownTimer(10000, 2000) {            override fun onTick(millisUntilFinished: Long) {            }            override fun onFinish() {                normaliseAdapters()                clearPreviousConstraints()                cancelTimeout()            }        }        visibilityTimeout?.start()    }    fun cancelTimeout() {        if (visibilityTimeout != null) {            visibilityTimeout?.cancel()            visibilityTimeout = null        }    }    @SuppressLint("HardwareIds")    private fun getVentilatorDetailsApi() {        CoroutineScope(Dispatchers.IO).launch {            val response = ServerLogger.getVentiDetailsRequest(                Settings.Secure.getString(                    this@DashBoardActivity.contentResolver,                    Settings.Secure.ANDROID_ID                )            )            response?.let {                if (it.statusCode == 200) {                    prefManager?.saveVentiDetails("${it.data.Ward_No},${it.data.Hospital_Name},${it.data.Department_Name}")                }            }        }    }    // knob highlight logic ends here    override fun onCreate(savedInstanceState: Bundle?) {        super.onCreate(savedInstanceState)        startTimeDashboard = currentTimeMillis()        //ServerLogger.i(this, "On Create")        prefManager = PreferenceManager(this@DashBoardActivity)        dataStoreManager = DataStoreManager(this@DashBoardActivity)        lastDashboardRunningTime = prefManager?.readDashBoardRunningTime()!!        lastServiceRunningTime = prefManager?.readDashBoardRunningTimeForService()!!        prefManager?.setRebootStatusForHandshake(false)        VentilatorApp.currentActivityName = "Dash"        CoroutineScope(Dispatchers.Main).launch {            dataStoreManager?.saveCurrentActivity("Dash")        }        // add run status api        callRunningStatusApi(RUNNING_STATUS_ACTIVE, ACTIVITY_VENTILATION)        getVentilatorDetailsApi()        callPatientDetailsApi()        CoroutineScope(Dispatchers.IO).launch {            FileLogger.readCrashFile().let {                if (it != dataNotFound) {                    val result = ServerLogger.d(                        this@DashBoardActivity,                        it,                        "AgvaPro"                    )                    if (result) FileLogger.deleteCrashFile()                }            }        }        lastUpdatedTime = System.currentTimeMillis()        // set standby status false        CoroutineScope(Dispatchers.Main).launch {            dataStoreManager?.saveStandByCheckFlag(false)        }        VentilatorApp.xValuePatientTriggerList.clear()        VentilatorApp.xValueManualTriggerList.clear()        requestWindowFeature(Window.FEATURE_NO_TITLE)        hideSystemUI()        setContentView(R.layout.activity_dashboard)        if (prefManager?.readLastVentMode() == MODE_HFNC) layoutFreezeData.visibility = View.GONE        mAlarmViewModel = ViewModelProvider(this)[AlarmViewModel::class.java]        mEventViewModel = ViewModelProvider(this)[EventViewModel::class.java]        mDebugViewModel = ViewModelProvider(this)[DebugViewModel::class.java]        mDashBoardViewModel = ViewModelProvider(this)[DashBoardViewModel::class.java]        smartFio2Algo()        socketSendLogic()        onPlayAlarm()        mDashBoardViewModel.alarms.observe(this) { validateErrorBar() }        notifyObserverAboutInhalation()        alarmLayoutPosition = modeButtonLayout.width + patientLayout.width        mDashBoardViewModel.isUHIDSet.observe(this, androidx.lifecycle.Observer {            if (it == true) {                if (!prefManager?.readUHID().equals(FIRST_FILTER_NAME)) uhidView.text = "  ${                    prefManager?.readUHID()                }"            }        })        lastUhidAlarms = prefManager?.readUHID().toString()        lastUhidEvents = prefManager?.readUHID().toString()        lastUhid = prefManager?.readUHID().toString()        prefManager.apply {            this?.setOperationalHoursStartTime(currentTimeMillis())            this?.setOperationalHoursEndTime(0L)            this?.setServiceHoursStartTime(currentTimeMillis())            this?.setServiceHoursEndTime(0L)        }        if (!prefManager?.readUHID().equals(FIRST_FILTER_NAME)) uhidView.text =            prefManager?.readUHID()        mDashBoardViewModel.setBAtteryConnectedFlag(false)        mDashBoardViewModel.isBatteryConnected.observe(this, androidx.lifecycle.Observer { it ->            Log.i("093123", "adwadawd")            isBatteryConnected = it            globalCount = 0            if (it == true) {                mDashBoardViewModel.ventBatteryLevel.value?.let { it1 -> updateBatteryImage(it1) }            } else {                primaryActionAdapter?.updateBatteryData(                    R.drawable.ic_plug_linear, R.drawable.ic_charging_linear                )                mBatteryLevel = "charging"                mBatteryPercentage = mDashBoardViewModel.ventBatteryLevel.value.toString()            }        })        mDashBoardViewModel.ventBatteryLevel.distinctUntilChanged()            .observe(this, androidx.lifecycle.Observer {                if (mDashBoardViewModel.isBatteryConnected.value == true) {                    updateBatteryImage(it)                    mBatteryPercentage = it.toString()                }            })        initData()        initStartVentilationTime()        renderTopBarViaPreference()        // observedPopUpRecyclerView.last        ivParamMenuCross.setOnClickListener {            closeSwappableLayout()        }        ivSwappableDown.setOnClickListener { scrollSwappableListDown() }        ivSwappableUp.setOnClickListener { scrollSwappableListUp() }        alarmPanel.setOnClickListener {            alarmMuteUnMuteVisibility()        }        patientLayout?.setOnClickListener(View.OnClickListener {            if (isLocked) {                DialogBoxFactory.showSystemLockDialog(ctx)            } else {                layoutFreezeData.visibility = View.GONE                showControlFragment(Bundle().apply {                    putString("fragment_patient", "PatientFragment")                }, "patient")            }        })        layoutErrorBar?.setOnClickListener(View.OnClickListener {            layoutFreezeData.visibility = View.GONE            showAlarmFragment(Bundle().apply { putString("fragment_val", "BufferFragment") })        })        Intent(this, UsbService::class.java).also { intent ->            startService(intent)        }        graphicsDialogFragment?.requireDialog()?.setOnDismissListener {            button_graphics.setBackgroundResource(R.drawable.background_black)            button_graphics.setTextColor(                ContextCompat.getColor(                    this@DashBoardActivity, R.color.dim_grey                )            )        }        //The smart Fio2 average section code section        prefManager?.setSmartFio2(prefManager?.readFiO2())        //Operational hours in hours and minutes.        countDownTimerForServiceHour()        // timer to dec spo2 value in 10 mins        timerForDecreaseSmartFio2()        observeGraphFreeze()        freezeGraphTimer()    }    private fun timerForDecreaseSmartFio2() {        decTimer = object : CountDownTimer(360000, 1000) {            override fun onTick(millisUntilFinished: Long) {                isDecreTimerRunning = true                Log.i("vlaue_Sdwa", "dec timer ontick")            }            override fun onFinish() {                Log.i("vlaue_Sdwa", "dec timer finish")                prefManager?.setFiO2(                    prefManager?.readFiO2()?.minus(1)                )                primaryControlParameterAdapter?.notifyDataSetChanged()                isDecreTimerRunning = false            }        }    }//    private fun setupOperatingHoursTimer(){//        operatingHoursTimer = object :CountDownTimer(prefManager?.readOperatingHours()!!,1000L){//            override fun onTick(millisUntilFinished: Long) {//                Log.i("CHECK_TICK_HERE",millisUntilFinished.toString())//                prefManager?.setOperatingHours(millisUntilFinished)////            }////            override fun onFinish() {//                operatingHoursTimer?.cancel()//            }//        }//        operatingHoursTimer?.start()//    }    @SuppressLint("NotifyDataSetChanged")    private fun smartFio2Algo() {        prefManager?.readSmartFiO2Status()?.let { mDashBoardViewModel.SmartSpo2Toggle.tryEmit(it) }        lifecycleScope.launch(Dispatchers.Main) {            mDashBoardViewModel.hrSpo2DataStreaming.zip(mDashBoardViewModel.spo2hrDataStreaming) { value1, value2 ->                Pair(value1, value2)            }.combine(mDashBoardViewModel.SmartSpo2Toggle) { value12, value3 ->                Pair(value12, value3)            }.collect {                Log.i("vlaue_Sdwa", "in tuple condition")                if (it.first.first && (it.first.second && it.second)) {                    Log.i("vlaue_Sdwa", "in tuple first condition")                    if (isTempHrTimerRunning == false && isTempSPo2TimerRunning == false) {                        Log.i("vlaue_Sdwa", "timer started")                        hrTimerClosed = false                        spo2TimerClosed = false                        tempSpo2Timer?.start()                        tempHrTimer?.start()                    }                    fio2ChangeFlag = true                    primaryControlParameterAdapter?.notifyDataSetChanged()                } else {                    Log.i("vlaue_Sdwa", "in tuple second condition")                    isTempHrTimerRunning = false                    isTempSPo2TimerRunning = false                    tempHrTimer = null                    tempSpo2Timer = null                    hrTimerClosed = true                    spo2TimerClosed = true                    decTimer?.cancel()                    isDecreTimerRunning = false                    Log.i("vlaue_Sdwa", "timer finished")                    removeHighPRMaxFio2()                    removeSPO2LowMaxFio2()                    primaryControlParameters.let {                        it.forEach {                            if (it.title == "FiO₂") {                                Log.i("CHECK_HERE_FIO2", it.reading.toString())                                prefManager?.setFiO2(prefManager?.readSmartFio2())                                it.reading = prefManager?.readSmartFio2()?.toInt().toString()                                if (!isFio2ValueChange) {                                    primaryControlParameterAdapter?.notifyDataSetChanged()                                }                            }                        }                    }                    fio2ChangeFlag = null                    primaryControlParameterAdapter?.notifyDataSetChanged()                }            }        }        mDashBoardViewModel.avgTempSpo2List.observe(this) {            var string: java.lang.StringBuilder = java.lang.StringBuilder()            for (i in 0..(it.size - 1)) {                string.append(" ${it.get(i)} ")            }            Log.i("vlaue_Sdwa", "avg spo2 list generated")            mDashBoardViewModel.Spo2TempMean.tryEmit(it.sum().div(it.size))        }        mDashBoardViewModel.avgTempHrList.observe(this) {            var string: java.lang.StringBuilder = java.lang.StringBuilder()            for (i in 0..(it.size - 1)) {                string.append(" ${it.get(i)} ")            }            Log.i("vlaue_Sdwa", "avg HR list generated")            mDashBoardViewModel.HrTempMean.tryEmit(it.sum().div(it.size))        }        lifecycleScope.launch(Dispatchers.Main) {            mDashBoardViewModel.Spo2TempMean.combine(mDashBoardViewModel.HrTempMean) { value1, value2 ->                Pair(value1, value2)            }.collect {                val spo2Mean = it.first                val HrMean = it.second                if (spo2Mean != null && HrMean != null && !isGraphicalToolTipVisible) {                    Log.i("vlaue_Sdwa", "in inc and dec condition")                    val condition = prefManager?.readSmartFio2()?.toInt()                        ?.plus(prefManager?.readFiO2Dev()!!.toInt())                    // plus code                    Log.i("vlaue_Sdwa", "spo02Mean = $spo2Mean , hrMean = $HrMean")                    Log.i(                        "vlaue_Sdwa",                        "spo2 < targetspo2 = ${spo2Mean <= prefManager?.readTargetSpo2()!!} , hrMean >= hrlimit = ${HrMean >= prefManager?.readHrLimit()!!}"                    )                    Log.i(                        "vlaue_Sdwa",                        "spo2 > targetspo2 = ${spo2Mean > prefManager?.readTargetSpo2()!!} , hrMean < hrlimit = ${HrMean < prefManager?.readHrLimit()!!}"                    )                    if ((spo2Mean <= prefManager?.readTargetSpo2()!!) || (HrMean >= prefManager?.readHrLimit()!!)) {                        primaryControlParameters.let {                            it.forEach {                                if (it.title == "FiO₂") {//                                    decTimer?.onFinish()                                    decTimer?.cancel()                                    isDecreTimerRunning = false                                    // modify value section                                    if (it.reading?.toFloat()?.toInt()!! < condition!!) {                                        if (it.reading?.toFloat()?.toInt()!! in 21..100) {                                            // value set on view                                            prefManager?.setFiO2(                                                if (prefManager?.readFiO2()?.toInt()                                                        ?.plus(1)!! > 100                                                ) 100f                                                else if (prefManager?.readFiO2()?.toInt()                                                        ?.plus(1)!! > condition                                                ) prefManager?.readSmartFio2()?.toInt()?.plus(                                                    prefManager?.readFiO2Dev()!!.toInt()                                                )!!.toFloat()                                                else prefManager?.readFiO2()?.plus(5)                                            )                                            // set default value section if value out of 21 or 100                                            it.reading = prefManager?.readFiO2()?.toInt().toString()                                            Log.i("vlaue_Sdwa", it.reading.toString())                                            primaryControlParameterAdapter?.notifyDataSetChanged()                                        }                                    }                                    // add alarms sections                                    else if (it.reading?.toFloat()                                            ?.toInt()!! >= condition!! || it.reading?.toFloat()                                            ?.toInt()!! == 100                                    ) {                                        if (spo2Mean < prefManager?.readTargetSpo2()!!) {                                            if (prefManager?.readSmartFiO2Status() == true) {                                                addSPO2LowMaxFio2()                                            }                                        } else {                                            removeSPO2LowMaxFio2()                                        }                                        if (HrMean > prefManager?.readHrLimit()!!) {                                            if (prefManager?.readSmartFiO2Status() == true) {                                                addHighPRMaxFio2()                                            }                                        } else {                                            removeHighPRMaxFio2()                                        }                                    }                                }                                sendConfigurationToVentilatorWithWatchDog()                            }                        }                    }                    // minus  code                    else if ((spo2Mean > prefManager?.readTargetSpo2()!!) && (HrMean < prefManager?.readHrLimit()!!)) {                        primaryControlParameters.let {                            it.forEach {                                if (it.title == "FiO₂") {                                    Log.i(                                        "vlaue_Sdwa", "condtion -> ${                                            it.reading?.toFloat()                                                ?.toInt()!! > prefManager?.readSmartFio2()?.toInt()                                                ?.minus(prefManager?.readFiO2Dev()!!.toInt())!!                                        }"                                    )                                    Log.i(                                        "vlaue_Sdwa", "secondconditon -> ${                                            it.reading?.toFloat()?.toInt()!! in 21..100                                        }"                                    )                                    if (it.reading?.toFloat()                                            ?.toInt()!! > prefManager?.readSmartFio2()?.toInt()                                            ?.minus(prefManager?.readFiO2Dev()!!.toInt())!!                                    ) {                                        if (it.reading?.toFloat()?.toInt()!! in 21..100) {                                            it.reading = if (prefManager?.readFiO2()?.toInt()                                                    ?.minus(1)!! <= 21                                            ) "21" else prefManager?.readFiO2()?.toInt()?.minus(1)                                                .toString()                                            Log.i(                                                "vlaue_Sdwa", "in minus condition"                                            )                                            removeHighPRMaxFio2()                                            removeSPO2LowMaxFio2()                                            if (prefManager?.readFiO2()?.minus(1)!! >= 21) {                                                if (isDecreTimerRunning == false) decTimer?.start()                                            }                                        }                                    }                                }                            }                        }                    }                }            }        }    }    // created by masoom on 04 jan 2023    private fun setUpLayoutViaMode() {        Log.i(            "check_vent_mode",            "setUpLayoutViaMode Dashboard ${prefManager?.readVentilationMode().toString()}"        )        Log.i("check_pref", prefManager?.readVentilationMode().toString())        if (prefManager?.readLastVentMode() == Configs.MODE_HFNC) {            button_loop.isEnabled = false            button_graphics.isEnabled = false//            button_alarms.isEnabled = true            button_maneuvers.isEnabled = false            prefManager?.setGraphParentType(parentType.DefaultFragment)            setUpDefaultFragment()        } else {            button_loop.isEnabled = true            button_graphics.isEnabled = true//            button_alarms.isEnabled = true            button_maneuvers.isEnabled = true            prefManager?.setGraphParentType(parentType.DuoFragmentGraph)            onSelectDuoGraph()        }    }    private fun scrollSwappableListUp() = scrollSwappableList(null, Direction.UP)    private fun scrollSwappableListDown() = scrollSwappableList(null, Direction.DOWN)    private fun notifyObserverAboutInhalation() {        mDashBoardViewModel.graphPeekValue.observe(this) {            if (prefManager?.readLastVentMode() != Configs.MODE_VCV_CMV) {                if (isPatientTrigger && it == "A") {                    Log.i("adadwdaw", "true")                    VentilatorApp.isPatientTrigger = true                    ivRespiratoryType.visibility = View.VISIBLE                    ivRespiratoryType.setImageResource(R.drawable.lungs_white)                } else if (isPatientTrigger && it == "D") {                    Log.i("adadwdaw", "false")                    VentilatorApp.isPatientTrigger = false                    ivRespiratoryType.visibility = View.INVISIBLE                    ivRespiratoryType.setImageResource(R.drawable.lungs_white)                    isPatientTrigger = false                }            }            if (it == "B") {                VentilatorApp.isManualBreath = false                imageViewbreathe.visibility = View.GONE            }        }    }    // scroll index at top    private fun scrollSwappableList(index: Int?, direction: Direction) {        (swappableRecyclerView.getLayoutManager() as? LinearLayoutManager)?.apply {            val visibleOnsetCount = index                ?: (findLastCompletelyVisibleItemPosition() - findFirstCompletelyVisibleItemPosition())            val expectedPos = when (direction) {                Direction.UP -> findFirstCompletelyVisibleItemPosition() - visibleOnsetCount                Direction.DOWN -> findLastCompletelyVisibleItemPosition() + visibleOnsetCount            }            val lastPossibleIndex = itemCount - 1            val actualPos = when {                expectedPos in 0..lastPossibleIndex -> expectedPos                expectedPos > lastPossibleIndex -> lastPossibleIndex                else -> 0            }            Log.i("SCROLLCHECK", "Scrolling to ACTUAL $actualPos | EXPECTED $expectedPos")            swappableRecyclerView.smoothScrollToPosition(actualPos)        }    }    private fun renderTopBarViaPreference() {        prefManager?.apply {            if (readCurrentUid() != PatientProfile.TYPE_NEONAT) {                neoSensorView.visibility = View.INVISIBLE            } else {                neoSensorView.visibility = View.VISIBLE            }            if (Gender.TYPE_MALE == readGender()) {                ivRespiratoryType.setImageResource(R.drawable.lungs_white)            } else ivRespiratoryType.setImageResource(R.drawable.lungs_white)            if (readCurrentUid() == PatientProfile.TYPE_NEONAT) {                if (readAge().toInt() == 1) {                    ageView.text = readAge().toInt().toString() + " day"                } else {                    ageView.text = readAge().toInt().toString() + " days"                }            } else {                if (readAge().toInt() == 1) {                    ageView.text = readAge().toInt().toString() + " year"                } else {                    ageView.text = readAge().toInt().toString() + " years"                }//                ageView.text = readAge().toInt().toString() + " years"            }            heightView.text = readBodyHeight().toInt().toString() + " cms"            weightView.text = readBodyWeight().toInt().toString() + " kg"        }    }    /*        private fun renderTopBarViaPreference() {            prefManager?.apply {                if (Gender.TYPE_MALE == readGender()) {                    ivRespiratoryType.setImageResource(R.drawable.lungs_white)                } else ivRespiratoryType.setImageResource(R.drawable.lungs_white)                ageView.text = readAge().toInt().toString() + " years"                heightView.text = readBodyHeight().toInt().toString() + " cms"                weightView.text = readBodyWeight().toInt().toString() + " kg"            }        }*/    private fun initStartVentilationTime() {        val liveData: MutableLiveData<String> = MutableLiveData()        customCountDownTimer = CustomCountDownTimer(liveData)        customCountDownTimer?.start(1000) //Epoch timestamp        customCountDownTimer?.mutableLiveData?.observe(            this,            androidx.lifecycle.Observer { counterState ->                counterState?.let {                    controlDialogFragment?.takeIf { it.isVisible }?.apply {                        setTime(counterState, customCountDownTimer!!)                    }                    mDebugViewModel.ackOccurenceLiveData.postValue(ack756Visibility)                    mDebugViewModel.ventiLiveData.value?.let {                        val dataList = it                        if (dataList.size < 17) {                            dataList.add(VentilatorApp.ventiData)                            mDebugViewModel.ventiLiveData.postValue(dataList)                        } else {                            val newDataList = dataList.subList(1, dataList.size)                            newDataList.add(VentilatorApp.ventiData)                            mDebugViewModel.ventiLiveData.postValue(newDataList)                        }                    } ?: kotlin.run {                        val newDataList = ArrayList<String>()                        newDataList.add(VentilatorApp.ventiData)                        mDebugViewModel.ventiLiveData.postValue(newDataList)                    }                    mDebugViewModel.hidLiveData.value?.let {                        val dataList = it                        if (dataList.size < 17) {                            dataList.add(VentilatorApp.hidData)                            mDebugViewModel.hidLiveData.postValue(dataList)                        } else {                            val newDataList = dataList.subList(1, dataList.size)                            newDataList.add(VentilatorApp.hidData)                            mDebugViewModel.hidLiveData.postValue(newDataList)                        }                    } ?: kotlin.run {                        val newDataList = ArrayList<String>()                        newDataList.add(VentilatorApp.hidData)                        mDebugViewModel.hidLiveData.postValue(newDataList)                    }                    CoroutineScope(Dispatchers.Main).launch {                        if (countBatteryData == 10 && dataStoreManager?.getDashRebootStatusFlag()                                ?.first() == true                        ) {                            dataStoreManager?.saveDashRebootStatusFlag(false)                            sendBroadcast(Intent(IntentFactory.ACTION_VENTILATOR_FAILURE_REMOVED))                            addEventsForDevelopers(                                "Re-Initiate Handshake Due to Spo2 Data Not Available during ventilation",                                prefManager?.readUHID().toString()                            )                            isForKnob = false                            onDeviceConnect()                        } else if (countBatteryData == 10 && dataStoreManager?.getDashRebootStatusFlag()                                ?.first() == false                        ) {                            addEventsForDevelopers(                                "Show Alarm Due to Spo2 Data Not Available during ventilation",                                prefManager?.readUHID().toString()                            )                            sendBroadcast(Intent(IntentFactory.ACTION_VENTILATOR_FAILURE_GENERATED))                        }                        countBatteryData++                    }                    setDateTime(counterState)                    globalCount++                    println(counterState)                }            })    }    private fun setDateTime(counterState: String) {        timeView.text = AppUtils.getCurrentTime()        dateView.text = AppUtils.getCurrentDate()    }    private fun alarmMute() {        communicationService?.takeIf { it.isPortsConnected }?.apply {            send(getString(R.string.cmd_vent_mute_alarm_permanent))        }        // change here 19 sep        mediaPlayer?.setVolume(0.0f, 0.0f)        alarmcount.visibility = View.VISIBLE        tvalarm.visibility = View.VISIBLE        alarmPanel.setBackgroundColor(ContextCompat.getColor(this, R.color.yellow_dark))        imageViewAlarm.setImageDrawable(            ContextCompat.getDrawable(                applicationContext, // Context                R.drawable.ic_mute_alarm // Drawable            )        )        muteUnMuteTimer = object : CountDownTimer(120000, 1000) {            override fun onTick(milliSec: Long) {                alarmcount.text = "${(milliSec / 1000)} s"            }            override fun onFinish() {                alarmcount.visibility = View.GONE                tvalarm.visibility = View.GONE                alarmPanel.setBackgroundColor(                    ContextCompat.getColor(                        this@DashBoardActivity, R.color.black                    )                )                // change here 19 sep                isAlarmMuted = false                try {                    if (isAlarmPlaying) {                        prefManager?.apply {                            mediaPlayer?.setVolume(                                readVolume() / VOLUME_MAX_VALUE, readVolume() / VOLUME_MAX_VALUE                            )                        }                    }                } catch (e: Exception) {                    e.printStackTrace()                }                alarmcount.visibility = View.GONE                tvalarm.visibility = View.GONE                imageViewAlarm.setImageDrawable(                    ContextCompat.getDrawable(                        applicationContext, // Context                        R.drawable.ic_unmute_alarm // Drawable                    )                )                muteUnMuteTimer.cancel()            }        }.start()        addEvents("Alarm are muted", prefManager?.readUHID().toString())    }    private fun alarmUnMute() {        communicationService?.takeIf { it.isPortsConnected }?.apply {            send(getString(R.string.cmd_vent_unmute_alarm))        }        addEvents("Alarm are unmuted", prefManager?.readUHID().toString())        muteUnMuteTimer.cancel()        alarmPanel.setBackgroundColor(ContextCompat.getColor(this, R.color.black))        alarmcount.visibility = View.GONE        tvalarm.visibility = View.GONE        imageViewAlarm.setImageDrawable(            ContextCompat.getDrawable(                applicationContext, // Context                R.drawable.ic_unmute_alarm // Drawable            )        )        // change here 19 sep        try {            if (isAlarmPlaying) {                prefManager?.apply {                    mediaPlayer?.setVolume(                        readVolume() / VOLUME_MAX_VALUE, readVolume() / VOLUME_MAX_VALUE                    )                }            }        } catch (e: Exception) {            e.printStackTrace()        }    }    private fun alarmMuteUnMuteVisibility() {        if (!isLocked) {            if (isAlarmMuted) {                alarmUnMute()                isAlarmMuted = false            } else {                alarmMute()                isAlarmMuted = true            }        } else {            DialogBoxFactory.dismissDialogs()            DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)        }    }    private fun initData() {        createAndRenderAllTiles()        SciChartBuilder.init(this)        //setUpDivideQuadFragment()        setUpLayoutViaMode()        //onSelectTrioGraph()        setUpOnClickListener()        doBindService()    }    var dataStoreModelAvg = DataStoreModel()    //Operational hours in hours and minutes.    lateinit var serviceHourCountdowntimer: CountDownTimer    //Operational hours in hours and minutes.    private fun countDownTimerForServiceHour() {        serviceHourCountdowntimer = object : CountDownTimer(120000, 1000) {            override fun onTick(milliSec: Long) {                mDashBoardViewModel.OPHours.value = prefManager?.readOperationalHoursStartTime()                    ?.let { calculateOperationalHourInTime(it, System.currentTimeMillis()) }                mDashBoardViewModel.serviceHours.value =                    prefManager?.readServiceHoursStartTime()?.let {                        calculateServiceHourInTime(it, System.currentTimeMillis())                    }            }            override fun onFinish() {                serviceHourCountdowntimer.start()            }        }.start()    }    //Service hours in hours and minutes.    private fun calculateServiceHourInTime(startTimeInMillis: Long, endTimeInmillis: Long): String {        val accesstime = lastServiceRunningTime        val totalRunningTime = currentTimeMillis() - startTimeInMillis + accesstime        Log.i("value_of_sesdwad", totalRunningTime.toString())        val hr = TimeUnit.MILLISECONDS.toHours(totalRunningTime)        val min = TimeUnit.MILLISECONDS.toMinutes(totalRunningTime) - TimeUnit.HOURS.toMinutes(            TimeUnit.MILLISECONDS.toHours(totalRunningTime)        )        prefManager?.apply {            val accessTimeForService = lastServiceRunningTime            this.setDashBoardRunningTimeForService(accessTimeForService.plus(currentTimeMillis() - this.readServiceHoursStartTime()))        }        return String.format("%d hr, %d min", hr, min)    }    private fun calculateTotalAndLastHours(        millis: Long    ): String {        return String.format(            "%02d:%02d:%02d",            TimeUnit.MILLISECONDS.toHours(millis),            TimeUnit.MILLISECONDS.toMinutes(millis) % TimeUnit.HOURS.toMinutes(1),            TimeUnit.MILLISECONDS.toSeconds(millis) % TimeUnit.MINUTES.toSeconds(1)        )    }    //Operational hours in hours and minutes.    private fun calculateOperationalHourInTime(        startTimeInMillis: Long, endTimeInmillis: Long    ): String {        val accessTime = lastDashboardRunningTime//        val accesstime = prefManager?.readDashBoardRunningTime()?.toLong() ?: 0L        val totalRunningTime = currentTimeMillis() - startTimeInMillis + accessTime        val hr = TimeUnit.MILLISECONDS.toHours(totalRunningTime)        val min = TimeUnit.MILLISECONDS.toMinutes(totalRunningTime) - TimeUnit.HOURS.toMinutes(            TimeUnit.MILLISECONDS.toHours(totalRunningTime)        );        val totalOperationalHours = String.format(            "%d hr, %d min", hr, min        );        prefManager?.apply {            // save current dashboard running time            val accessTime = lastDashboardRunningTime            //Operational hours in hours and minutes.            this.setDashBoardRunningTime(accessTime.plus(currentTimeMillis() - readOperationalHoursStartTime()))        }        return totalOperationalHours    }    override fun onPause() {        VentilatorApp.isNebuliserActive = true        try {            mediaPlayer?.takeIf { it.isRunning }?.run {                stop()                release()                null            }            socket.close()        } catch (e: Exception) {            e.printStackTrace()        }        Log.i("CHECK_ONPAUSE", "on pause called")        //        if (!isSocketStop) {            VentilatorApp.isLiveDataRequest = false            VentilatorApp.isLiveGraphDataRequest = false            mSocket?.emit("AndroidStopAuto", deviceId)        }        mSocket?.emit("AndroidDisconnect", deviceId)        mSocket?.disconnect()        VentilatorApp.isPatientTrigger = false        isPatientTrigger = false        ivRespiratoryType.visibility = View.INVISIBLE        ivRespiratoryType.setImageResource(R.drawable.lungs_white)        dataStoreManager?.apply {            CoroutineScope(Dispatchers.IO).launch {                // set last hours and total hours                saveLastHours(abs(startTimeDashboard - currentTimeMillis()))                saveTotalHours(getLastHours().first().toLong() + getTotalHours().first().toLong())                Log.i(                    "check_total_timing",                    getLastHours().first().toString() + " , " + getTotalHours().first().toString()                )            }        }        oxygenTimer?.cancel()        oxygenTimer = null        freezeTimer.onFinish()        prefManager?.setGraphParentType(parentType.TrioFragmentGraph)        // stop smart fio2 algo on activity change        mDashBoardViewModel.SmartSpo2Toggle.tryEmit(false)        mDashBoardViewModel.hrSpo2DataStreaming.tryEmit(false)        mDashBoardViewModel.spo2hrDataStreaming.tryEmit(false)        DialogBoxFactory.dismissDialogs()        super.onPause()    }    override fun onStop() {        super.onStop()        unregisterReceiver(gattReceiver)    }    override fun onDestroy() {        settingsCountDownTimer?.safeStop()//        operatingHoursTimer?.onFinish()        VentilatorApp.selectedOptions = null        settingsCountDownTimer = null        customCountDownTimer?.stop()        serviceHourCountdowntimer.cancel()        stopPinging()        doUnbindService()        handler?.removeCallbacksAndMessages(null);        isFromControlFragment = null        hideStandByDialog()        super.onDestroy()    }    // ClickListener on Buttons    private fun setUpOnClickListener() {        standbyLayout.setOnClickListener { showStandbyConfirmation() }        layoutFreezeData.setOnClickListener {            if (freezeGraph) freezeTimer.onFinish()            else {                mDashBoardViewModel.graphFreeze.postValue(true)                freezeTimer.start()            }        }        modeButtonLayout.setOnClickListener {            if (!isLocked) {                layoutFreezeData.visibility = View.GONE                showModeFragment()            } else {                DialogBoxFactory.dismissDialogs()                DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)            }        }        button_monitoring.setOnClickListener {            layoutFreezeData.visibility = View.GONE            showMonitoringFragment()        }        button_graphics.setOnClickListener {            layoutFreezeData.visibility = View.GONE            showLayoutFragment()        }        button_maneuvers.setOnClickListener {            if (!isLocked) {                if (prefManager?.readCurrentUid() == PatientProfile.TYPE_NEONAT) {                    DialogBoxFactory.showNeonateSensorDialog(                        this@DashBoardActivity, "Manuevers not available"                    )                } else {                    if (prefManager?.readLastVentMode() == Configs.MODE_NIV_CPAP || prefManager?.readLastVentMode() == Configs.MODE_NIV_NCPAP || prefManager?.readLastVentMode() == Configs.MODE_NC_IPPV) {//                button_maneuvers.isEnabled = false                        DialogBoxFactory.dismissDialogs()                        DialogBoxFactory.showNeonateSensorDialog(                            this@DashBoardActivity, "Manuevers not available"                        )                    } else if (prefManager?.readLastVentMode() == Configs.MODE_NIV_NBPAP || prefManager?.readLastVentMode() == Configs.MODE_NIV_BPAP) {//                button_maneuvers.isEnabled = false                        DialogBoxFactory.dismissDialogs()                        DialogBoxFactory.showNeonateSensorDialog(                            this@DashBoardActivity, "Manuevers not available"                        )                    } else {                        layoutFreezeData.visibility = View.GONE                        isFromKnob = ""                        showManeuversFragment()                    }                }            } else {                DialogBoxFactory.dismissDialogs()                DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)            }        }        button_logs.setOnClickListener {            layoutFreezeData.visibility = View.GONE            showLogsFragment()        }        button_systems.setOnClickListener {            layoutFreezeData.visibility = View.GONE            showSystemFragment()        }        button_modes.setOnClickListener {            if (!isLocked) {                layoutFreezeData.visibility = View.GONE                showModeFragment()            } else {                DialogBoxFactory.dismissDialogs()                DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)            }        }        var bundle = Bundle()        bundle.putString("passing", "fromPatient")        button_controls.setOnClickListener {            if (!isLocked) {                layoutFreezeData.visibility = View.GONE                showControlFragment(bundle, "nonpatient")            } else {                DialogBoxFactory.dismissDialogs()                DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)            }        }        button_more_controls.setOnClickListener {            if (!isLocked) {                layoutFreezeData.visibility = View.GONE                if (button_controls.isEnabled) button_controls.callOnClick()            } else {                DialogBoxFactory.dismissDialogs()                DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)            }        }        button_alarms.setOnClickListener {            layoutFreezeData.visibility = View.GONE            showAlarmFragment(Bundle().apply { putString("fragment_val", "FromButton") })        }        button_loop.setOnClickListener {            prefManager?.setGraphParentType(parentType.LoopsFragmentGraph)            button_loop.setBackgroundResource(R.drawable.background_white_border_white)            button_loop.setTextColor(                ContextCompat.getColor(                    this@DashBoardActivity, R.color.black                )            )            onSelectLoopsGraph()            Handler(Looper.getMainLooper()).postDelayed(                {                    button_loop.setBackgroundResource(R.drawable.background_black_border_black)                    button_loop.setTextColor(                        ContextCompat.getColor(                            this@DashBoardActivity, R.color.dim_grey                        )                    )                    //checkDialogPresence()                }, 1000            )            hideAllAlertDialogBox()            hideKnobViews()            hideAllDialogFragment()            onSelectLoopsGraph()            checkDialogPresence()        }    }    private fun observeGraphFreeze() {        mDashBoardViewModel.graphFreeze.observe(this) {            if (it) {                freezeGraph = true                freeze_img.setBackgroundResource(R.drawable.forzen)            } else {                freezeGraph = false                freeze_img.setBackgroundResource(R.drawable.freeze)            }        }    }    private fun freezeGraphTimer() {        freezeTimer = object : CountDownTimer(15000, 1000) {            override fun onTick(millisUntilFinished: Long) {            }            override fun onFinish() {                mDashBoardViewModel.graphFreeze.postValue(false)            }        }    }    fun sendCommandForChangeXAxisGraph(value: String) {        communicationService?.takeIf { it.isPortsConnected }?.apply {            send(getString(R.string.hint_command_graph_xvalue) + value)        }    }    private fun showAlarmFragment(bundle: Bundle? = null) {        closeSwappableLayout()        val isNotEqual =            alarmDialogFragment?.arguments?.get("fragment_val") != bundle?.get("fragment_val")        if (alarmDialogFragment == null || isNotEqual) {            alarmDialogFragment = AlarmDialogFragment.newInstance(                heightSize,                widthSize,                communicationService,                this,                this,            )        }        alarmDialogFragment?.let {            alarmDialogFragment?.arguments = bundle            supportFragmentManager.apply {                beginTransaction().replace(                    R.id.dashboardFragment_nav_container, it, AlarmDialogFragment.TAG                ).commitNow()            }        }        checkDialogPresence()    }    private fun showStandbyControlFragment() {        layoutFreezeData.visibility = View.GONE        VentilatorApp.testingConditonMap.values.clear()        // open standby after control fragment then        if (isFromControlFragment == null) VentilatorApp.IERatio = prefManager?.readRR()            ?.let { Configs.calculateIERatio(it.toInt(), prefManager?.readTinsp()) }.toString()        isFromControlFragment = null        val controlParameters = filterControlParameterViaMode(            this@DashBoardActivity,            modeCode,            getAllControlParameterLists(this@DashBoardActivity, modeCode).flatten()        )        basicParams = null        advancedParams = null        vTasParams = null        etCuffParams = null        backupParams = null        smartFioParams = null        controlParameters[ControlSettingType.BASIC]?.let {            basicParams = it        }        controlParameters[ControlSettingType.BACKUP]?.let {            backupParams = it        }        controlParameters[ControlSettingType.ADVANCED]?.let {            advancedParams = it        }        controlParameters[ControlSettingType.SmartFio2]?.let {            smartFioParams = it        }        controlParameters[ControlSettingType.VTas]?.let {            vTasParams = it        }        controlParameters[ControlSettingType.EtCuff]?.let {            etCuffParams = it        }        if (VentilatorApp.selectedOptions == SELECTED_OPTIONS.NON_INVASIVE_NAME) {            if (modeCode == MODE_NIV_BPAP || modeCode == MODE_NIV_CPAP) {                advancedParams?.filter {                    it.ventKey == LBL_TEXP                }?.apply {                    this[0].reading = 75.0f.toInt().toString()                }            } else {                advancedParams?.filter {                    it.ventKey == LBL_TEXP                }?.apply {                    if (this.isNotEmpty()) {                        this[0].reading = 75.0f.toInt().toString()                    }                }            }        } else {            if (modeCode == MODE_NIV_BPAP || modeCode == MODE_NIV_CPAP) {                advancedParams?.filter {                    it.ventKey == LBL_TEXP                }?.apply {                    this[0].reading = 50.0f.toInt().toString()                }            } else {                advancedParams?.filter {                    it.ventKey == LBL_TEXP                }?.apply {                    if (this.isNotEmpty()) {                        this[0].reading = 50.0f.toInt().toString()                    }                }            }        }        Log.i("backup_check", backupParams.toString())        Log.i(            "VTAS_CHECK",            prefManager?.readVGVStatus().toString() + prefManager?.readVGVStatusTemp().toString()        )        prefManager?.apply {            if (this@DashBoardActivity.lastUhid != readUHID() && (backupParams == null || backupParams?.isEmpty() == true)) {                Log.i("backup_value", "1")                setIRVStatusTemp(true)                setApneaSettingsStatusTemp(false)            } else if (this@DashBoardActivity.lastUhid == readUHID() && (backupParams == null || backupParams?.isEmpty() == true)) {                Log.i("backup_value", "2")                setIRVStatusTemp(readIRVStatus())                setApneaSettingsStatusTemp(false)            } else if (this@DashBoardActivity.lastUhid != readUHID() && (backupParams != null || backupParams?.isEmpty() == false)) {                Log.i("backup_value", "3")                setIRVStatusTemp(true)                setApneaSettingsStatusTemp(true)            } else if (this@DashBoardActivity.lastUhid == readUHID() && (backupParams != null || backupParams?.isEmpty() == false)) {                Log.i("backup_value", "4")                setIRVStatusTemp(readIRVStatus())                setApneaSettingsStatusTemp(readApneaSettingsStatusTemp())            }        }        standbyControlFragment = basicParams?.let {            StandbyControlDialogFragment.newInstance(                height = heightSize,                width = widthSize,                status = false,                basicParams = it,                advancedParams = advancedParams,                backupParams = backupParams,                smartFio2Params = smartFioParams,                vTasParams = vTasParams,                etCuffParams = etCuffParams,                closeListener = standbyControlDismissListener,                basicParameterClickListener = getStandbyParameterClickListener(                    it, ControlSettingType.BASIC                ),                advancedParameterClickListener = getStandbyParameterClickListener(                    advancedParams, ControlSettingType.ADVANCED                ),                backupParameterClickListener = getStandbyParameterClickListener(                    backupParams, ControlSettingType.BACKUP                ),                smartFio2ParameterClickListener = getStandbyParameterClickListener(                    smartFioParams, ControlSettingType.SmartFio2                ),                vTasParameterClickListener = getStandbyParameterClickListener(                    vTasParams, ControlSettingType.VTas                ),                etCuffParameterClickListener = getStandbyParameterClickListener(                    etCuffParams, ControlSettingType.EtCuff                ),                onStartVentilationListener = startNewVentilationListener            )        }        standbyControlFragment?.let {            supportFragmentManager.apply {                beginTransaction().replace(                    R.id.dashboardFragment_nav_container, it, "FromDashBoardActivity"                ).commitNow()            }        }        checkDialogPresence()    }    private fun showControlFragment(bundle: Bundle? = null, tag: String?) {        testingConditonMap.clear()        isFromControlFragment = true        closeSwappableLayout()        val isNotPatient =            controlDialogFragment?.arguments?.get("fragment_patient") != bundle?.get("fragment_patient")        controlDialogFragment = null        Log.i("value_backup", backupControlParameterList.toString())        if (controlDialogFragment == null || isNotPatient) {            controlDialogFragment = ControlDialogFragment.newInstance(                height = heightSize,                width = widthSize,                basicParams = basicControlParameterList?.filter { it.isVoid },                // ensure that no blank tiles are sent                advancedParams = advancedControlParameterList?.filter { it.isVoid },                backupParams = backupControlParameterList?.filter { it.isVoid },                // ensure that no blank tiles are sent                smartFio2Params = smartFio2ControlParameterList?.filter { it.isVoid },                vTasParams = vTasControlParameterList?.filter { it.isVoid },                etCuffParams = etCuffControlParameterList?.filter { it.isVoid },                closeListener = controlDismissListener,                basicParameterClickListener = onBasicParameterClickListener,                advancedParameterClickListener = onAdvancedParameterClickListener,                backupParameterClickListener = onBackupParameterClickListener,                smartFio2ParameterClickListener = onSmartFio2ParamterClickListener,                vTasParameterClickListener = onVTasParamterClickListener,                etCuffParameterClickListener = onEtCuffParamterClickListener,                onToggledListener = { _, isOn -> communicationService?.sendConfigurationToVentilator() })        }        controlDialogFragment?.also {            controlDialogFragment?.arguments = bundle        