eSwappableLayout()        filterObserverParameterList()        if (monitoringDialogFragment == null) {            monitoringDialogFragment = MonitoringDialogFragment.newInstance(                heightSize, widthSize, observedValueList, observedValueSpHOList, this            )        }        monitoringDialogFragment?.let {            supportFragmentManager.apply {                beginTransaction().replace(                    R.id.dashboardFragment_nav_container, it, MonitoringDialogFragment.TAG                ).commitNow()            }        }        checkDialogPresence()    }    private fun showModeFragment() {        closeSwappableLayout()        if (modeDialogFragment == null) {            modeDialogFragment = ModeDialogFragment.newInstance(                heightSize, widthSize, true, onModeConfirmListener = modeConfirmListener, this            )        }        modeDialogFragment?.let {            supportFragmentManager.apply {                beginTransaction().replace(                    R.id.dashboardFragment_nav_container, it, "DashboardActivity"                ).commitNow()            }        }        checkDialogPresence()    }    private fun showShutDownProgress(txt: String) {        if (shutDownProgress == null) {            shutDownProgress = ProgressDialog(this)            shutDownProgress?.setCancelable(false)        }        shutDownProgress?.setMessage(txt)        shutDownProgress?.show()    }    private fun hideShutDownDialog() {        shutDownConfirmDialog?.takeIf { it.isShowing }?.apply {            dismiss()        }    }    fun hideShutDownProgress() {        shutDownProgress?.apply {            cancel()        }    }    private fun hideShutDownConfirmation() {        shutDownConfirmDialog?.apply {            cancel()        }    }//Same as this to be implemented in the critical battery low code.    private fun showStandbyConfirmation() {        var dialogDisplayMessage = ""        if (standByConfirmDialog?.isShowing() == true) return;        if (ackVisibilities[5] == true) {            dialogDisplayMessage = this.getString(R.string.patient_disconnected_standby)            //Main message of the dialog.            standByConfirmDialog =                DialogBoxFactory.showVentilationStatusDialog(dialogDisplayMessage, this) { ->                    DialogBoxFactory.showShutDownStatusDialog(                        "Initiating Standby", this@DashBoardActivity                    )                    addEvents("Standby Requested", prefManager?.readUHID().toString())                    lifecycleScope.launch(Dispatchers.IO) {                        sendStandbyCommandToVentilator()                        delay(5000L)                        if (dataStoreManager?.getStandByCheckFlag()?.first() == false) {                            sendStandbyCommandToVentilator()                        }                    }                }        } else {            dialogDisplayMessage = this.getString(R.string.patient_connected_standby)            standByConfirmDialog =                DialogBoxFactory.showVentilationStatusDialog(dialogDisplayMessage, this) { ->                    DialogBoxFactory.showShutDownStatusDialog(                        "Initiating Standby", this@DashBoardActivity                    )                    addEvents("Standby Requested", prefManager?.readUHID().toString())                    lifecycleScope.launch(Dispatchers.IO) {                        sendStandbyCommandToVentilator()                        delay(5000L)                        if (dataStoreManager?.getStandByCheckFlag()?.first() == false) {                            sendStandbyCommandToVentilator()                        }                    }                }        }    }    private fun showStandByProgress(txt: String) {        if (standByProgress == null) {            standByProgress = ProgressDialog(this)      