ousFragment == null || currentFragment != previousFragment) {            previousFragment = fragmentGraph            supportFragmentManager.apply {                beginTransaction().replace(                    R.id.dashboard_nav_container, fragmentGraph, fragmentGraph.name                ).commitNow()            }            resetGraphCounter()        }    }    private fun resetGraphCounter() {        pCount = 0        eCount = 0        vCount = 0        fCount = 0    }    override fun onWindowFocusChanged(hasFocus: Boolean) {        super.onWindowFocusChanged(hasFocus)        Log.i("FOCUSCHECK", "Focus state = $hasFocus")        hideSystemUI()        checkDialogPresence()        if (knobDialog?.isVisible == false) normaliseParameterTiles()//        knobDialog?.apply {//            if (isVisible || !isVisible) {//                hideSystemUI()//            }//        }    }    private fun checkDialogPresence() {        Log.i("vakuessdaw", "2")        hideKnobViews()        isFromKnob = ""        val visibleDialogFragment: Fragment? =            fragmentManager.findFragmentById(R.id.dashboardFragment_nav_container)        if (visibleDialogFragment is MonitoringDialogFragment) {            button_monitoring.setBackgroundResource(R.drawable.background_white_border)            button_monitoring.setTextColor(                ContextCompat.getColor(                    this@DashBoardActivity, R.color.black                )            )        } else {            button_monitoring.setBackgroundResource(R.drawable.background_black)            button_monitoring.setTextColor(                ContextCompat.getColor(                    this@DashBoardActivity, R.color.dim_grey                )            )        }        if (visibleDialogFragment is GraphicsDialogFragment) {            button_graphics.setBackgroundResource(R.drawable.background_white_border)            button_graphics.setTextColor(                Co