ake_check", "onServiceConnect Second")                    communicationService?.takeIf { it.isPortsConnected }?.apply {                        if (!isReadingFromConnection) {                            Log.i(                                "SERVICE_CHECK",                                "connection status = $isPortsConnected during DEVICE_CONNECTED check"                            )                            isReadingFromConnection = true                            startReading()                            startPinging()                        }                    }                }            }        }        override fun onServiceDisconnected(name: ComponentName) {            isServiceBound = false        }    }    /*    * This method binds the required services    * and set the flags to active    */    private fun doUnbindService() {        if (isServiceBound) {            try {                unbindService(mServiceConnection)                Log.i("COMM_SERVICE_CHECK", "service disconnected ")                isServiceBound = false            } catch (e: IllegalArgumentException) {                e.printStackTrace()            }        }        stopService(serviceIntent)    }    private fun doBindService() {        if (!isServiceBound) {            serviceIntent = Intent(this, UsbService::class.java)            bindService(serviceIntent, mServiceConnection, BIND_AUTO_CREATE)            Log.i("COMM_SERVICE_CHECK", "service connected ")            isServiceBound = true        }        startService(serviceIntent)//        if (!UsbService.isServiceConnect) {//            val startService = Intent(this, UsbService::class.java)//            startService(startService)//        }//        val bindingIntent = Intent(this, UsbService::class.java)//        bindService(bindingIntent, mServiceConnection, BIND_AUTO_CREATE)    }    /*    * Inflating general info tiles and configuring their styles     */    private fun createAndRenderAllTiles() {        // set Observe tiles Side Panel Monitoring -> General Fragment        // and set Observe titles Side Panel SpO2 -> General Fragment        prefManager?.readLastVentMode()?.apply {            Log.i("MODECHECK", "CODE = $this")            createObservedParameterList(this)            renderObservedDataTiles(this)            createControlParameterTiles(this)            renderControlParameterTiles(this)        }        //Action Adapter Code        setupActionParameterAdapter()    }    private fun renderAllTiles() {        Log.i(            "check_vent_mode",            "renderAllTiles Dashboard ${prefManager?.readVentilationMode().toString()}"        )        // set Observe tiles Side Panel Monitoring -> General Fragment        prefManager?.readVentilationMode()?.apply { renderObservedDataTiles(this) }        // set Ventilator Parameter        prefManager?.readVentilationMode()?.apply {            renderControlParameterTiles(this)        }    }    private fun createSecondaryObservedList(containerList: List<ObservedParameterModel>) {        val defaultSecondaryObservedParameters = listOf<String>(            LBL_SPO2,            LBL_HR,        )        // perform mapping        containerList.filter {            defaultSecondaryObservedParameters.contains(it.label + it.labelSubscript)        }.apply {            for (tile in this) {                observedValueSpHO2Map.put(tile.label + tile.labelSubscript, tile)            }        }    }    private fun renderSecondaryObservedList() {        observedValueSpHOList.clear()        observedValueSpHO2Map.forEach {            observedValueSpHOList.add(it.value)        }        setSecondaryObservedParameterAdapter()    }    private fun createObservedParameterList(modeCode: Int) {        val containerList = arrayListOf<ObservedParameterModel>()        prefManager?.apply {            ObservedParameterModel(                L