       for (tile in this) {                       primaryTileMap.put(tile.label + tile.labelSubscript, tile)                       Log.i("OBSERVED_PARAMS_CHECK","${tile.label + tile.labelSubscript}")                   }               }           }       }*/    private fun createPrimaryObservedDataTiles(        modeCode: Int, containerList: List<ObservedParameterModel>    ) {        if (modeCode == MODE_HFNC) {            primaryTileMap.clear()            val defaultPrimaryObservedParametersNeonate =                prefManager?.readPrimaryObservedParamsNeonate()?.toList()            if (defaultPrimaryObservedParametersNeonate != null) {                Log.i("Listed_Values", defaultPrimaryObservedParametersNeonate.toString())                // perform mapping                containerList.filter {                    defaultPrimaryObservedParametersNeonate.contains(it.label + it.labelSubscript)                }.apply {                    for (tile in this) {                        primaryTileMap.put(tile.label + tile.labelSubscript, tile)                        Log.i("OBSERVED_PARAMS_CHECK", "${tile.label + tile.labelSubscript}")                    }                }            }        } else if (modeCode == MODE_NC_CPAP) {            primaryTileMap.clear()            val defaultPrimaryObservedParametersNasalProngs =                prefManager?.readPrimaryObservedParamsNasalProngs()?.toList()            if (defaultPrimaryObservedParametersNasalProngs != null) {                Log.i("Listed_Values", defaultPrimaryObservedParametersNasalProngs.toString())                // perform mapping                containerList.filter {                    defaultPrimaryObservedParametersNasalProngs.contains(it.label + it.labelSubscript)                }.apply {                    for (tile in this) {                        primaryTileMap.put(tile.label + tile.labelSubscript, tile)                        Log.i("OBSERVED_PARAMS_CHECK", "${tile.label + tile.labelSubscript}")                    }                }            }        } else {            primaryTileMap.clear()            val defaultPrimaryObservedParameters =                prefManager?.readPrimaryObservedParams()?.toList()            if (defaultPrimaryObservedParameters != null) {                Log.i("Listed_Values", defaultPrimaryObservedParameters.toString())                // perform mapping                containerList.filter {                    defaultPrimaryObservedParameters.contains(it.label + it.labelSubscript)                }.apply {                    for (tile in this) {                        primaryTileMap.put(tile.label + tile.labelSubscript, tile)                        Log.i("OBSERVED_PARAMS_CHECK", "${tile.label + tile.labelSubscript}")                    }                }            }        }    }    private fun renderPrimaryObservedDataTiles() {        selectedTiles.clear()        primaryTileMap.forEach {            selectedTiles.add(it.value)        }        setUpPrimaryObservedParameterAdapter()    }    private fun createControlParameterTiles(modeCode: Int) {        Log.i("MODECHECK", "CODEIn = $modeCode")        // perform mapping        getAllControlParameterLists(this, modeCode).apply {            ventBasicParameterMap.clear()            ventAdvancedParameterMap.clear()            ventBackupParameterMap.clear()            ventSmartFio2ParameterMap.clear()            ventVTasParameterMap.clear()            ventEtCuffParameterMap.clear()            this.getOrNull(0)?.let { basicParams ->                for (tile in basicParams) {                    ventBasicParameterMap.put(tile.ventKey.toString(), tile)                }            }            this.getOrNull(1)?.let { advancedParams ->                for (tile in advancedParams) {                    ventAdvancedParameterMap.put(tile.ventKey.toString(), tile)                }            }            this.getOrNull(2)?.let { backupParams ->                for (tile in backupParams) {                    ventBackupParameterMap.put(tile.ventKey.toString(), tile)                }            }            this.getOrNull(3)?.let { smartFio2Params ->                for (tile in smartFio2Params) {                    ventSmartFio2ParameterMap.put(tile.ventKey.toString(), tile)                }            }            this.getOrNull(4)?.let { vTasParams ->                for (tile in vTasParams) {                    ventVTasParameterMap.put(tile.ventKey.toString(), tile)                }            }            this.getOrNull(5)?.let { etCuffParams ->                for (tile in etCuffParams) {                    ventEtCuffParameterMap.put(tile.ventKey.toString(), tile)                }            }        }    }    private fun renderControlParameterTiles(modeCode: Int) {        basicControlParameterList.clear()        backupControlParameterList?.clear()        advancedControlParameterList.clear()        smartFio2ControlParameterList.clear()        vTasControlParameterList.clear()        etCuffControlParameterList.clear()        val voidTile = ControlParameterModel(            LBL_VOID_TILE, "", "", "", 0.0, 0.0, 0.0        )        // modifying parameter names according to modes        ventBasicParameterMap.apply {            val peep = this[LBL_PEEP]?.apply { this.title = getString(R.string.peep) }            val triggerFlow = this[LBL_TRIG_FLOW]?.apply {                this.title = getString(R.string.trigger_flow)            }            val pPlat = this[LBL_PPLAT]?.apply {                if (modeCode == MODE_PC_PSV) this.title = getString(R.string.support_pressure)                else this.title = getString(R.string.pinsp)            }            val vti = this[LBL_VTI]?.apply { this.title = getString(R.string.vti) }            // val pip = this[LBL_PIP]?.apply { this.title = getString(R.string.plimit) }            val rr = this[LBL_RR]?.apply { this.title = getString(R.string.respiratory_rate) }            val tInsp = this[LBL_TINSP]?.apply { this.title = getString(R.string.inhale_time) }            val fio2 = this[LBL_FIO2]?.apply { this.title = getString(R.string.fio2) }            val supportPressure = this[LBL_SUPPORT_PRESSURE]?.apply {                this.title = getString(R.string.support_pressure)            }            Log.i("iu565765", fio2.toString())            // val slope = this[LBL_SLOPE]?.apply { this.title = getString(R.string.slope) }            val tLow = this[LBL_TLOW]?.apply { this.title = getString(R.string.tLow) }            //    val texp = this[LBL_TEXP]?.apply { this.title = getString(R.string.tExp) }            when (modeCode) {                MODE_VCV_CMV -> {                    modeType.text = getString(R.string.hint_vc_cmv)                }                MODE_VCV_ACV -> {                    modeType.text = getString(R.string.hint_vc_cv)                }                MODE_VCV_SIMV -> {                    modeType.text = getString(R.string.hint_vc_simv)                }                MODE_PC_CMV -> {                    modeType.text = getString(R.string.hint_pc_cmv)                }                MODE_PC_SIMV -> {                    modeType.text = getString(R.string.hint_pc_simv)                }                MODE_PC_AC -> {                    modeType.text = getString(R.string.hint_spont)                }                MODE_PC_ARPV -> {                    modeType.text = getString(R.string.hint_pc_aprv)                }                MODE_PC_PSV -> {                    modeType.text = getString(R.string.hint_psv)                }                MODE_PC_PRVC -> {                    modeType.text = getString(R.string.hint_prvc)                }                MODE_HFNC -> {//                    modeType.text = getString(R.string.hint_pc_aprv)                    pPlat?.title = getString(R.string.phigh) // PHigh                    tInsp?.title = getString(R.string.thigh) // THigh                    peep?.title = getString(R.string.plow) // PLow                    if (prefManager?.readCurrentUid() == Configs.PatientProfile.TYPE_NEONAT) modeType.text =                        getString(R.string.NeoNatehfnc) else modeType.text =                        getString(R.string.hfnc)                }                MODE_AUTO_VENTILATION -> {                    modeType.text = getString(R.string.hint_ai_vent)                }                MODE_NIV_BPAP -> {                    if (prefManager?.readCurrentUid() == Configs.PatientProfile.TYPE_NEONAT) modeType.text =                        getString(R.string.hint_nbpap) else modeType.text =                        getString(R.string.hint_bpap)                }                MODE_NC_IPPV -> {                    if (prefManager?.readCurrentUid() == Configs.PatientProfile.TYPE_NEONAT) modeType.text =                        getString(R.string.hint_nc_cpap) else modeType.text =                        getString(R.string.hint_nc_cpap)                }                MODE_NIV_CPAP -> {                    if (prefManager?.readCurrentUid() == Configs.PatientProfile.TYPE_NEONAT) modeType.text =                        getString(R.string.hint_ncpap) else modeType.text =                        getString(R.string.hint_cpap)                }                MODE_NC_CPAP -> {                    if (prefManager?.readCurrentUid() == Configs.PatientProfile.TYPE_NEONAT) modeType.text =                        getString(R.string.hint_ncpap)                }            }        }        filterControlParameterViaMode(            this@DashBoardActivity,            modeCode,            (ventBasicParameterMap + ventAdvancedParameterMap + ventBackupParameterMap + ventSmartFio2ParameterMap + ventVTasParameterMap + ventEtCuffParameterMap).values.toList()        )?.apply {            this[ControlSettingType.BASIC]?.let {                basicControlParameterList = it as ArrayList<ControlParameterModel>            }            this[ControlSettingType.ADVANCED]?.let {                advancedControlParameterList = it as ArrayList<ControlParameterModel>            }            this[ControlSettingType.BACKUP]?.let {                backupControlParameterList = it as ArrayList<ControlParameterModel>            }            this[ControlSettingType.SmartFio2]?.let {                smartFio2ControlParameterList = it as ArrayList<ControlParameterModel>            }            this[ControlSettingType.VTas]?.let {                vTasControlParameterList = it as ArrayList<ControlParameterModel>            }            this[ControlSettingType.EtCuff]?.let {                etCuffControlParameterList = it as ArrayList<ControlParameterModel>            }        }        if (basicControlParameterList.size < PARAMETER_TILE_COUNT) {            for (i in 0 until (PARAMETER_TILE_COUNT - basicControlParameterList.size)) voidTile.apply {                basicControlParameterList.add(                    this                )            }        }        Log.i(            "CONTROLPARAMS_CHECK",            "AFTER NORMALISE = " + "CHECKING MAP" + ventEtCuffParameterMap.toString() + etCuffControlParameterList.toString()        )        setUpControlParameterAdapter()    }    // change here 12 feb    private fun renderStandbyControlParameterTilesViaPreference(lbl: String) {        standbyControlFragment?.let {            prefManager?.apply {                when (lbl) {                    LBL_PEEP -> {                        it.updateBasicParameterValue(LBL_PEEP, readPEEP().toInt().toString())                    }                    LBL_TRIG_FLOW -> {                        it.updateBasicParameterValue(LBL_TRIG_FLOW, readTrigFlow().toString())                    }                    LBL_PPLAT -> {                        it.updateBasicParameterValue(LBL_PPLAT, readPplat().toInt().toString())                    }                    LBL_VTI -> {                        it.updateBasicParameterValue(LBL_VTI, readVti().toInt().toString())                    }                    LBL_RR -> {                        it.updateBasicParameterValue(LBL_RR, readRR().toInt().toString())                    }                    LBL_TINSP -> {                        it.updateBasicParameterValue(LBL_TINSP, readTinsp().toString())                    }                    LBL_FLOW -> {                        it.updateBasicParameterValue(LBL_FLOW, readFlow().toInt().toString())                    }                    LBL_FIO2 -> {                        it.updateBasicParameterValue(LBL_FIO2, readFiO2().toInt().toString())                    }                    LBL_SLOPE -> {                        it.updateBasicParameterValue(LBL_SLOPE, readSlope().toInt().toString())                        it.updateAdvancedParameterValue(LBL_SLOPE, readSlope().toInt().toString())                    }                    LBL_SUPPORT_PRESSURE -> {                        it.updateBasicParameterValue(                            LBL_SUPPORT_PRESSURE, readSupportPressure().toInt().toString()                        )                    }                    LBL_FREQUENCY -> {                        it.updateAdvancedParameterValue(LBL_FREQUENCY, readFrequency().toString())                    }                    LBL_TLOW -> {                        it.updateBasicParameterValue(LBL_TLOW, readTlow().toString())                    }                    LBL_INSP_PAUSE -> {                        it.updateAdvancedParameterValue(                            LBL_INSP_PAUSE, readInspiratoryPause().toInt().toString()                        )                    }                    LBL_PIP -> {                        it.updateAdvancedParameterValue(LBL_PIP, readPip().toInt().toString())                        it.updateVTasParameterValue(LBL_PIP, readPip().toInt().toString())                    }                    LBL_ET_PRESSURE -> {                        it.updateEtCuffParameterValue(                            LBL_ET_PRESSURE, readEtPressure().toInt().toString()                        )                    }                    LBL_PEEP_VALVE -> {                        it.updateAdvancedParameterValue(                            LBL_PEEP_VALVE, readPeepValve().toInt().toString()                        )                    }                    /*    LBL_SPONT_VT ->{                            it.updateBasicParameterValue(                                LBL_SPONT_VT,                                readSpontVT().toInt().toString()                            )                        }*///                    LBL_TEXP -> {//                        it.updateAdvancedParameterValue(LBL_TEXP, readTexp().toInt().toString())//                    }                    LBL_APNEA_RR -> {                        it.updateBackupParameterValue(                            LBL_APNEA_RR, readRRApnea().toInt().toString()                        )                    }                    LBL_APNEA_VT -> {                        it.updateBackupParameterValue(                            LBL_APNEA_VT, readVtApnea().toInt().toString()                        )                    }                    LBL_TAPNEA -> {                        it.updateBackupParameterValue(LBL_TAPNEA, readTApnea().toString())                    }                    LBL_APNEA_TRIG_FLOW -> {                        it.updateBackupParameterValue(                            LBL_APNEA_TRIG_FLOW, readTrigFlowApnea().toInt().toString()                        )                    }                    LBL_TARGET_SPO2 -> {                        it.updateSmartFio2ParameterValue(                            LBL_TARGET_SPO2, readTargetSpo2().toInt().toString()                        )                    }                    LBL_TARGET_VOLUME -> {                        it.updateVTasParameterValue(                            LBL_TARGET_VOLUME, readTargetVolume().toInt().toString()                        )                    }                    LBL_FREQUENCY -> {                        it.updateAdvancedParameterValue(LBL_FREQUENCY, readFrequency().toString())                    }                    LBL_HR_LIMIT -> {                        it.updateSmartFio2ParameterValue(                            LBL_HR_LIMIT, readHrLimit().toInt().toString()                        )                    }                    LBL_FIO2_DEV -> {                        it.updateSmartFio2ParameterValue(                            LBL_FIO2_DEV, readFiO2Dev().toInt().toString()                        )                    }                }            }            prefManager?.apply {                if (modeCode == MODE_NIV_CPAP || modeCode == MODE_NIV_BPAP) {                    // note : we only need to handle first tym value because every time it receives value from preferences                    if (isKnobPressedForControlTile) updateParameter(                        LBL_TEXP, readTexp().toInt().toString()                    )                    else updateParameter(                        LBL_TEXP, 90.0f.toInt().toString()                    )                } else {                    if (isKnobPressedForControlTile) updateParameter(                        LBL_TEXP, readTexp().toInt().toString()                    )                    else updateParameter(                        LBL_TEXP, 25.0f.toInt().toString()                    )                }            }        }    }    // change here 12    private fun updateParameter(key: String, value: String) {        basicParams?.filter { it.ventKey == key }?.takeIf { it.isNotEmpty() }?.getOrNull(0)?.apply {            updateGraphictoolTip(this)            this.reading = supportPrecision(key, value)        }        advancedParams?.filter { it.ventKey == key }?.takeIf { it.isNotEmpty() }?.getOrNull(0)            ?.apply {                this.reading = supportPrecision(key, value)            }        backupParams?.filter { it.ventKey == key }?.takeIf { it.isNotEmpty() }?.getOrNull(0)            ?.apply {                this.reading = supportPrecision(key, value)            }        smartFioParams?.filter { it.ventKey == key }?.takeIf { it.isNotEmpty() }?.getOrNull(0)            ?.apply {                this.reading = supportPrecision(key, value)            }        vTasParams?.filter { it.ventKey == key }?.takeIf { it.isNotEmpty() }?.getOrNull(0)?.apply {            this.reading = supportPrecision(key, value)        }        etCuffParams?.filter { it.ventKey == key }?.takeIf { it.isNotEmpty() }?.getOrNull(0)            ?.apply {                this.reading = supportPrecision(key, value)            }        standbyControlFragment?.notifyParameterAdapter()    }    private fun renderControlParameterTilesViaPreference() {        Log.i("READ_PLIMIT", "${prefManager?.readFiO2()}")        prefManager?.apply {            updateVentParameterValue(LBL_PEEP, readPEEP().toInt().toString())            updateVentParameterValue(LBL_TRIG_FLOW, readTrigFlow().toString())            updateVentParameterValue(LBL_PPLAT, readPplat().toInt().toString())            updateVentParameterValue(LBL_VTI, readVti().toInt().toString())            updateVentParameterValue(LBL_RR, readRR().toInt().toString())            updateVentParameterValue(LBL_TINSP, readTinsp().toString())            updateVentParameterValue(LBL_FIO2, readFiO2().toInt().toString())            updateVentParameterValue(LBL_SUPPORT_PRESSURE, readSupportPressure().toInt().toString())            updateVentParameterValue(LBL_TLOW, readTlow().toString())            updateVentParameterValue(LBL_FLOW, readFlow().toInt().toString())            //Frequency            updateVentAdvancedParameterValue(LBL_FREQUENCY, readFrequency().toString())            // updateVentParameterValue(LBL_SPONT_VT,readSpontVT().toInt().toString())            updateVentParameterValue(LBL_SLOPE, readSlope().toInt().toString())            //Advanced Parameter Settings.            updateVentAdvancedParameterValue(                LBL_INSP_PAUSE, readInspiratoryPause().toInt().toString()            )            updateVentAdvancedParameterValue(LBL_PEEP_VALVE, readPeepValve().toInt().toString())            updateVentAdvancedParameterValue(LBL_TEXP, readTexp().toInt().toString())            updateVentAdvancedParameterValue(LBL_PIP, readPip().toInt().toString())            updateVentAdvancedParameterValue(LBL_SLOPE, readSlope().toInt().toString())            updateVentBackupParameterValue(LBL_APNEA_RR, readRRApnea().toInt().toString())            updateVentBackupParameterValue(LBL_APNEA_VT, readVtApnea().toInt().toString())            updateVentBackupParameterValue(LBL_TAPNEA, readTApnea().toString())            updateVentBackupParameterValue(                LBL_APNEA_TRIG_FLOW, readTrigFlowApnea().toInt().toString()            )            // Smart Fio2 Parameters settings            updateVentSmartFio2ParameterValue(LBL_TARGET_SPO2, readTargetSpo2().toInt().toString())            updateVentSmartFio2ParameterValue(LBL_HR_LIMIT, readHrLimit().toInt().toString())            updateVentSmartFio2ParameterValue(LBL_FIO2_DEV, readFiO2Dev().toInt().toString())            // vTas parameters settings            updateVentVTasParameterValue(LBL_TARGET_VOLUME, readTargetVolume().toInt().toString())            updateVentAdvancedParameterValue(LBL_FREQUENCY, readFrequency().toString())            updateVentAdvancedParameterValue(LBL_PIP, readPip().toInt().toString())            //EtCuff parameter settings//            updateVentEtCuffParameterValue(LBL_ET_PRESSURE, readEtPressure().toInt().toString())        }    }    private var dataActionList = ArrayList<ActionDataModel>()    //Action Adapter Code    private fun setupActionParameterAdapter() {        val recyclerViewActionButtons: RecyclerView = findViewById(R.id.recyclerViewActionButtons)        dataActionList.clear()        dataActionList.add(ActionDataModel.ActionModel(R.drawable.ic_updated_bell))        dataActionList.add(ActionDataModel.ActionModel(R.drawable.ic_nebuliser_updated))//        data.add(ActionModel(R.drawable.ic_100percent_frame))//        data.add(ActionModel(R.drawable.ic_i_hold_updated))//        data.add(ActionModel(R.drawable.ic_ehold_updated))        dataActionList.add(ActionDataModel.ActionModelText("↑ 100% O₂"))        dataActionList.add(ActionDataModel.ActionModelText("I - HOLD"))        dataActionList.add(ActionDataModel.ActionModelText("E - HOLD"))        dataActionList.add(ActionDataModel.ActionModel(R.drawable.ic_manual_breathe_updated))        dataActionList.add(ActionDataModel.ActionModel(R.drawable.home_icon))        dataActionList.add(ActionDataModel.ActionModel(R.drawable.ic_battery_full_updated))        dataActionList.add(ActionDataModel.ActionModel(R.drawable.ic_plug_linear))        dataActionList.add(ActionDataModel.ActionModel(R.drawable.ic_locked_icon))// Add more items if needed// Create adapter and pass data list        primaryActionAdapter = PrimaryActionAdapter(this, dataActionList, this)        recyclerViewActionButtons.layoutManager =            LinearLayoutManager(this, LinearLayoutManager.HORIZONTAL, false)// Set adapter to RecyclerView        recyclerViewActionButtons.adapter = primaryActionAdapter    }    // RecyclerView Set value    var primaryControlParameters = ArrayList<ControlParameterModel>()    private fun setUpControlParameterAdapter() {        primaryControlParameters = try {            ArrayList(basicControlParameterList.subList(0, PARAMETER_TILE_COUNT))        } catch (e: Exception) {            Log.i(                "PRIMARYTILE_CHECK",                "Invalid size (size required = $PARAMETER_TILE_COUNT | current size = ${basicControlParameterList.size}"            )            basicControlParameterList        }        primaryControlParameterAdapter = PrimaryControlParameterAdapter(            this, primaryControlParameters, onBasicParameterClickListener        )        recyclerViewSetValue?.apply {            layoutManager =                LinearLayoutManager(this@DashBoardActivity, LinearLayoutManager.HORIZONTAL, false)            adapter = primaryControlParameterAdapter            isNestedScrollingEnabled = false        }        Log.i("CONTROLPARAMS_CHECK", "Recycler child = ${recyclerViewSetValue.childCount}")        Log.i(            "CONTROLPARAMS_CHECK", "Adapeter count = ${primaryControlParameterAdapter?.itemCount}"        )    }    private fun setUpPrimaryObservedParameterAdapter() {        primaryObservedParameterAdapter = PrimaryObservedParameterAdapter(this, selectedTiles, this)        recyclerViewObserveValue?.apply {            layoutManager = LinearLayoutManager(this@DashBoardActivity)            adapter = primaryObservedParameterAdapter            isNestedScrollingEnabled = false        }    }    // RecyclerView Secondary Observe value    private fun setSecondaryObservedParameterAdapter() {        secondaryObservedParameterAdapter =            SecondaryObservedParameterAdapter(this, observedValueSpHOList)        observeValueRecyclerView?.apply {            layoutManager =                LinearLayoutManager(this@DashBoardActivity, LinearLayoutManager.HORIZONTAL, false)            adapter = secondaryObservedParameterAdapter            isNestedScrollingEnabled = false        }    }    /*    * This method checks the bound services    * and unbind them    */    /*    * This methods start pinging to ventilator    */    private fun startPinging() {        if (communicationService != null) {            if (pingingTask == null) pingingTask = PingingTask(communicationService)            if (pingingTask?.isRunning == false) pingingTask?.start()        }    }    /*    * This methods stop pinging to ventilator    */    private fun stopPinging() {        pingingTask?.apply {            if (isRunning) stop()        }    }    /*     * This will split the map data into co-ordinates     * and render them on REALTIME graph     */    private fun setDataOnScreen(dataMap: Map<String, Map<String, String>>?) {        dataMap?.takeIf { it.isNotEmpty() }?.apply {            val lbl = this.keys.iterator().next()            this[lbl]?.apply {                updateData(lbl, this)            }        }    }    // Define Variable    private var cacheTrigger: Float? = null    private var isCmvActive = false    private var isNivActive = false    private var cachedVolume: Float? = null    private var cachedPip: Float? = null    //changes to integrate vti in the database    private var cachedVti: Float? = null    private var cachedRR: Float? = null    private var cachedMvi: Float? = null    private var cachedPmean: Float? = null    private var cachedMve: Float? = null    private var cachedFiO2: Float? = null    private var cachedVte: Float? = null    private var cachedPeep: Float? = null    private var cachedLeak: Float? = null    private var cachedIERatio: Float? = null    private var tempVolume: Float? = null    private var cachedTinsp: Float? = null    private var cachedTexp: Float? = null    private var cachedMeanAirwayPressure: Float? = null    private var cachedrsbi: Float? = null    private var cachedSpontRR: Float? = null    private var cachedSpo2: Float? = null    private var cachedPR: Float? = null    //    private var cachedSpontMvi : Float? = null    private var isEndOfExhalationOccured: Boolean = false    private var breathCountAfterModeChange = 0;    private var volumeCountAtFirst = 0;    private var calculatedPip: Float? = null    private fun isCycleCheckActivated() = breathCountAfterModeChange <= 4    private fun isVolumeActivated() = volumeCountAtFirst <= 2    //The smart Fio2 average section code section    var spo2temp: Double? = null    var Hrtemp: Double? = null    var isPatientTrigger: Boolean = false    var floorTinsp: Float = 0f    var floorTexp: Float = 0f    private fun updateData(label: String, map: Map<String, String>) {        removeVentilatorFailureAlarm()        var pressure: Float? = getMapValueFromLabel(map, RaspiParser.DATA_PRESSURE)        val flow: Float? = getMapValueFromLabel(map, RaspiParser.DATA_FLOW)        val hfncFlow: Float? = getMapValueFromLabel(map, RaspiParser.DATA_HFNC_FLOW)        val hfncFio2: Float? = getMapValueFromLabel(map, RaspiParser.DATA_HFNC_FIO2)        var volume: Float? = getMapValueFromLabel(map, RaspiParser.DATA_VOLUME)//        if (mDashBoardViewModel.modeChange.value == true) volume = 0.0f        var pip: Float? = getMapValueFromLabel(map, RaspiParser.DATA_PIP)        var vti: Float? = getMapValueFromLabel(map, RaspiParser.DATA_VTI)        var vte: Float? = getMapValueFromLabel(map, RaspiParser.DATA_VTE)        val mve: Float? = getMapValueFromLabel(map, RaspiParser.DATA_MVE)        val mvi: Float? = getMapValueFromLabel(map, RaspiParser.DATA_MVI)        val pMean: Float? = getMapValueFromLabel(map, RaspiParser.DATA_PMEAN)?.also {            cachedPmean = it        }        val vPeakI: Float? = getMapValueFromLabel(map, RaspiParser.DATA_VPEAK_I)        val vPeakE: Float? = getMapValueFromLabel(map, RaspiParser.DATA_VPEAK_E)        var peep: Float? = getMapValueFromLabel(map, RaspiParser.DATA_PEEP)        var rr: Float? = getMapValueFromLabel(map, RaspiParser.DATA_RR)        // rr plus minus one padding        rr?.let {            prefManager?.apply {                if (it.toInt() in (readRR().toInt() - 1)..(readRR().toInt() + 1)) rr = readRR()            }        }        val tiTot: Float? = getMapValueFromLabel(map, RaspiParser.DATA_TITOT)        val fio2: Float? = getMapValueFromLabel(map, RaspiParser.DATA_FIO2)        Log.i("check_fio2_test", fio2.toString())        val leak: Float? = getMapValueFromLabel(map, RaspiParser.DATA_LEAK)        val volLeak: Float? = getMapValueFromLabel(map, RaspiParser.DATA_VOLUME_LEAK)        var trigFlow: Float? = getMapValueFromLabel(map, RaspiParser.DATA_TRIGFLOW)        val observedPplat: Float? = getMapValueFromLabel(map, RaspiParser.DATA_PLATEAU_PRESSURE)        val rsbi: Float? = getMapValueFromLabel(map, RaspiParser.DATA_RSBI)        val spontVT: Float? = getMapValueFromLabel(map, RaspiParser.DATA_RR)        val meanAirwayPressure: Float? = getMapValueFromLabel(            map, RaspiParser.DATA_MEAN_AIRWAY_PRESSURE        )?.also { cachedMeanAirwayPressure = it }        val tInsp: Float? =            getMapValueFromLabel(map, RaspiParser.DATA_INSPIRE_TIME)?.also { cachedTinsp = it }        Log.i("fio2_hfnc_check", "$hfncFio2, $fio2")        Log.i("fio2_hfnc_check_flow", "$hfncFio2, $flow")        val tExpire: Float? = getMapValueFromLabel(map, RaspiParser.DATA_EXPIRE_TIME)?.also {            cachedTexp = it        }        val tRise: Float? = getMapValueFromLabel(map, RaspiParser.DATA_RISE_TIME)        var trigger: String? = null        var dynamicCompliance: Float? = null        // SPO2 Parameters        val spo2: Float? = getMapValueFromLabel(map, SpO2ParserExtension.DATA_SPO2)        val heartRate: Float? = getMapValueFromLabel(map, SpO2ParserExtension.DATA_HEARTRATE)        val plethmograph: Float? = getMapValueFromLabel(map, SpO2ParserExtension.DATA_PLETHMOGRAPH)        //ToDo:-check this line out        val triggerValue = getMapValueFromLabel(map, RaspiParser.DATA_TRIGGER)?.also {            cacheTrigger = it        }        val ieRatio: Float? = tExpire?.let {            tInsp?.div(it)        }        if (triggerValue != null) {            val isPatientTriggered = !isCmvActive && triggerValue.toInt() == TRIGGER_PATIENT            if (isPatientTriggered) {                trigger = LABEL_PATIENT                isPatientTrigger = true                machineTriggerCount = 0            } else {                trigger = LABEL_MACHINE            }        }        Log.i("LABEL CHECK", "Entry mode is $label")        when (label) {            SpO2ParserExtension.TYPE_SPO2 -> {                countBatteryData = 0                CoroutineScope(Dispatchers.Main).launch {                    dataStoreManager?.saveDashRebootStatusFlag(true)                }                spo2?.apply {                    spo2temp = this.toDouble()                    cachedSpo2 = this                    Log.i(                        "SPO2_value",                        spo2.toString() + " --> " + if (this == 0f) "-" else this.toInt().toString()                    )                    // remove alarm                    if (this == 0.0f && alarmsMap.containsKey(LBL_SPO2)) removeAlarm(LBL_SPO2)                    updateSecondaryModelActualValue(                        LBL_SPO2, if (this == 0f) "-" else this.toInt().toString()                    )                    tempSpo2Timer = object : CountDownTimer(120000, 1000) {                        override fun onTick(millisUntilFinished: Long) {                            Log.i("vlaue_Sdwa", "onTIck SPo2")                            if (spo2TimerClosed == false) {                                isTempSPo2TimerRunning = true                                if (spo2temp != 0.0) spo2temp?.let { tempReadSpo2List.add(it.toFloat()) }                            } else {                                tempReadSpo2List.clear()                            }                        }                        override fun onFinish() {                            Log.i("vlaue_Sdwa", "onFInish SPo2")                            if (spo2TimerClosed == false) {                                isTempSPo2TimerRunning = false                                if (prefManager?.readSmartFiO2Status() == true && mDashBoardViewModel.spo2hrDataStreaming.value) {                                    if (tempReadSpo2List.isNotEmpty() && tempReadSpo2List.size > 5) {                                        mDashBoardViewModel.avgTempSpo2List.value = tempReadSpo2List                                    }                                    tempReadSpo2List.clear()                                    tempSpo2Timer?.start()                                }                            }                        }                    }                    if (spo2temp != 0.0) mDashBoardViewModel.spo2hrDataStreaming.value = true                    else mDashBoardViewModel.spo2hrDataStreaming.value = false                }            }            SpO2ParserExtension.TYPE_HEARTRATE -> {                countBatteryData = 0                CoroutineScope(Dispatchers.Main).launch {                    dataStoreManager?.saveDashRebootStatusFlag(true)                }                heartRate?.apply {                    cachedPR = this                    Hrtemp = this.toDouble()                    //Log.d("TheMeanSpo2HrValueisatcondition","${Hrtemp!=0.0} with the value ${this.toDouble()}")                    updateSecondaryModelActualValue(                        LBL_HR, if (this == 0f) "-" else this.toInt().toString()                    )                    tempHrTimer = object : CountDownTimer(120000, 1000) {                        override fun onTick(millisUntilFinished: Long) {                            Log.i("vlaue_Sdwa", "onTIck HR")                            if (hrTimerClosed == false) {                                isTempHrTimerRunning = true                                if (Hrtemp != 0.0) Hrtemp?.let { tempReadHrList.add(it.toFloat()) }                            } else {                                tempReadSpo2List.clear()                            }                        }                        override fun onFinish() {                            Log.i("vlaue_Sdwa", "Finish HR")                            if (hrTimerClosed == false) {                                isTempHrTimerRunning = false                                if (prefManager?.readSmartFiO2Status() == true && mDashBoardViewModel.spo2hrDataStreaming.value) {                                    if (tempReadHrList.isNotEmpty() && tempReadHrList.size > 5) mDashBoardViewModel.avgTempHrList.value =                                        tempReadHrList                                    tempReadHrList.clear()                                    tempHrTimer?.start()                                }                            } else {                                tempReadHrList.clear()                            }                        }                    }                    if (Hrtemp != 0.0) mDashBoardViewModel.hrSpo2DataStreaming.value = true                    else mDashBoardViewModel.hrSpo2DataStreaming.value = false                }            }            // Prefix : A@            RaspiParser.TYPE_INHALATION -> {                VentilatorApp.currentBreathCycle = "A"                Log.i("type_inhalation", "A")                mDashBoardViewModel.graphPeekValue.postValue("A")                cachedVolume = volume                updatePrimaryModelActualValue(LBL_RESPIRATORY_PHASE, "INSPIRE")            }            // Prefix : B@            RaspiParser.TYPE_END_OF_INHALATION -> {                VentilatorApp.currentBreathCycle = "B"                Log.i("type_inhalation", "B")                mDashBoardViewModel.graphPeekValue.postValue("B")                cachedLeak = leak                cachedPip = pip                cachedVti = vti                cachedMvi = mvi                //Need to test this condition                if (prefManager?.readModeType() != Configs.ModeType.TYPE_Volume && prefManager?.readApneaSettingsStatus() != true) {                    if (!VentilatorApp.isPatientTrigger) {                        Log.d("VentilatorApp", "Patient is NOT triggering")                        Log.d("VentilatorApp", "Pip Value before padding -> $pip")                        if (pip != null) {                            Log.d("VentilatorApp", "Initial pip value: $pip")                            val cPeep = prefManager?.readPEEP()                            val cPplat = prefManager?.readPplat()                            if (cPeep != null && cPplat != null) {                                val calculatedPip = cPeep + cPplat                                Log.d("VentilatorApp", "Calculated PIP: $calculatedPip")                                if (pip in (calculatedPip - 2)..(calculatedPip + 2)) {                                    Log.d(                                        "VentilatorApp",                                        "PIP is within range, updating pip to $calculatedPip"                                    )                                    pip = calculatedPip                                } else {                                    Log.w(                                        "VentilatorApp",                                        "PIP is OUT of range. Current: $pip, Expected Range: ${calculatedPip - 2} to ${calculatedPip + 2}"                                    )                                }                            } else {                                Log.e(                                    "VentilatorApp",                                    "PEEP or Pplat is NULL! Cannot calculate PIP."                                )                            }//              calculatedPip = cPeep + cPplat//                if (pip in calculatedP - 2..calculatedPip!! + 2) {//                  pip = calculatedPip//                }                        } else {                            Log.e("VentilatorApp", "PIP is NULL! Cannot proceed.")                        }                    } else {                        Log.d("VentilatorApp", "Patient is triggering, skipping calculation")                    }                } else {                    Log.d(                        "VentilatorApp",                        "Either ModeType is TYPE_Volume or ApneaSettingsStatus is enabled, skipping logic"                    )                }                if (peep != null) {                    Log.d("VentilatorApp", "PEEP Value before padding -> $peep")                    prefManager?.apply {                        if (peep!! in readPEEP() - 2..readPEEP() + 2) {                            peep = readPEEP()                        }                    }                } else {                    Log.e("VentilatorApp", "PEEP is NULL! Cannot proceed.")                }                Log.i("CHECK_VTI_VAL", vti.toString())                if (prefManager?.readLastVentMode() == 60 || prefManager?.readVentilationMode() == 60) {                    hfncFlow?.let {                        if (it <= 0) {                            updatePrimaryModelActualValue(LBL_FLOW, "-")                        } else {                            updatePrimaryModelActualValue(LBL_FLOW, it)                        }                    }                }                Log.i("CHECK_BREATHE", "vti - $vti,cahedVti-$cachedVti")            }            // Prefix : C@            TYPE_EXHALATION -> {                VentilatorApp.currentBreathCycle = "C"                Log.i("type_inhalation", "C ")                mDashBoardViewModel.graphPeekValue.postValue("C")                updatePrimaryModelActualValue(LBL_RESPIRATORY_PHASE, "EXPIRE")                volume = volume?.let {                    if (it < 0.0f) {                        tempVolume                    } else {                        cachedVolume?.let { it1 ->                            it1 - it