=//                                    vti//                            }//                        }//                    }//                }                Log.i("CHECK_VT_TESTING", "raw $vti - $vte")                vti?.let {                    vte?.let {                        prefManager?.apply {                            if (readCurrentUid() == PatientProfile.TYPE_NEONAT && readModeType() != ModeType.TYPE_Volume) {                                Log.i("CHECK_VT_TESTING", " neonate + volume")                                Log.i(                                    "CHECK_VOLUME",                                    "1 -> VTI is" + vti.toString() + "VTE is " + vte.toString()                                )//                                if (vTe < 20.0f) {                                if (vti!! < 20.0f) {                                    for (i in 1 until 3) {                                        if (vte!!.toInt() + i == vti!!.toInt() || vte!!.toInt() - i == vti!!.toInt()) {                                            vte = vti                                            Log.i(                                                "CHECK_VOLUME",                                                "2. -> VTI is" + vti.toString() + "VTE is " + vte.toString()                                            )                                        }                                    }                                } else if (vti!!.toInt() in 20 until 50) {                                    for (i in 1 until 5) {                                        if (vte!!.toInt() + i == vti!!.toInt() || vte!!.toInt() - i == vti!!.toInt()) {                                            vte = vti                                            Log.i(                                                "CHECK_VOLUME",                                                "2. -> VTI is" + vti.toString() + "VTE is " + vte.toString()                                       