(j in 1 until 3) {                                                    if (vte!!.toInt() + j == obsVti!!.toInt() || vte!!.toInt() - j == obsVti!!.toInt()) {                                                        vte = vti                                                        Log.i(                                                            "CHECK_VOLUME",                                                            "2. -> VTI is" + vti.toString() + "VTE is " + vte.toString()                                                        )                                                    }                                                }                                                Log.i("Check_Volume", vti.toString() + " after")                                            } else {                                                for (i in 1 until 3) {                                                    if (vte!!.toInt() + i == vti!!.toInt() || vte!!.toInt() - i == vti!!.toInt()) {                                                        vte = vti                                                        Log.i(                                                            "CHECK_VOLUME",                                                            "2. -> VTI is" + vti.toString() + "VTE is " + vte.toString()                                                        )                                                    }                                                }                                            }                                        }                                    }                                } else if (vti!!.toInt() in 20 until 50) {                                    for (i in 1 until 5) {                                        prefManager?.apply {                                            if (vti!!.toInt() in readVti().toInt() - i..readVti().toInt() + i) {                                                vti = readVti()                                                for (j in 1 until 5) {                                                    if (vte!!.toInt() + j == vti!!.toInt() || vte!!.toInt() - j == vti!!.toInt()) {                                                        vte = vti                                                        Log.i(                                                            "CHECK_VOLUME",                                                            "2. -> VTI is" + vti.toString() + "VTE is " + vte.toString()                                                        )                                                    }                                                }                                                Log.i("Check_Volume", vti.toString() + " after")                                            }                                        }                                    }                                } else if (vti!!.toInt() > 50) {                                    for (i in 1 until 7) {                                        prefManager?.apply {                                            if (vti!!.toInt() in readVti().toInt() - i..readVti().toInt() + i) {                                                vti = readVti()                                                for (j in 1 until 7) {                                                    if (vte!!.toInt() + j == vti!!.toInt() || vte!!.toInt() - j == vti!!.toInt()) {                                                        vte = vti                                                        Log.i(                                                            "CHECK_VOLUME",                                                            "2. -> VTI is" + vti.toString() + "VTE is " + vte.toString()                                                        )                                                    }                                                }                                                Log.i("Check_Volume", vti.toString() + " after")                                            }                                        }                                    }                                }                            } else if (readModeType() == ModeType.TYPE_Volume && readCurrentUid() != PatientProfile.TYPE_NEONAT) {                                Log.i("CHECK_VT_TESTING", " non neonate + volume")                                if (VentilatorApp.apneaActive == true) {                                    if (vti!!.toInt() >= (readVtApnea().toInt() * 0.92) && vti!!.toInt() < (readVtApnea().toInt() * 1.08)) {                                        if (vti!!.toInt() < readVtApnea().toInt()) aug_Vti =                                            readVtApnea() - (((readVtApnea() / vti!!) * 100) - 100)                                        else if (vti!!.toInt() > readVtApnea().toInt()) aug_Vti =                                            readVtApnea() + (((vti!! / readVtApnea()) * 100) - 100)                                    } else {                                        aug_Vti = vti                                    }                                } else {                                    if (vti!!.toInt() >= (readVti().toInt() * 0.92) && vti!!.toInt() < (readVti().toInt() * 1.08)) {                                        if (vti!!.toInt() < readVti().toInt()) aug_Vti =                                            readVti() - (((readVti() / vti!!) * 100) - 100)                                        else if (vti!!.toInt() > readVti().toInt()) aug_Vti =                                            readVti() + (((vti!! / readVti()) * 100) - 100)                                    } else {                                        aug_Vti = vti                                    }                                }                            }                            if (readModeType() == ModeType.TYPE_Volume && readCurrentUid() != PatientProfile.TYPE_NEONAT) {                                Log.i("CHECK_VT_TESTING", " non neonate + volume")                                if (((vte!! < (vti!! * 1.09)) && (vte!! > (vti!! * 0.91))) || (vti != aug_Vti)) vte =                                    aug_Vti                            } else if (readCurrentUid() != PatientProfile.TYPE_NEONAT) {                                Log.i("CHECK_VT_TESTING", " non neonate + non volume")                                if ((vte!! < (vti!! * 1.09)) && (vte!! > (vti!! * 0.91))) {                                    vte = vti                                }                            }                        }                    }                }                if ((peep != null && flow != null) && vPeakE != null) {                    prefManager?.apply {                        if ((peep!! < (readPEEP().toInt() + 1)) && (flow!! < (vPeakE * 0.2))) {                            Log.i("CHECK_AUTOPEEP", "AUTO PEEP ALARM GENERATED")                            addAutoPeepAlarm()                        } else {                            removeAutoPeepAlarm()                        }                    }                }                if (prefManager?.readPeepAlarmStatus() == true) {                    peep?.let { it1 ->                        prefManager?.let { it2 ->                            if (it1 < it2.readPEEP() * 0.25) {                                addWrongPeepAlarm()                            } else {                                removeWrongPeepAlarm()                            }                        } ?: run {                            removeWrongPeepAlarm()                        }                    } ?: run {                        removeWrongPeepAlarm()                    }                }                Log.i("CHECK_BREATHE", "vte-$vte,vti - $vti,cahedVti-$cachedVti")                VentilatorApp.currentBreathCycle = "D"                Log.i("type_inhalation", "D")                mDashBoardViewModel.graphPeekValue.postValue("D")                breathCountAfterModeChange++                if (peep != null) {                    peep = if (peep!! < 0f) 0f else peep                }                // rsbi set 0 if less than 1                cachedrsbi?.apply {                    if (this > 0) updatePrimaryModelActualValue(LBL_RSBI, this * 1000, 0)                    else updatePrimaryModelActualValue(LBL_RSBI, 0.0f, 0)                }                cachedSpontRR = rr?.minus(prefManager?.readRR()!!)                cachedSpontRR?.apply {                    if (this <= 0) updatePrimaryModelActualValue(LBL_SPONT_RR, "0")                    else updatePrimaryModelActualValue(LBL_SPONT_RR, this)                }                if (isPatientAvailable) {                    vti?.apply {                        if (this > 2000f || this < 0) {                            updatePrimaryModelActualValue(LBL_VTI, "-")                        } else {                            if (prefManager?.readModeType() == ModeType.TYPE_Volume && prefManager?.readCurrentUid() != Configs.PatientProfile.TYPE_NEONAT) {                                Log.i("CHECK_VT_TESTING", " non neonate + volume + show vti")                                updatePrimaryModelActualValue(LBL_VTI, aug_Vti)                                vti = aug_Vti                            } else {                                Log.i("CHECK_VT_TESTING", "normal + show vti")                                updatePrimaryModelActualValue(LBL_VTI, this)                            }                        }                    }                    vte?.apply {                        if (this > 2000f || this < 0) {                            updatePrimaryModelActualValue(LBL_VTE, "-")                        } else {                            Log.i("CHECK_VT_TESTING", "normal + show vte")                            updatePrimaryModelActualValue(LBL_VTE, this.toInt().toString())                        }                    }                } else {                    updatePrimaryModelActualValue(LBL_VTI, "-")                    updatePrimaryModelActualValue(LBL_VTE, "-")                }                // add alarm for fio2 leakage                prefManager?.apply {                    if (fio2 != null && leak != null) {                        if (fio2 < readFiO2() - 8 && leak > 50) addFio2LeakAlarm()                        else removeFio2LeakAlarm()                    }                }                cachedRR = rr                cachedMve = mve                cachedFiO2 = fio2                Log.i("CHECKFIO2STRING", cachedFiO2.toString())                cachedPeep = peep                cachedrsbi = rsbi                cachedLeak = leak                val model = TrendDBModel()                if (breathCacheList.size < 1) {                    // FIO2 coming in D string only                    cachedSpo2?.apply {                        model.spo2 = this                    }                    cachedPR?.apply {                        model.pr = this                    }                    cachedPip?.apply {                        model.pip = this                    }                    //changes to integrate vti in the database                    cachedVti?.apply {                        model.vti = this                    }                    cachedRR?.apply {                        model.respiratoryRate = this                    }                    cachedFiO2?.apply {                        model.fio2 = this                    }                    cachedMve?.apply {                        model.mve = this                    }                    cachedVte?.apply {                        model.vte = this                    }                    cachedPeep?.apply {                        model.peep = this                    }                    cachedLeak?.apply {                        model.averageLeak = this                    }                    cachedIERatio?.apply {                        model.iE = this                    }                    //newly added values                    cachedMvi?.apply {                        model.mvi = this                    }                    cachedTinsp?.apply {                        model.tinsp = this                    }                    cachedTexp?.apply {                        model.texp = this                    }                    cachedMeanAirwayPressure?.apply {                        model.meanAirway = this                    }                    breathCacheList.add(model)                } else {                    cachedSpo2?.apply {                        breathCacheList[0].spo2 = (breathCacheList[0].spo2 + this) / 2                    }                    cachedPR?.apply {                        breathCacheList[0].pr = (breathCacheList[0].pr + this) / 2                    }                    cachedPip?.apply {                        breathCacheList[0].pip = (breathCacheList[0].pip + this) / 2                    }                    cachedVti?.apply {                        breathCacheList[0].vti = (breathCacheList[0].vti + this) / 2                    }                    cachedRR?.apply {                        breathCacheList[0].respiratoryRate =                            (breathCacheList[0].respiratoryRate + this) / 2                    }                    cachedFiO2?.apply {                        breathCacheList[0].fio2 = (breathCacheList[0].fio2 + this) / 2                    }                    cachedMve?.apply {                        breathCacheList[0].mve = (breathCacheList[0].mve + this) / 2                    }                    cachedVte?.apply {                        breathCacheList[0].vte = (breathCacheList[0].vte + this) / 2                    }                    cachedPeep?.apply {                        breathCacheList[0].peep = (breathCacheList[0].peep + this) / 2                    }                    cachedLeak?.apply {                        breathCacheList[0].averageLeak = (breathCacheList[0].averageLeak + this) / 2                    }                    cachedIERatio?.apply {                        breathCacheList[0].iE = (breathCacheList[0].iE + this) / 2                    }                    //newly added values                    cachedMvi?.apply {                        breathCacheList[0].mvi = (breathCacheList[0].mvi + this) / 2                    }                    cachedTinsp?.apply {                        breathCacheList[0].tinsp = (breathCacheList[0].tinsp + this) / 2                    }                    cachedTexp?.apply {                        breathCacheList[0].texp = (breathCacheList[0].texp + this) / 2                    }                    cachedMeanAirwayPressure?.apply {                        breathCacheList[0].meanAirway = (breathCacheList[0].meanAirway + this) / 2                    }                }//                600000                if (abs(lastUpdatedTime - currentTimeMillis()) > 600000) {//                    // saved data in room and server                    CoroutineScope(Dispatchers.IO).launch {                        trendsLogic()                    }                    lastUpdatedTime = currentTimeMillis()                }                // data send in live fragment here                sendDataToLiveFragment()            }        }        // OSC - Order sensitive code        // Rendering of loop graphs        // After D the first A will re render the charts        val isRedrawRequired = isEndOfExhalationOccured && RaspiParser.TYPE_INHALATION.equals(label)        if (pressure != null && volume != null) {            if (freezeGraph == true) {            } else {                divideTrioGraphFragment.takeIf { it.isVisible }?.apply {                    if (isRedrawRequired && cachedPeep != null) {                        addGraphPressureVolumeData(cachedPeep, 0.0f, isRedrawRequired)                        addGraphPressureVolumeData(pressure, volume, false);                    } else addGraphPressureVolumeData(pressure, volume, isRedrawRequired)                }                loopsGraphFragment.takeIf { it.isVisible }?.apply {                    if (isRedrawRequired && cachedPeep != null) {                        addGraphPressureVolumeData(cachedPeep, 0.0f, isRedrawRequired)                        addGraphPressureVolumeData(pressure, volume, false);                    } else addGraphPressureVolumeData(pressure, volume, isRedrawRequired)                }            }        }        if (flow != null && volume != null) {            if (freezeGraph == true) {            } else {                divideQuadGraphFragment?.takeIf {                    it.isVisible                }?.apply {                    if (isRedrawRequired && cachedVolume != null) {                        addGraphFlowVolumeData(cachedVolume, 0.0f, isRedrawRequired)                        addGraphFlowVolumeData(volume, flow, false)                    } else {                        addGraphFlowVolumeData(volume, flow, isRedrawRequired)                    }                }                loopsGraphFragment?.takeIf {                    it.isVisible                }?.apply {                    if (isRedrawRequired && cachedVolume != null) {                        addGraphFlowVolumeData(cachedVolume, 0.0f, isRedrawRequired)                        addGraphFlowVolumeData(volume, flow, false)                    } else {                        addGraphFlowVolumeData(volume, flow, isRedrawRequired)                    }                }            }        }        if (flow != null && pressure != null) {            if (freezeGraph == true) {            } else {                divideTrioGraphFragment.takeIf { it.isVisible }?.apply {                    if (isRedrawRequired && cachedPeep != null) {                        addGraphFlowPressureData(cachedPeep, 0.0f, isRedrawRequired)                        addGraphFlowPressureData(pressure, flow, false)                    } else {                        addGraphFlowPressureData(pressure, flow, isRedrawRequired)                    }                }                loopsGraphFragment?.takeIf { it.isVisible }?.apply {//                Log.i("value_flow_pressure","$pressure, $flow")                    if (isRedrawRequired && cachedPeep != null) {                        addGraphFlowPressureData(cachedPeep, 0.0f, isRedrawRequired)                        addGraphFlowPressureData(pressure, flow, false)                    } else {                        addGraphFlowPressureData(pressure, flow, isRedrawRequired)                    }                }            }            /* pentGraphFragment.takeIf { it.isVisible }?.apply {                 addGraphFlowPressureData(pressure,flow,isRedrawRequired)             }*/        }        // OSC - Order sensitive code        if (isRedrawRequired) {            // disable the flag as first TYPE_INHALATION after a TYPE_END_OF_EXHALATION is encountered            isEndOfExhalationOccured = false        }        // updating graphs        pressure?.apply {            Log.i("DIVIDE_PRESSURE", pressure.toString())            pressure = if (this < 0) 0f else this            if (freezeGraph == true) {            } else {                addPressureGraphEntry(pressure!!, pCount++, trigger)            }        }        flow?.apply {            if (freezeGraph == true) {            } else {                Log.i("DIVIDE_FLOW", flow.toString())                addFlowGraphEntry(this, fCount++)            }        }        volume?.apply {            Log.i("DIVIDE_VOLUME", volume.toString())            if (this < 0.0f) volume = 0.0f            if (freezeGraph == true) {            } else {                addVolumeGraphEntry(volume!!, vCount++)            }        }        try {            if (volume != null && flow != null && pressure != null) {                sendGraphDataToLiveFragment(                    vCount % (GRAPH_THRESHOLD + 1), volume!!, flow!!, pressure!!                )            }        } catch (e: Exception) {            e.printStackTrace()        }        // ============== updating titles ==============        pip?.apply { updatePrimaryModelActualValue(LBL_PIP, this) }        if (isPatientAvailable) {            mve?.apply { updatePrimaryModelActualValue(LBL_MVE, String.format("%.1f", this)) }            mvi?.apply { updatePrimaryModelActualValue(LBL_MVI, String.format("%.1f", this)) }        } else {            updatePrimaryModelActualValue(LBL_MVI, "-")            updatePrimaryModelActualValue(LBL_MVE, "-")        }//PMean issue Fixed//        pMean?.apply {//            updatePrimaryModelActualValue(LBL_PMEAN, cachedPmean)//        }        vPeakI?.apply {            VentilatorApp.flowPeakValuePositive = this            updatePrimaryModelActualValue(LBL_VPEAK_I, this)        }        vPeakE?.apply {            VentilatorApp.flowPeakValueNegative = this            updatePrimaryModelActualValue(LBL_VPEAK_E, this)        }        peep?.apply {            val setPeep = prefManager?.readPEEP()            if (setPeep != null) {                val deviation = abs(this - setPeep)                // controlling PEEP                peep = if (setPeep >= 2 && deviation <= THRESHOLD_PEEP_DEVIATION) setPeep else this            }            updatePrimaryModelActualValue(LBL_PEEP, this)        }        rr?.apply {            if (this > THRESHOLD_RR_FOR_FLOW_SENSOR) {                if (++rrCheckCount > RR_THRESHOLD_CYCLE_COUNT) Log.i("RR", "Shooting out of range")                sendBroadcast(Intent(IntentFactory.ACTION_FLOW_SENSOR_OCCLUSION_DETECTED))            } else {                Log.i("RR", "Under range")                sendBroadcast(Intent(IntentFactory.ACTION_FLOW_SENSOR_OCCLUSION_RESOLVED))                rrCheckCount = 0            }            if (this == 0f) {                updatePrimaryModelActualValue(LBL_RR, "-")            } else {                updatePrimaryModelActualValue(LBL_RR, this)            }        }        //Nadeem        if (tiTot != null) {            updatePrimaryModelActualValue(LBL_TITOT, tiTot.toInt().toString() + " %")            var ieRatio = "-"            try {                if (tiTot != 0f) {                    val eiRatio: Float = 100 / tiTot - 1                    ieRatio = "1:" + String.format("%.1f", eiRatio)                    cachedIERatio = eiRatio                }            } catch (e: Exception) {                cachedIERatio = 0f                e.printStackTrace()                Log.i("IERATIO CHECK", "error : " + e.message)            } finally {                updatePrimaryModelActualValue(LBL_IE_RATIO, ieRatio)            }        }        if (prefManager?.readLastVentMode() != 60) {            fio2?.apply {                updatePrimaryModelActualValue(LBL_FIO2, this)                Log.i("CHECKVALF", this.toString())            }        } else {            hfncFio2?.apply {                updatePrimaryModelActualValue(LBL_FIO2, this)                Log.i("CHECKVALF", this.toString())            }        }        leak?.let {            prefManager?.apply {                if (readCuffLeakageAlarmStatus()) {                    val isRRValid = rr?.let {                        if (it < THRESHOLD_RR_FOR_TUBE_BLOCKAGE) true                        else false                    }                    val isLeakValid = it < MAX_LEAK_THRESHOLD && it > MIN_LEAK_THRESHOLD                    if (isLeakValid && isRRValid == true) {                        if (++leakCheckCount > LEAK_THRESHOLD_CYCLE_COUNT) Log.i(                            "CUFF_LEAK", "Shooting out of range"                        )                        sendBroadcast(Intent(IntentFactory.ACTION_CUFF_LEAKAGE_DETECTED))                    } else {                        Log.i("CUFF_LEAK", "Under range")                        sendBroadcast(Intent(IntentFactory.ACTION_CUFF_LEAKAGE_RESOLVED))                        leakCheckCount = 0                    }                } else {                    Log.i("CUFF_LEAK", "Under range")                    sendBroadcast(Intent(IntentFactory.ACTION_CUFF_LEAKAGE_RESOLVED))                    leakCheckCount = 0                }                if (readLeakBasedAlarmStatus() && !isNivActive) {                    if (it >= LEAK_BASED_ALARM_THRESHOLD) {                        if (++leakBasedAlarmCheckCount > LEAK_BASED_ALARM_THRESHOLD_CYCLE_COUNT) Log.i(                            "LEAK_BASED_ALARM", "Shooting out of range"                        )                        sendBroadcast(Intent(IntentFactory.ACTION_LEAK_BASED_ALARM_DETECTED))                    } else {                        Log.i("LEAK_BASED_ALARM", "Under range")                        sendBroadcast(Intent(IntentFactory.ACTION_LEAK_BASED_ALARM_RESOLVED))                        leakBasedAlarmCheckCount = 0                    }                } else {                    Log.i("LEAK_BASED_ALARM", "Under range")                    sendBroadcast(Intent(IntentFactory.ACTION_LEAK_BASED_ALARM_RESOLVED))                    leakBasedAlarmCheckCount = 0                }                /*             HIGH LEAK VTI MAY BE INACCURACY ALARM :             Condition :  Leak should be greater than or equal to 90%             */                if (it >= HIGH_LEAK_INACCURACY_ALARM_THRESHOLD) {                    if (++highLeakInaccuracy > HIGH_LEAK_INACCURACY_THRESHOLD_CYCLE_COUNT) Log.i(                        "LEAK_INACCURACY_ALARM", "Shooting out of range"                    )                    sendBroadcast(Intent(IntentFactory.ACTION_HIGH_LEAK_INACCURACY_DETECTED))                } else {                    Log.i("LEAK_INACCURACY_ALARM", "Under range")                    sendBroadcast(Intent(IntentFactory.ACTION_HIGH_LEAK_INACCURACY_RESOLVED))                    highLeakInaccuracy = 0                }                if (it < 25) {                    updatePrimaryModelActualValue(LBL_AVERAGE_LEAK, 0)                    lastAvgLeak = 0.0f                } else if (it > 100) {                    updatePrimaryModelActualValue(LBL_AVERAGE_LEAK, 100)                    lastAvgLeak = 100.0f                } else {                    updatePrimaryModelActualValue(LBL_AVERAGE_LEAK, it)                    lastAvgLeak = it                }            }        }//        leakFlow?.apply { updateModelActualValue(LBL_LEAK_FLOW, this) }        volLeak?.apply { updatePrimaryModelActualValue(LBL_VLEAK, this) }        trigFlow?.apply {            trigFlow = if (this >= 0) 0f else this            updatePrimaryModelActualValue(LBL_TRIG_FLOW, this)        }        observedPplat?.apply { updatePrimaryModelActualValue(LBL_OBSERVED_PLATEAU_PRESSURE, this) }        meanAirwayPressure?.apply {            updatePrimaryModelActualValue(                LBL_MEAN_AIRWAY_PRESSURE, String.format("%.1f", this)            )        }        tInsp?.apply {            Log.i("CHECK_TINSP", "Tinsp Raw is -> $this")//            floorTinsp = floor(this)            val flooredTinsp = (floor(this * 10) / 10).toFloat()            Log.i("CHECK_TINSP", "Tinsp Floor is -> $flooredTinsp")            updatePrimaryModelActualValue(LBL_TINSP, String.format("%.1f", flooredTinsp))        }        Log.i("TINS", tInsp.toString())        tExpire?.apply {            Log.i("CHECK_TINSP", "Texp Raw is -> $this")//            floorTexp = floor(this)            val ceiledTexp = (ceil(this * 10) / 10).toFloat()            Log.i("CHECK_TINSP", "Texp Ceil is -> $ceiledTexp")            updatePrimaryModelActualValue(LBL_TEXPR, String.format("%.1f", ceiledTexp))        }        tRise?.apply { updatePrimaryModelActualValue(LBL_TRISE, String.format("%.1f", this)) }        if (trigger != null && (tbCount++) % TRIGG_BALANCE_COUNT == 0) {            updatePrimaryModelActualValue(LBL_TRIGGER, trigger)        }        if (peep != null && cachedPip != null && cachedPip!! > peep!!) {            dynamicCompliance = cachedVti!! / (cachedPip!! - peep!!)        }        Log.i("Dynamic Compliance", dynamicCompliance.toString())        Log.d("ackvisibilitycheck", ackVisibilities[5090].toString())        val check = ackVisibilities[5090].toString()        if (ackVisibilities[5090]) {            ackVisibilities[5090] = false        }        if (ackVisibilities[5091]) {            // Maneuvers specific block            observedPplat?.apply {                var staticCompliance: Float? = null                try {                    cachedPeep?.let { it1 ->                        val pressureVariation = observedPplat - it1                        staticCompliance = (vti)?.div(pressureVariation)                        addEvents(                            "Inspiratory Hold Success with observed Pplat : $observedPplat & Static Compliance : $staticCompliance",                            prefManager?.readUHID().toString()                        )                        expiratoryInspiratoryFragmentDialog =                            ExpiratoryInspiratoryFragmentDialog.newInstance(                                observedPplat,                                staticCompliance,                                null,                                true                            )                        expiratoryInspiratoryFragmentDialog?.show(                            supportFragmentManager,                            ExpiratoryInspiratoryFragmentDialog.TAG                        )                        if (expiratoryInspiratoryFragmentDialog != null) {                            Handler(Looper.getMainLooper()).postDelayed(                                { expiratoryInspiratoryFragmentDialog?.dismiss() },                                30000                            )                        }                        ackVisibilities[5091] = false                    }                } catch (e: Exception) {                    e.printStackTrace()                }            }        }        if (ackVisibilities[5092]) {            ackVisibilities[5092] = false        }        if (ackVisibilities[5093]) {            addEvents(                "Expiratory Hold Success with peep : $cachedPeep",                prefManager?.readUHID().toString()            )            cachedPeep?.let {                expiratoryInspiratoryFragmentDialog =                    ExpiratoryInspiratoryFragmentDialog.newInstance(null, null, cachedPeep, false)                expiratoryInspiratoryFragmentDialog?.show(                    supportFragmentManager, ExpiratoryInspiratoryFragmentDialog.TAG                )                ackVisibilities[5093] = false            }        }        dynamicCompliance?.let {            prefManager?.apply {                if (readTubeBlockageAlarmStatus()) {                    // patient should not be disconnected ie leak < 70%                    lastAvgLeak?.apply {                        isPatientAvailable = this < MAX_LEAK_THRESHOLD                    }                    val isRRValid = rr?.let {                        if (it < THRESHOLD_RR_FOR_TUBE_BLOCKAGE) true                        else false                    }                    if (it < DYNAMIC_COMPLIANCE_THRESHOLD && isPatientAvailable && isRRValid == true) {                        if (++complianceCheckCount > COMPLIANCE_THRESHOLD_CYCLE_COUNT) sendBroadcast(                            Intent(IntentFactory.ACTION_TUBE_BLOCKAGE_DETECTED)                        )                    } else {                        sendBroadcast(Intent(IntentFactory.ACTION_TUBE_BLOCKAGE_RESOLVED))                        complianceCheckCount = 0                    }                } else {                    sendBroadcast(Intent(IntentFactory.ACTION_TUBE_BLOCKAGE_RESOLVED))                    complianceCheckCount = 0                }                updatePrimaryModelActualValue(LBL_DYNAMIC_COMPLIANCE, it)            }        }    }    private fun trendsLogic() {        Log.i("tetingmasoom", "2")        prefManager?.readLastVentMode()?.let {            getVentilatorModeByCode(                this@DashBoardActivity, it            )        }?.let {            breathCacheList[0].mode = it.modeType        } ?: kotlin.run {            breathCacheList[0].mode = ""        }        addTrendsDataIntoFile(breathCacheList[0])        // call api for trends        val request = TrendsRequestBodyModel()        request.apply {            time = AppUtils.getCurrentDateTimeForTrends()            did = Settings.Secure.getString(                this@DashBoardActivity.contentResolver, Settings.Secure.ANDROID_ID            )            spo2 = breathCacheList[0].spo2.toInt().toString()            pr = breathCacheList[0].pr.toInt().toString()            mode = breathCacheList[0].mode            pip = breathCacheList[0].pip.toInt().toString()            peep = breathCacheList[0].peep.toInt().toString()            vti = breathCacheList[0].vti.toInt().toString()            vte = breathCacheList[0].vte.toInt().toString()            mve = String.format("%.1f", breathCacheList[0].mve)            mean_Airway = breathCacheList[0].meanAirway.toInt().toString()            mvi = String.format("%.1f", breathCacheList[0].mvi)            fio2 = breathCacheList[0].fio2.toInt().toString()            respiratory_Rate = breathCacheList[0].respiratoryRate.toFloat().toInt().toString()            ie = "1 : " + String.format("%.1f", breathCacheList[0].iE.toFloat())            tinsp = String.format("%.1f", breathCacheList[0].tinsp.toFloat())            texp = String.format("%.1f", breathCacheList[0].texp.toFloat())            averageLeak = breathCacheList[0].averageLeak.toFloat().toInt().toString()        }        Log.i("trendsApi", "$request")        ServerLogger.sendTrendsRequest(this, request)        breathCacheList.clear()    }    private fun addTrendsDataIntoFile(data: TrendDBModel) {        var trendSingleLineData: String        data.apply {            trendSingleLineData = "${AppUtils.getCurrentDateTimeForTrends()},$mode,${                String.format(                    "%.1f", pip                )            },${                String.format(                    "%.1f", peep                )            },${                String.format(                    "%.1f", meanAirway                )            },${                String.format(                    "%.1f", vti                )            },${                String.format(                    "%.1f", vte                )            },${                String.format(                    "%.1f", mve                )            },${                String.format(                    "%.1f", mvi                )            },${                String.format(                    "%.1f", fio2                )            },${                String.format(                    "%.1f", respiratoryRate                )            },${                String.format(                    "%.1f", iE                )            },${                String.format(                    "%.1f", tinsp                )            },${                String.format(                    "%.1f", texp                )            },${                String.format(                    "%.1f", averageLeak                )            },${                String.format(                    "%.1f", spo2                )            },${                String.format(                    "%.1f", pr                )            }|"        }        FileLogger.writeTrendGraphFile(ctx, "trends", trendSingleLineData)    }    private fun addVolumeGraphEntry(volume: Float, vCount: Int) {        when (val graphLayoutFragment =            supportFragmentManager.findFragmentById(R.id.dashboard_nav_container)) {            is LoopsFragmentGraph -> graphLayoutFragment.addGraphVolumeData(                vCount, volume            )            is DivideQuadFragmentGraph -> graphLayoutFragment.addGraphVolumeData(                vCount, volume            )            is QuadFragmentGraph -> graphLayoutFragment.addGraphVolumeData(                vCount, volume            )            is TrioFragmentGraph -> graphLayoutFragment.addGraphVolumeData(                vCount, volume            )            is DuoFragmentGraph -> graphLayoutFragment.addGraphVolumeData(                vCount, volume            )            is DivideTrioFragmentGraph -> graphLayoutFragment.addGraphVolumeData(                vCount, volume            )            is LinearQuadGraphFragment -> graphLayoutFragment.addGraphVolumeData(vCount, volume)            is DefaultFragment -> graphLayoutFragment.addGraphVolumeData(                0, 0.0f            )            else -> throw UnsupportedOperationException("Invalid fragment type")        }        Log.i("VOLUME_GRAPH", volume.toString())    }    private fun addFlowGraphEntry(flow: Float, fCount: Int) {        when (val graphLayoutFragment =            supportFragmentManager.findFragmentById(R.id.dashboard_nav_container)) {            is LoopsFragmentGraph -> graphLayoutFragment.addGraphFlowData(                fCount, flow            )            is DivideQuadFragmentGraph -> graphLayoutFragment.addGraphFlowData(                fCount, flow            )            is QuadFragmentGraph -> graphLayoutFragment.addGraphFlowData(                fCount, flow            )            is DuoFragmentGraph -> graphLayoutFragment.addGraphFlowData(                fCount, flow            )            is TrioFragmentGraph -> graphLayoutFragment.addGraphFlowData(                fCount, flow            )            is DivideTrioFragmentGraph -> graphLayoutFragment.addGraphFlowData(                fCount, flow            )            is LinearQuadGraphFragment -> graphLayoutFragment.addGraphFlowData(fCount, flow)            is DefaultFragment -> graphLayoutFragment.addGraphFlowData(                0, 0.0f            )            else -> throw UnsupportedOperationException("Invalid fragment type")        }        Log.i("FLOW_GRAPH", flow.toString())    }    private fun addPressureGraphEntry(pressure: Float, pCount: Int, trigger: String?) {        when (val graphLayoutFragment =            supportFragmentManager.findFragmentById(R.id.dashboard_nav_container)) {            is LoopsFragmentGraph -> graphLayoutFragment.addGraphPressureData(                pCount, pressure, trigger            )            is DivideQuadFragmentGraph -> graphLayoutFragment.addGraphPressureData(                pCount, pressure, trigger            )            is QuadFragmentGraph -> graphLayoutFragment.addGraphPressureData(                pCount, pressure, trigger            )            is DuoFragmentGraph -> graphLayoutFragment.addGraphPressureData(                pCount, pressure, trigger            )            is TrioFragmentGraph -> graphLayoutFragment.addGraphPressureData(                pCount, pressure, trigger            )            is DivideTrioFragmentGraph -> graphLayoutFragment.addGraphPressureData(                pCount, pressure, trigger            )            is LinearQuadGraphFragment -> graphLayoutFragment.addGraphPressureData(                pCount, pressure, trigger            )            is DefaultFragment -> graphLayoutFragment.addGraphPressureData(                0, 0.0f            )            else -> {                throw UnsupportedOperationException("Invalid fragment type")            }        }    }    private fun addEtco2GraphEntry(etco2: Float, eCount: Int) {        when (val graphLayoutFragment =            supportFragmentManager.findFragmentById(R.id.dashboard_nav_container)) {            is LinearQuadGraphFragment -> graphLayoutFragment.addEtCo2GraphData(eCount, etco2)            else -> {            }        }    }    private fun clearDataSeries() {        when (val graphLayoutFragment =            supportFragmentManager.findFragmentById(R.id.dashboard_nav_container)) {            is LoopsFragmentGraph -> graphLayoutFragment.clearSeries()            is DivideQuadFragmentGraph -> graphLayoutFragment.clearSeries()            is QuadFragmentGraph -> graphLayoutFragment.clearSeries()            is DuoFragmentGraph -> graphLayoutFragment.clearSeries()            is TrioFragmentGraph -> graphLayoutFragment.clearSeries()            is DivideTrioFragmentGraph -> graphLayoutFragment.clearSeries()            is LinearQuadGraphFragment -> graphLayoutFragment.clearSeries()            is DefaultFragment -> graphLayoutFragment.clearSeries()            else -> throw UnsupportedOperationException("Invalid fragment type")        }    }    /*    * add updated data to tiles    * Returns the update data model     */    private fun updatePrimaryModelActualValue(lbl: String, value: Float?): ObservedParameterModel? {        return updatePrimaryModelActualValue(lbl, value?.toInt())    }    private fun updatePrimaryModelActualValue(lbl: String, value: Int?): ObservedParameterModel? {        return updatePrimaryModelActualValue(lbl, value.toString())    }    private fun updatePrimaryModelActualValue(        lbl: String, value: Float?, rsbi: Int?    ): ObservedParameterModel? {        return updatePrimaryModelActualValue(lbl, value.toString())    }    private fun updatePrimaryModelActualValue(lbl: String, value: String): ObservedParameterModel? {        var resultValue = value        //invoked for Range filtration        try {            val tValue = if (LBL_TITOT == lbl) resultValue.substring(                0, resultValue.length - 1            ) else resultValue            tValue.toFloatOrNull()?.let { validateRangeLimits(lbl, it) }        } catch (e: Exception) {            Log.i(                "DASHBOARD_ACTIVITY",                "Error while validating value= $resultValue against software limits"            )            e.printStackTrace()        }        if (lbl == LBL_AVERAGE_LEAK) {            if (prefManager?.readSelectedOptions() == SELECTED_OPTIONS.NON_INVASIVE_NAME) {                Log.i("CHECK_LEAKAGE_ALARM_NIV", "Average leak countered in NIV MODES")            } else {                if (prefManager?.readSelectedOptions() == SELECTED_OPTIONS.INVASIVE_NAME && prefManager?.readLastVentMode() != MODE_NC_IPPV) {                    if (resultValue.toInt() > 90) {                        if (!alarmsMap.containsKey(LBL_AVERAGE_LEAK)) {                            addAlarm(                                LBL_AVERAGE_LEAK,                                "Leakage",                                prefManager?.readUHID().toString()                            )                        }                    } else {                        if (alarmsMap.containsKey(LBL_AVERAGE_LEAK)) removeAlarm(LBL_AVERAGE_LEAK)                    }                } else if (prefManager?.readSelectedOptions() == SELECTED_OPTIONS.NON_INVASIVE_NAME && prefManager?.readLastVentMode() != MODE_NC_IPPV) {                    if (resultValue.toInt() > 60) {                        if (!alarmsMap.containsKey(LBL_AVERAGE_LEAK)) {                            addAlarm(                                LBL_AVERAGE_LEAK,                                "Leakage",                                prefManager?.readUHID().toString()                            )                        }                    } else {                        if (alarmsMap.containsKey(LBL_AVERAGE_LEAK)) removeAlarm(LBL_AVERAGE_LEAK)                    }                }            }        } else if (lbl == LBL_PEEP) {            prefManager?.apply {                Log.i("calueasd", "${(readPEEP()).toInt().toString()} , $resultValue")                if ((readPEEP() + 1).toInt().toString()                        .equals(resultValue) || (readPEEP() - 1).toInt().toString()                        .equals(resultValue)                ) {                    resultValue = readPEEP().toInt().toString()                }            }        } else if (lbl == LBL_FIO2) {            if (resultValue.toFloat() >= 25.0f) {                prefManager?.apply {                    if (readFiO2() >= 24.0f) {                        for (i in 1 until 5) {                            Log.i("swas", i.toString())                            if ((readFiO2() + i).toInt().toString()                                    .equals(resultValue) || (readFiO2() - i).toInt().toString()                                    .equals(resultValue)                            ) {                                resultValue = readFiO2().toInt().toString()                            }                        }                    }                }            } else {                resultValue = value            }        }        val model = primaryTileMap.get(lbl)        if (model != null) {            model.actualValue = resultValue            //Log.d("Thevalueofrsbi","${}")            primaryTileMap.put(lbl, model)            selectedTiles.let {                if (it.contains(model)) {                    it[it.indexOf(model)] = model                    primaryObservedParameterAdapter?.notifyItemChanged(it.indexOf(model))                }            }        }        Log.i(            "check_vent_mode", "updatePrimaryModelActualValue Dashboard ${                prefManager?.readVentilationMode().toString()            }"        )        if (prefManager?.readVentilationMode() == MODE_HFNC) {            notifyValueInHFNC(lbl, resultValue)        } else {            observedValueUpdate(lbl, resultValue)        }        return model    }    private fun updateSecondaryModelActualValue(        lbl: String, value: String    ): ObservedParameterModel? {        val model = observedValueSpHO2Map.get(lbl)        if (model != null) {            model.actualValue = value            secondaryObservedParameterAdapter?.notifyDataSetChanged()            observedValueSpHO2Map.put(lbl, model)            // add alarm for spo2            value.toFloatOrNull()?.let { validateRangeLimits(lbl, it) }            observedValueSpHOList.let {                if (it.contains(model)) {                    it[it.indexOf(model)] = model                    secondaryObservedParameterAdapter?.notifyItemChanged(it.indexOf(model))                    monitoringDialogFragment?.takeIf { it.isVisible }?.apply {                        setSpo2DataList(it)                        secondaryObservedParameterAdapter?.notifyDataSetChanged()                    }                }            }        }        observedValueUpdate(lbl, value)        return model    }    private fun observedValueUpdate(lbl: String, value: String): ObservedParameterModel? {        val model = observedValueMap.get(lbl)        if (model != null) {            // not to update if the value is same            //To be checked Once by Nadeem            if (value == model.actualValue) {                return model            }            model.actualValue = value            primaryObservedParameterAdapter?.notifyDataSetChanged()            observedValueMap.put(lbl, model)            observedValueList.let { it1 ->                if (it1.contains(model)) {                    it1[it1.indexOf(model)] = model                    monitoringDialogFragment?.takeIf { it.isVisible }?.apply {                        setModeList(it1)                        primaryObservedParameterAdapter?.notifyDataSetChanged()                    }                }            }        }        return model    }    private fun updateGraphictoolTip(controlParameterModel: ControlParameterModel) {        graphicTooltipFragment?.takeIf { it.isVisible }?.updateDataOnView(controlParameterModel)    }    // o(n+m+p) time complexity    private fun sendDataToLiveFragment() {        // add device id        dataStringLive = deviceId        dataStringLive += "^"        // add mode name        prefManager?.readLastVentMode()?.let {            getVentilatorModeByCode(                this@DashBoardActivity, it            )        }?.let {            dataStringLive += it.modeType        } ?: kotlin.run {            dataStoreModelAvg.mode = ""        }        dataStringLive += "^"        // data of observed parameter        for (i in observedValueList) {            if (i.label != "" && i.actualValue != "") dataStringLive += "${i.label}~${i.actualValue},"        }        dataStringLive = dataStringLive.substring(0, dataStringLive.length - 1) + "^"        // data of set parameter        for (i in basicControlParameterList) {            if (i.title != "" && i.reading != "" && i.units != "") dataStringLive += "${i.title}~${i.reading}~${i.units},"        }        dataStringLive = dataStringLive.substring(0, dataStringLive.length - 1) + "^"        // data of secondary observed        for (i in selectedTiles) {            if (i.label != "" && i.actualValue != "" && i.units != "") dataStringLive += "${i.label}~${i.actualValue}~${i.units},"        }        dataStringLive = dataStringLive.substring(0, dataStringLive.length - 1) + "^"        // send data of spo2 list        for (i in observedValueSpHOList) {            dataStringLive += "${i.label}~${i.actualValue}~${i.units},"        }        dataStringLive = dataStringLive.substring(0, dataStringLive.length - 1) + "^"        // added alarm data        dataStringLive += "${tvErrorBar.text}~${alarmBarColor}~${alarmTextColor}" + "^"        // send battery data to live window        dataStringLive += "$isBatteryConnected,$mBatteryLevel,$mBatteryPercentage,$isAlarmMuted,$isPatientTrigger,$isManualBreath^"        // usb connection data        dataStringLive += "${communicationService?.isVentilatorConnected},${communicationService?.isHIDConnected}"        Log.i("dataLiveSend", dataStringLive)        if (isLiveDataRequest) mSocket?.emit("DataSendingAndroid", dataStringLive)    }    private fun sendGraphDataToLiveFragment(x: Int, flow: Float, volume: Float, pressure: Float) {        // add device id        dataGraphStringLive = deviceId        dataGraphStringLive += "^"        // send pressure,flow, volume        dataGraphStringLive += "$x,$pressure,$volume,$flow"        Log.i("dataLiveSend", dataGraphStringLive)        if (VentilatorApp.isLiveGraphDataRequest) mSocket?.emit(            "DataGraphSendingAndroid", dataGraphStringLive        )    }    private fun updateVentParameterValue(lbl: String, value: String): ControlParameterModel? {        isFio2ValueChange = lbl == LBL_FIO2        val model = ventBasicParameterMap[lbl]        if (model?.upperLimit == value.toDouble()) {        }        if (model != null) {            // not to update if the value is same            if (value == model.reading) {                return model            }            Log.i("updateVentParameterValue", "lbl: $lbl, value: $value")            if (lbl != LBL_TINSP) model.reading = Configs.supportPrecision(lbl, value)            else model.reading = value            ventBasicParameterMap.put(lbl, model)            basicControlParameterList.let {                if (it.contains(model)) {                    it[it.indexOf(model)] = model                    primaryControlParameterAdapter?.notifyItemChanged(it.indexOf(model))                }            }            if (controlDialogFragment?.isVisible == true) {                controlDialogFragment?.notifyParameterAdapter()            }            // show changes in graphic tool tip            updateGraphictoolTip(model)        }        return model    }    private fun updateVentAdvancedParameterValue(        lbl: String, value: String    ): ControlParameterModel? {        val model = ventAdvancedParameterMap[lbl]        if (model?.upperLimit == value.toDouble()) {        }        if (model != null) {            // not to update if the value is same            if (value == model.reading) {                return model            }            model.reading = Configs.supportPrecision(lbl, value)            ventAdvancedParameterMap.put(lbl, model)            advancedControlParameterList.let {                if (it.contains(model)) {                    it[it.indexOf(model)] = model                }            }            if (controlDialogFragment?.isVisible == true) {                controlDialogFragment?.notifyParameterAdapter()            }        }        return model    }    private fun updateVentBackupParameterValue(lbl: String, value: String): ControlParameterModel? {        val model = ventBackupParameterMap[lbl]        if (model?.upperLimit == value.toDouble()) {        }        if (model != null) {            // not to update if the value is same            if (value == model.reading) {                return model            }            model.reading = Configs.supportPrecision(lbl, value)            ventBackupParameterMap.put(lbl, model)            backupControlParameterList?.let {                if (it.contains(model)) {                    it[it.indexOf(model)] = model                } else Log.i("ADAPTER", "Unable to update")         