        if (model != null) {            if (value == model.reading) {                return model            }            model.reading = Configs.supportPrecision(lbl, value)            ventEtCuffParameterMap.put(lbl, model)            etCuffControlParameterList.let {                if (it.contains(model)) {                    it[it.indexOf(model)] = model                } else Log.i("ADAPTER", "Unable to update")            }            if (controlDialogFragment?.isVisible == true) {                Log.i("value_model_smart_fio2", "enter")                controlDialogFragment?.notifyParameterAdapter()            }        }        return model    }    private var cachedPIPAlarmState = false    private var cachedVTEAlarmState = false    private var cachedRRAlarmState = false    private var cachedPEEPAlarmState = false    private var cachedMVIAlarmState = false    private var cachedTiTOTAlarmState = false    private var cachedAvgLeakAlarmState = false    private var cachedFiO2AlarmState = false    private var cachedSpO2AlarmState = false    // Validate user set limits    private fun validateRangeLimits(key: String, value: Float) {        var currentLable: String? = null        var i: Intent? = null        prefManager?.apply {            var limits: Array<Float?>? = null            var parametername: String? = null            when (key) {                LBL_PIP -> {                    currentLable = Configs.ALARM_PIP                    if (readPipLimitState()) {                        limits = readPipLimits()                        parametername = getString(R.string.plimit)                    } else {                        if (cachedPIPAlarmState) {                            i = Intent(IntentFactory.ACTION_VENT_PARAM_LIMIT_UNDERFLOW).apply {                                putExtra(ALERT_LABEL, currentLable)                                putExtra(                                    ALERT_MSG,                                    parametername + " " + getString(R.string.normal_value_msg_suffix)                                )                            }                        }                    }                    cachedPIPAlarmState = readPipLimitState()                }                LBL_VTE -> {                    currentLable = Configs.ALARM_VTE                    if (readVteLimitState()) {                        limits = readVteLimits()                        parametername = getString(R.string.hint_vte)                    } else {                        if (cachedVTEAlarmState) {                            i = Intent(IntentFactory.ACTION_VENT_PARAM_LIMIT_UNDERFLOW).apply {                                putExtra(ALERT_LABEL, currentLable)                                putExtra(                                    ALERT_MSG,                                    parametername + " " + getString(R.string.normal_value_msg_suffix)                                )                                Log.i("SOFTALARM CHECK", "$parametername is detected to be STABLE")                            }                        }                    }                    cachedVTEAlarmState = readVteLimitState()                }                LBL_RR -> {                    currentLable = Configs.ALARM_RR                    if (readRRLimitState()) {                        limits = readRRLimits()                        parametername = getString(R.string.respiratory_rate)                    } else {                        if (cachedRRAlarmState) {                            i = Intent(IntentFactory.ACTION_VENT_PARAM_LIMIT_UNDERFLOW).apply {                                putExtra(ALERT_LABEL, currentLable)                                putExtra(                                    ALERT_MSG,                                    parametername + " " + getString(R.string.normal_value_msg_suffix)                                )                            }                        }                    }                    cachedRRAlarmState = readRRLimitState()                }                LBL_PEEP -> {                    currentLable = Configs.ALARM_PEEP                    if (readPeepLimitState()) {                        limits = readPeepLimits()                        parametername = getString(R.string.peep)                    } else {                        if (cachedPEEPAlarmState) {                            i = Intent(IntentFactory.ACTION_VENT_PARAM_LIMIT_UNDERFLOW).apply {                                putExtra(ALERT_LABEL, currentLable)                                putExtra(                                    ALERT_MSG,                                    parametername + " " + getString(R.string.normal_value_msg_suffix)                                )                            }                        }                    }                    cachedPEEPAlarmState = readPeepLimitState()                }                LBL_MVE -> {                    currentLable = Configs.ALARM_MVE                    if (readMveLimitState()) {                        limits = readMveLimits()                        parametername = getString(R.string.mve)                    } else {                        if (cachedMVIAlarmState) {                            i = Intent(IntentFactory.ACTION_VENT_PARAM_LIMIT_UNDERFLOW).apply {                                putExtra(ALERT_LABEL, currentLable)                                putExtra(                                    ALERT_MSG,                                    parametername + " " + getString(R.string.normal_value_msg_suffix)                                )                            }                        }                    }                    cachedMVIAlarmState = readMveLimitState()                }                LBL_FIO2 -> {                    currentLable = LBL_FIO2                    if (readFio2LimitState()) {                        limits = readFiO2Limits()                        parametername = getString(R.string.fio2)                    } else {                        if (cachedFiO2AlarmState) {                            i = Intent(IntentFactory.ACTION_VENT_PARAM_LIMIT_UNDERFLOW).apply {                                putExtra(ALERT_LABEL, currentLable)                                putExtra(                                    ALERT_MSG,                                    parametername + " " + getString(R.string.normal_value_msg_suffix)                                )                            }                        }                    }                    cachedFiO2AlarmState = readFio2LimitState()                }                LBL_SPO2 -> {                    currentLable = LBL_SPO2                    if (readSpO2LimitState()) {                        limits = readSpO2Limits()                        parametername = getString(R.string.spo2)                    } else {                        if (cachedSpO2AlarmState) {                            i = Intent(IntentFactory.ACTION_VENT_PARAM_LIMIT_UNDERFLOW).apply {                                putExtra(ALERT_LABEL, currentLable)                                putExtra(                                    ALERT_MSG,                                    parametername + " " + getString(R.string.normal_value_msg_suffix)                                )                            }                        }                    }                    cachedSpO2AlarmState = readSpO2LimitState()                }            }            // null safety & condition check            limits?.takeIf { it.size >= 2 && it[0] != null && it[1] != null }?.apply {                val lowerLimit = this[0]!!                val upperLimit = this[1]!!                when {                    value < lowerLimit -> {                        i = Intent(IntentFactory.ACTION_VENT_PARAM_LIMIT_OVERFLOW)                        i?.putExtra(ALERT_LABEL, currentLable)                        i?.putExtra(                            ALERT_MSG,                            parametername + " " + getString(R.string.low_value_msg_suffix)                        )                    }                    value > upperLimit -> {                        i = Intent(IntentFactory.ACTION_VENT_PARAM_LIMIT_OVERFLOW)                        i?.putExtra(ALERT_LABEL, currentLable)                        i?.putExtra(                            ALERT_MSG,                            parametername + " " + getString(R.string.high_value_msg_suffix)                        )                    }                    else -> {                        i = Intent(IntentFactory.ACTION_VENT_PARAM_LIMIT_UNDERFLOW)                        i?.putExtra(ALERT_LABEL, currentLable)                        i?.putExtra(                            ALERT_MSG,                            parametername + " " + getString(R.string.normal_value_msg_suffix)                        )                    }                }                if (isNivActive && LBL_VTI == key && IntentFactory.ACTION_VENT_PARAM_LIMIT_OVERFLOW.equals(                        i?.action                    )                ) {                    i?.action = IntentFactory.ACTION_VENT_PARAM_LIMIT_UNDERFLOW                }            }            i?.run { sendBroadcast(this) }        }    }    var breathCacheList: ArrayList<TrendDBModel> = ArrayList<TrendDBModel>()    private fun getCurrentTimeStamp(): String? {        return Date().toString()    }    private fun getMapValueFromLabel(map: Map<String, String>, lbl: String): Float? {        try {            if (map.containsKey(lbl)) return (map[lbl]?.toFloatOrNull())        } catch (exception: NumberFormatException) {            exception.printStackTrace()            return null        }        return null    }    fun sendControlModeToVentilator(mode: Int) {        communicationService?.takeIf { it.isPortsConnected }?.apply {            if (VentilatorApp.selectedOptions == SELECTED_OPTIONS.PRONGS_NAME && (mode != MODE_NC_CPAP && mode != MODE_HFNC)) send(                MODE_NC_IPPV.toString()            )            else if (mode == MODE_PC_PRVC) {                send(Configs.MODE_PC_SIMV.toString())            } else {                send(mode.toString())            }            Log.i("modeCurrent", mode.toString())        }    }    private fun sendConfigurationToVentilatorWithWatchDog() {        if (settingsCountDownTimer == null) {            settingsCountDownTimer = SettingsCountDownTimer(2500, 700)        }        communicationService?.takeIf { it.isPortsConnected }?.apply {            settingsCountDownTimer?.startRunning()        }    }    private fun sendO2CalibrationCommandToVentilator() {        communicationService?.takeIf { it.isPortsConnected }?.apply {            send(getString(R.string.cmd_calibration_oxyzen))        }    }    private fun sendShutDownCommandToVentilator() {        communicationService?.send(getString(R.string.cmd_vent_shutdown))    }    private fun sendStandbyCommandToVentilator() {        communicationService?.takeIf { it.isPortsConnected }?.apply {            sendConfigurationToVentilator { config ->                val list: ConfigurationArrayList = config.clone() as ConfigurationArrayList                if (list.size > 8) {                    val fio2 = getString(R.string.fio2_on_standby)                    list.set(8, fio2)                }                list            }            Handler(Looper.getMainLooper()).postDelayed({                // Dismiss progress bar after 2 seconds                send(resources.getString(R.string.cmd_vent_standby))            }, 1000)        }    }    /*     * Customized countdown timer for 5155tion     */    open inner class CalibrationCountDownTimer(millisInFuture: Long, countDownInterval: Long) :        CountDownTimer(millisInFuture, countDownInterval) {        private var counter = 0        fun startProgress() {            counter = 0            start()        }        override fun onTick(millis: Long) {            if (counter <= 100) systemDialogFragment?.takeIf { it.isVisible }?.apply {                updateOxygenCalibrateProgressStatus(                    counter++, "Calibration in progress", View.TEXT_ALIGNMENT_CENTER                )            }        }        override fun onFinish() {            cancel()        }    }    open inner class SettingsCountDownTimer(millisInFuture: Long, countDownInterval: Long) :        CountDownTimer(millisInFuture, countDownInterval) {        private var isSafeStop = false        private var isRunning = false        private var isFirstCallElapsed = false        fun startRunning() {            if (!isRunning) {                isSafeStop = false                isRunning = true                Log.i("WATCHDOG_CHECK", "Starting watchdog")                start()            }        }        fun safeStop() {            isSafeStop = true            if (isRunning) {                Log.i("WATCHDOG_CHECK", "Stoping watchdog")                cancel()            }        }        override fun onTick(millis: Long) {            communicationService?.takeIf { it.isPortsConnected }?.apply {                sendConfigurationToVentilator()            }        }        override fun onFinish() {            if (isFirstCallElapsed) {                if (!isSafeStop) {                    ToastFactory.setSnackBar(                        mainViewPanelDashboard, getString(R.string.hint_setting_failure)                    )                }            } else isFirstCallElapsed = true            isRunning = false        }    }    override fun onCalibration() {        sendO2CalibrationCommandToVentilator()    }    override fun onAdjustLoudness(volumeLevel: Float) {        mediaPlayer?.apply {            setVolume(                volumeLevel / VOLUME_MAX_VALUE, volumeLevel / VOLUME_MAX_VALUE            )        }    }    // change here 19 sep    override fun onCheckLoudness() {        val uri = URI_ALARM_CRITICAL_LEVEL        uri?.let {            try {                prefManager?.apply {                    mediaPlayer?.apply {                        setVolume(                            readVolume() / VOLUME_MAX_VALUE, readVolume() / VOLUME_MAX_VALUE                        )                    }                }            } catch (e: Exception) {                e.printStackTrace()            }            object : CountDownTimer(5000, 1000) {                override fun onTick(millisUntilFinished: Long) {                }                override fun onFinish() {                    if (!isAlarmPlaying) {                        mediaPlayer?.setVolume(0.0f, 0.0f)                    }                }            }.start()        }    }    private fun onPlayAlarm() {        val uri = AlarmConfiguration.getAlarmUri(currentPriority)        uri?.also {            mediaPlayer = null            mediaPlayer = CustomMediaPlayer()            mediaPlayer?.apply {                val attrib: AudioAttributes =                    AudioAttributes.Builder().setLegacyStreamType(AudioManager.STREAM_ALARM).build()                setAudioAttributes(attrib)                setDataSource(this@DashBoardActivity, it)                prepare()                isLooping = true                mediaPlayer?.setVolume(0.0f, 0.0f)                start()            }        }    }    override fun onLimitChange(previousValue: Float, newValue: Float) {        val isAdvancedFragmentVisible = controlDialogFragment?.isAdvancedFragmentVisible() == true        val isBackupFragmentVisible = controlDialogFragment?.isBackupFragmentVisible() == true        if (isBackupFragmentVisible) {            selectedBackupPosition?.let { pos ->                backupControlParameterList?.getOrNull(pos)?.apply {                    updateVentBackupParameterValue(ventKey, newValue.toString())                }            }        } else if (isAdvancedFragmentVisible) {            selectedAdvancedPosition?.let { pos ->                advancedControlParameterList.getOrNull(pos)?.apply {                    updateVentAdvancedParameterValue(ventKey, newValue.toString())                }            }        }        selectedBasicPosition?.let { pos ->            basicControlParameterList.getOrNull(pos)?.apply {                updateVentParameterValue(ventKey, newValue.toString())            }        }        selectedSmartFio2Position?.let { pos ->            smartFio2ControlParameterList.getOrNull(pos)?.apply {                updateVentSmartFio2ParameterValue(ventKey, newValue.toString())            }        }        selectedVTasPosition?.let { pos ->            vTasControlParameterList.getOrNull(pos)?.apply {                updateVentVTasParameterValue(ventKey, newValue.toString())            }        }        selectedEtCuffPosition?.let { pos ->            etCuffControlParameterList.getOrNull(pos)?.apply {                updateVentEtCuffParameterValue(ventKey, newValue.toString())            }        }//        }    }    override fun onKnobPress(previousValue: Float, newValue: Float) {        // save value        // ventParameterTiles[selectedPosition].isIsselected=false        val isAdvancedFragmentVisible = controlDialogFragment?.isAdvancedFragmentVisible() == true        // val isBasicFragmentVisible = controlDialogFragment?.isBasicFragmentVisible() == true        val isBackupFragmentVisible = controlDialogFragment?.isBackupFragmentVisible() == true        if (isBackupFragmentVisible) {            backupControlParameterList?.let {                selectedBackupPosition?.apply {                    val lbl = it[this].ventKey                    val unit = it[this].units                    lbl?.let { paramLabel ->                        Log.i("LBL", "Selected label = $paramLabel, postion  = $this")                        prefManager?.apply { updateParameterViaName(paramLabel, newValue) }                        Log.i("SetValue", "Sett $lbl from $previousValue to $newValue")                        updateVentBackupParameterValue(paramLabel, newValue.toString())                        sendConfigurationToVentilatorWithWatchDog()                        addEvents(                            "Set $paramLabel from ${                                supportPrecision(paramLabel, previousValue)                            }  $unit to $newValue $unit", prefManager?.readUHID().toString()                        )                    }                    selectedBackupPosition = null                }            }            sendBackUpDataToLiveFragment()        } else if (isAdvancedFragmentVisible) {            advancedControlParameterList.let {                // ventParameterTiles[selectedPosition].isIsselected=false                selectedAdvancedPosition?.apply {                    val lbl = it[this].ventKey                    val unit = it[this].units                    lbl?.let { paramLabel ->                        Log.i("LBL", "Selected label = $paramLabel, postion  = $this")                        prefManager?.apply { updateParameterViaName(paramLabel, newValue) }                        Log.i("SetValue", "Sett $lbl from $previousValue to $newValue")                        updateVentAdvancedParameterValue(paramLabel, newValue.toString())                        sendConfigurationToVentilatorWithWatchDog()                        addEvents(                            "Set $paramLabel from ${                                supportPrecision(paramLabel, previousValue)                            }  $unit to $newValue $unit", prefManager?.readUHID().toString()                        )                    }                    selectedAdvancedPosition = null                }            }            sendAdvancedDataToLiveFragment()        }//        else {        basicControlParameterList.let {            // ventParameterTiles[selectedPosition].isIsselected=false            selectedBasicPosition?.apply {                val lbl = it[this].ventKey                val unit = it[this].units                lbl?.let { paramLabel ->                    Log.i("LBL", "Selected label = $paramLabel, postion  = $this")                    // ToDO : Save on shared pref//The smart Fio2 average section code section                    if (lbl == "FiO₂") {                        if (newValue < 100.0f) {                            stopFiO2()                            isOxygenRunning = false                        }                        prefManager?.setSmartFio2(newValue)                    }                    prefManager?.apply { updateParameterViaName(paramLabel, newValue) }                    Log.i("SetValue", "Sett $lbl from $previousValue to $newValue")                    updateVentParameterValue(paramLabel, newValue.toString())                    sendConfigurationToVentilatorWithWatchDog()                    addEvents(                        "Set $paramLabel from ${                            supportPrecision(paramLabel, previousValue)                        }  $unit to $newValue $unit", prefManager?.readUHID().toString()                    )                }                selectedBasicPosition = null            }            sendBasicDataToLiveFragment()        }        // added smartFio2        smartFio2ControlParameterList.let {            // ventParameterTiles[selectedPosition].isIsselected=false            selectedSmartFio2Position?.apply {                val lbl = it[this].ventKey                val unit = it[this].units                lbl?.let { paramLabel ->                    Log.i("LBL", "Selected label = $paramLabel, postion  = $this")                    // ToDO : Save on shared pref//The smart Fio2 average section code section                    if (lbl == "FiO₂") {                        prefManager?.setSmartFio2(newValue)                    }                    prefManager?.apply { updateParameterViaName(paramLabel, newValue) }                    Log.i("gettargetValue", "${prefManager?.readTargetSpO2().toString()}")                    Log.i("SetValue", "Sett $lbl from $previousValue to $newValue")                    updateVentSmartFio2ParameterValue(paramLabel, newValue.toString())                    sendConfigurationToVentilatorWithWatchDog()                    addEvents(                        "Set $paramLabel from ${                            supportPrecision(paramLabel, previousValue)                        }  $unit to $newValue $unit", prefManager?.readUHID().toString()                    )                }                selectedSmartFio2Position = null            }        }        // added vTas        vTasControlParameterList.let {            // ventParameterTiles[selectedPosition].isIsselected=false            selectedVTasPosition?.apply {                val lbl = it[this].ventKey                val unit = it[this].units                lbl?.let { paramLabel ->                    Log.i("LBL", "Selected label = $paramLabel, postion  = $this")                    if (lbl == "FiO₂") {                        prefManager?.setSmartFio2(newValue)                    }                    prefManager?.apply { updateParameterViaName(paramLabel, newValue) }                    Log.i("gettargetValue", prefManager?.readTargetSpO2().toString())                    Log.i("SetValue", "Sett $lbl from $previousValue to $newValue")                    updateVentVTasParameterValue(paramLabel, newValue.toString())                    sendConfigurationToVentilatorWithWatchDog()                    addEvents(                        "Set $paramLabel from ${                            supportPrecision(paramLabel, previousValue)                        }  $unit to $newValue $unit", prefManager?.readUHID().toString()                    )                }                selectedVTasPosition = null            }        }        etCuffControlParameterList.let {            selectedEtCuffPosition?.apply {                val lbl = it[this].ventKey                val unit = it[this].units                lbl?.let { paramLabel ->                    Log.i("LBL", "Selected label = $paramLabel, postion  = $this")                    if (lbl == "FiO₂") {                        prefManager?.setSmartFio2(newValue)                    }                    prefManager?.apply { updateParameterViaName(paramLabel, newValue) }                    Log.i("SetValue", "Sett $lbl from $previousValue to $newValue")                    updateVentEtCuffParameterValue(paramLabel, newValue.toString())//                    if (prefManager?.readEtCuffStatus() == true) sendMessageToServer("CM+EC1${prefManager?.readEtPressure()?.toInt()!!}")//                    else sendMessageToServer("CM+EC0")                    sendConfigurationToVentilatorWithWatchDog()                    addEvents(                        "Set $paramLabel from ${                            supportPrecision(paramLabel, previousValue)                        }  $unit to $newValue $unit", prefManager?.readUHID().toString()                    )                }                selectedEtCuffPosition = null            }        }//        }        normaliseParameterTiles()        hideKnobViews()        hideSystemUI()    }    private fun normaliseParameterTiles() {        Log.i("value1231", "4")        basicControlParameterList.forEach {            it?.isIsselected = false        }        advancedControlParameterList.forEach {            it?.isIsselected = false        }        backupControlParameterList?.forEach {            it?.isIsselected = false        }        smartFio2ControlParameterList.forEach {            it?.isIsselected = false        }        vTasControlParameterList.forEach {            it?.isIsselected = false        }        etCuffControlParameterList.forEach {            it?.isIsselected = false        }        selectedTiles.forEach {            it?.isSelectedAsSwappable = false        }        primaryControlParameterAdapter?.notifyDataSetChanged()        controlDialogFragment?.notifyParameterAdapter()        standbyControlFragment?.notifyParameterAdapter()        primaryObservedParameterAdapter?.notifyDataSetChanged()    }    private fun setControlParameterSelected(params: List<ControlParameterModel>, at: Int) {        Log.i("value1231", "10")        if (at < params.size) {            normaliseParameterTiles()            params[at].isIsselected = true        }    }    private fun updateModeAndSendParametersToVentilator(modeCode: Int) {        if (modeCode == MODE_AUTO_VENTILATION) {            prefManager?.apply {                Log.i(                    "check_vent_mode",                    "updateModeAndSendParametersToVentilator Dashboard ${modeCode.toString()}"                )                clearProfilePreferences(readCurrentUid())                setVentilationMode(modeCode)                setLastVentMode(modeCode)                CoroutineScope(Dispatchers.IO).launch {                    FileLogger.writeModeFile(this@DashBoardActivity, modeCode.toString())                }                //for normalizing the VGV Toggle            }            Configs.getAllControlParameterLists(this@DashBoardActivity, modeCode)?.flatten()?.let {                prefManager?.readApneaSettingsStatus()                    ?.let { it1 -> sendParametersToVentilator(it, it1) }            }        } else {            Log.i(                "check_vent_mode",                "updateModeAndSendParametersToVentilator Dashboard else block ${modeCode.toString()}"            )            prefManager?.setVentilationMode(modeCode)            prefManager?.setLastVentMode(modeCode)            CoroutineScope(Dispatchers.IO).launch {                FileLogger.writeModeFile(this@DashBoardActivity, modeCode.toString())            }            standbyControlFragment?.apply {                Log.i("MODE_CHECK", "Calling getAllCOntrolParameters")                getAllControlParameters().let {                    prefManager?.readApneaSettingsStatus()                        ?.let { it1 -> sendParametersToVentilator(it, it1) }                }            }        }    }    override fun onStart() {        super.onStart()        registerReceiver(gattReceiver, getIntentFilter())    }    private fun sendParametersToVentilator(        parameters: List<ControlParameterModel>, apneaStatus: Boolean    ) {        parameters.forEach {            try {                Log.i(                    "ONSTARTVENTILATION", "${it.ventKey} updated with value = ${it.reading}"                )                prefManager?.updateParameterViaName(                    it.ventKey, it.reading.toFloat()                )            } catch (e: Exception) {                e.printStackTrace()                Log.i(                    "ONSTARTVENTILATION", "Unable to parse some parameters to Float"                )            }        }        prefManager?.setApneaSettingsStatus(apneaStatus)        sendConfigurationToVentilatorWithWatchDog()    }    // update limits on the observed tiles    override fun onChangeAlarmLimit(        currentKey: String?, lowerLimit: Float, upperLimit: Float?    ) {        for (i in selectedTiles) {            if (i.label.equals(currentKey)) {                i.lowerLimitValue = lowerLimit.toString()                i.upperLimitValue = upperLimit.toString()            }        }        primaryObservedParameterAdapter?.notifyDataSetChanged()        if (observedValueSpHOList.any { (it.label + it.labelSubscript) == currentKey }) {            Log.i("ALARMLIMITCHECK", "Key = $currentKey found in secondary observed tiles")            val tempList = arrayListOf<ObservedParameterModel>()            for (i in observedValueSpHOList) {                if (i.label.equals(currentKey)) {                    i.lowerLimitValue = lowerLimit.toString()                    i.upperLimitValue = upperLimit.toString()                    tempList.add(i)                } else {                    tempList.add(i)                }            }            observedValueSpHOList = tempList            secondaryObservedParameterAdapter?.notifyDataSetChanged()        }    }    private fun getStandbyParameterClickListener(        params: MutableList<ControlParameterModel>?, type: ControlSettingType    ) = object : ControlParameterClickListener {        override fun onClick(position: Int, model: ControlParameterModel) {            params?.apply {                val knobModel = KnobParameterModel.fromControlParameter(model)                setControlParameterSelected(this, position)                val encoderValue = EncoderValue(                    model.lowerLimit.toFloat(), model.upperLimit.toFloat(), model.step.toFloat()                )                showKnobViewsForStandbyControls(                    knobModel, encoderValue, this, position, type                )            }            standbyControlFragment?.notifyParameterAdapter()        }        override fun onStateChange(isActive: Boolean, type: ControlSettingType, position: Int) {            if (type == ControlSettingType.ADVANCED) {                if (position == 0) {                    prefManager?.setIRVStatusTemp(isActive)                }            } else if (type == ControlSettingType.VTas) {                prefManager?.setVGVStatusTemp(isActive)            } else if (type == ControlSettingType.EtCuff) {                if (position == 0) {                    prefManager?.setEtCuffStatusTemp(isActive)                }            } else if (type == ControlSettingType.SmartFio2) {                prefManager?.setSmartFiO2StatusTemp(isActive)            } else if (type == ControlSettingType.BACKUP) {                if (prefManager?.readCurrentUid() != PatientProfile.TYPE_NEONAT) {                    Log.i("APNEA_BUTTON", "Apnea button is $isActive")                } else {                    prefManager?.setApneaSettingsStatusTemp(isActive)                }            }        }    }    private val onBasicParameterClickListener = object : ControlParameterClickListener {        override fun onClick(position: Int, model: ControlParameterModel) {            if (!isLocked) {                VentilatorApp.testingConditonMap.values.clear()                basicControlParameterList.let {                    selectedBasicPosition = position                    selectedAdvancedPosition = null                    selectedBackupPosition = null                    selectedSmartFio2Position = null                    selectedVTasPosition = null                    selectedEtCuffPosition = null                    val knobModel = KnobParameterModel.fromControlParameter(model)                    setControlParameterSelected(it, position)                    val encoderValue = EncoderValue(                        model.lowerLimit.toFloat(), model.upperLimit.toFloat(), model.step.toFloat()                    )                    showKnobViews(knobModel, encoderValue)                    primaryControlParameterAdapter?.notifyDataSetChanged()                }                controlDialogFragment?.notifyParameterAdapter()            } else {                DialogBoxFactory.dismissDialogs()                DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)            }        }        override fun onStateChange(isActive: Boolean, type: ControlSettingType, position: Int) {}    }    private val onAdvancedParameterClickListener = object : ControlParameterClickListener {        override fun onClick(position: Int, model: ControlParameterModel) {            advancedControlParameterList.let {                selectedBasicPosition = null                selectedAdvancedPosition = position                selectedBackupPosition = null                selectedSmartFio2Position = null                selectedVTasPosition = null                selectedEtCuffPosition = null                val knobModel = KnobParameterModel.fromControlParameter(model)                setControlParameterSelected(it, position)                val encoderValue = EncoderValue(                    model.lowerLimit.toFloat(), model.upperLimit.toFloat(), model.step.toFloat()                )                Log.i("ADVANCEDCHECK", "Encoder = " + encoderValue.toString())                showKnobViews(knobModel, encoderValue)            }            controlDialogFragment?.notifyParameterAdapter()        }        override fun onStateChange(isActive: Boolean, type: ControlSettingType, position: Int) {            Log.i("IRVMODE_CHECK", "Toggle state changed to " + isActive)            if (type == ControlSettingType.ADVANCED) {                if (position == 0) {                    prefManager?.apply {                        setIRVStatus(isActive)                    }                    sendAdvancedDataToLiveFragment()                }            }        }    }    private val onBackupParameterClickListener = object : ControlParameterClickListener {        override fun onClick(position: Int, model: ControlParameterModel) {            backupControlParameterList?.let {                selectedBasicPosition = null                selectedAdvancedPosition = null                selectedBackupPosition = position                selectedSmartFio2Position = null                selectedVTasPosition = null                selectedEtCuffPosition = null                val knobModel = KnobParameterModel.fromControlParameter(model)                setControlParameterSelected(it, position)                val encoderValue = EncoderValue(                    model.lowerLimit.toFloat(), model.upperLimit.toFloat(), model.step.toFloat()                )                Log.i("BACKUPCHECK", "Encoder = $encoderValue.toString()")                showKnobViews(knobModel, encoderValue)            }            controlDialogFragment?.notifyParameterAdapter()        }        override fun onStateChange(isActive: Boolean, type: ControlSettingType, position: Int) {            Log.i("STATECHANGE_CHECK", "Toggle state changed to " + isActive)            if (type == ControlSettingType.BACKUP) {                Log.i("STATECHANGE_CHECK", "In Backup Toggle state changed to " + isActive)                prefManager?.setApneaSettingsStatus(isActive)                sendConfigurationToVentilatorWithWatchDog()                sendBackUpDataToLiveFragment()            }        }    }    private val onSmartFio2ParamterClickListener = object : ControlParameterClickListener {        override fun onClick(position: Int, model: ControlParameterModel) {            smartFio2ControlParameterList.let {                selectedBasicPosition = null                selectedAdvancedPosition = null                selectedBackupPosition = null                selectedVTasPosition = null                selectedEtCuffPosition = null                selectedSmartFio2Position = position                val knobModel = KnobParameterModel.fromControlParameter(model)                setControlParameterSelected(it, position)                val encoderValue = EncoderValue(                    model.lowerLimit.toFloat(), model.upperLimit.toFloat(), model.step.toFloat()                )                Log.i("SmartCheck", "Encoder = $encoderValue.toString()")                showKnobViews(knobModel, encoderValue)            }            controlDialogFragment?.notifyParameterAdapter()        }        override fun onStateChange(isActive: Boolean, type: ControlSettingType, position: Int) {            Log.i("STATECHANGE_CHECK", "Toggle state changed to " + isActive)            //Fix the Toggle Position here            if (type == ControlSettingType.SmartFio2) {                //Smart code integration                prefManager?.setSmartFiO2Status(isActive)                mDashBoardViewModel.SmartSpo2Toggle.value = isActive            }            /*     if (type == ControlSettingType.SmartFio2) {                     prefManager?.setSmartFiO2Status(isActive)                     primaryControlParameterAdapter?.notifyDataSetChanged()                     Log.i("FIO2Toggle_check", "Toggle state changed to " + isActive)                 }*/        }    }    private val onVTasParamterClickListener = object : ControlParameterClickListener {        override fun onClick(position: Int, model: ControlParameterModel) {            vTasControlParameterList.let {                selectedBasicPosition = null                selectedAdvancedPosition = null                selectedBackupPosition = null                selectedSmartFio2Position = null                selectedEtCuffPosition = null                selectedVTasPosition = position                val knobModel = KnobParameterModel.fromControlParameter(model)                setControlParameterSelected(it, position)                val encoderValue = EncoderValue(                    model.lowerLimit.toFloat(), model.upperLimit.toFloat(), model.step.toFloat()                )                Log.i("SmartCheck", "Encoder = $encoderValue.toString()")                showKnobViews(knobModel, encoderValue)            }            controlDialogFragment?.notifyParameterAdapter()        }        override fun onStateChange(isActive: Boolean, type: ControlSettingType, position: Int) {            Log.i("STATECHANGE_CHECK", "