  sendConfigurationToVentilatorWithWatchDog()            }        }    }    // runs when swap is initiated    //ToDo:-current task the definition of the click event that has issue.    @SuppressLint("NotifyDataSetChanged")    override fun onClick(position: Int, model: ObservedParameterModel) {        if (prefManager?.readLastVentMode() == MODE_NC_CPAP || prefManager?.readLastVentMode() == MODE_HFNC) {            Log.i("CLICKED", "this is clicked")        } else {            filterObserverParameterList()            val testingObservedValueList = ArrayList<ObservedParameterModel>()            if (model.label == Configs.LBL_VTE || model.label == Configs.LBL_VTI) {                observedValueList.filter { it.label == LBL_VTE || it.label == LBL_VTI }                    .forEach { testingObservedValueList.add(it) }                onSwap(model, testingObservedValueList[0])            } else {                observedValueList.filter { it.label != LBL_VTE && it.label != LBL_VTI }                    .forEach { testingObservedValueList.add(it) }                swappableRecyclerView.layoutManager = LinearLayoutManager(this)                swappableAdapter = SwappableAdapter(                    testingObservedValueList, model, this                )                swappableRecyclerView.adapter = swappableAdapter                swappableLayout.visibility = View.VISIBLE                selectedTiles.forEach { it.isSelected = false }                selectedTiles[position].isSelected = true;                primaryObservedParameterAdapter?.notifyItemChanged(position)                primaryObservedParameterAdapter?.notifyDataSetChanged()                hideKnobViews()                // select first element                swappableAdapter?.setSelection(0)            }        }    }    private var observeredParameterClickIndex = 0    private var swapableAdapterClickIndex = 0    // runs after selection and swap is completed    @SuppressLint("NotifyDataSetChanged")    override fun onSwap(        containerModel: ObservedParameterModel, desiredModel: ObservedParameterModel    ) {        Log.i("vlaue_osdada", "onSwap")        val desiredModelIndex = observedValueList.indexOf(desiredModel)        val containerModelIndex = selectedTiles.indexOf(containerModel)        observeredParameterClickIndex = containerModelIndex        swapableAdapterClickIndex = desiredModelIndex        Log.i("vlaue_osdada", "$desiredModelIndex --- $containerModelIndex")        if (desiredModelIndex < 0 || containerModelIndex < 0) {            return        }        Log.i("vlaue_osdada", swappableAdapter.toString())        swappableAdapter?.setSelection(desiredModelIndex)        swapAndCloseSwappableLayout()    }    @SuppressLint("NotifyDataSetChanged")    private fun closeSwappableLayout() {        swappableLayout.visibility = View.GONE // ToDo: Add to all layout of XMl        observedValueList.forEach {            it.isSelectedAsSwappable = false            it.isSelected = false        }        swappableAdapter?.notifyDataSetChanged()    }    @SuppressLint("NotifyDataSetChanged")    private fun swapAndCloseSwappableLayout() {        Log.i("vlaue_osdada", "swapAndCloseSwappableLayout")        swappableLayout.visibility = View.GONE // ToDo: Add to all layout of XMl        observedValueList.forEach {            it.isSelectedAsSwappable = false            it.isSelected = false        }        swappableAdapter?.notifyDataSetChanged()        if ((observeredParameterClickIndex < selectedTiles.size || observeredParameterClickIndex >= 0) && (swapableAdapterClickIndex < observedValueList.size || swapableAdapterClickIndex >= 0)) {            Log.i("value_swappable_list", "in else - $observeredParameterClickIndex")            var tempData = selectedTiles[observeredParameterClickIndex]            selectedTiles[observeredParameterClickIndex] =                observedValueList[swapableAdapterClickIndex]            observedValueList[swapableAdapterClickIndex] = tempData            primaryObservedParameterAdapter?.notifyItemChanged(observeredParameterClickIndex)            Log.i("value_swappable_list", "in else - ${tempData.label}")        }    }    private fun upDateList(        observedParameterList: List<ObservedParameterModel>,        swappableAdapterList: List<ObservedParameterModel>    ): List<ObservedParameterModel> {        val list: MutableList<ObservedParameterModel> = observedParameterList.toMutableList()        val listSwappable: MutableList<ObservedParameterModel> =            swappableAdapterList.toMutableList()        listSwappable.removeAll(list)        return listSwappable.toList()    }    override fun onClick(position: Int) {        Log.i("asdawd12313", position.toString())        when (position) {            0 -> {                val i = Intent(IntentFactory.ACTION_MUTE_UNMUTE)                sendBroadcast(i)            }            1 -> {                val i = Intent(IntentFactory.ACTION_NEBULISER)                sendBroadcast(i)            }            2 -> {                val i = Intent(IntentFactory.ACTION_OXYGEN_100)                sendBroadcast(i)            }            3 -> {                val i = Intent(IntentFactory.ACTION_INSPIRATORY_HOLD)                sendBroadcast(i)            }            4 -> {                val i = Intent(IntentFactory.ACTION_EXPIRATORY_HOLD)                sendBroadcast(i)            }            5 -> {                val i = Intent(IntentFactory.ACTION_MANUAL_BREATH)                sendBroadcast(i)            }            6 -> {                val i = Intent(IntentFactory.ACTION_HOME)                sendBroadcast(i)            }            7 -> {                if (!isLocked) {                    layoutFreezeData.visibility = View.GONE                    showSystemFragment()                } else {                    DialogBoxFactory.dismissDialogs()                    DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)                }            }            8 -> {                if (!isLocked) {                    layoutFreezeData.visibility = View.GONE                    showSystemFragment()                } else {                    DialogBoxFactory.dismissDialogs()                    DialogBoxFactory.showSystemLockDialog(this@DashBoardActivity)                }            }            9 -> {                val i = Intent(IntentFactory.ACTION_LOCK)                sendBroadcast(i)            }        }    }}